@rest_api_bp.route("/v1/memory/buckets", methods=["GET"])
async def memory_buckets():
    """The two Workspace 'instances' for Agent Memory: Local (this agent's own, profile-scoped)
    + Global (shared across all the user's agents). Drives the standard component section."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"error": "Authentication required"}), 401
    try:
        from components.builtin.memory.store import MemoryStore
        from trusted_data_agent.core.config_manager import get_config_manager
        profile_id = request.args.get("profile_id") or None
        items = MemoryStore().list_items(user_uuid, include_inactive=True)
        local = [i for i in items if i.profile_id and i.profile_id == profile_id]
        shared = [i for i in items if not i.profile_id]
        tag = None
        if profile_id:
            p = get_config_manager().get_profile(profile_id, user_uuid) or {}
            tag = p.get("tag")
        buckets = [
            {"key": "local", "label": f"Local memory (@{tag})" if tag else "Local memory",
             "owner": "local", "profile_id": profile_id, "profile_tag": tag, "count": len(local)},
            {"key": "global", "label": "Global memory", "owner": "global",
             "profile_id": None, "count": len(shared)},
        ]
        return jsonify({"buckets": buckets})
    except Exception as e:
        app_logger.warning(f"[memory] buckets failed: {e}")
        return jsonify({"buckets": []}), 200


@rest_api_bp.route("/v1/memory/owners", methods=["GET"])
async def memory_owners():
    """All selectable memory owners for the manager canvas: Global (shared) + every agent
    (profile) that has memory OR has the memory component enabled, with item counts + IFOC
    type for colouring. ``?active_profile_id=`` marks the active agent."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"error": "Authentication required"}), 401
    active_id = request.args.get("active_profile_id") or None
    try:
        # Off the event loop (synchronous store read + a component-enablement check per
        # profile) — the Anatomy page requests this beside six other reads.
        owners = await asyncio.to_thread(_memory_owners_sync, user_uuid, active_id)
        return jsonify({"owners": owners})
    except Exception as e:
        app_logger.warning(f"[memory] owners failed: {e}")
        return jsonify({"owners": []}), 200


def _memory_owners_sync(user_uuid, active_id):
    with sqlite_util.reuse_connections():
        from components.builtin.memory.store import MemoryStore
        from components.builtin.memory.adapter import memory_component_enabled
        from trusted_data_agent.core.config_manager import get_config_manager
        items = MemoryStore().list_items(user_uuid, include_inactive=True)
        counts = {}
        for it in items:
            counts[it.profile_id] = counts.get(it.profile_id, 0) + 1  # None key = global

        profiles = get_config_manager().get_profiles(user_uuid) or []
        owners = [{
            "key": "global", "label": "Global", "owner": "global",
            "profile_id": None, "count": counts.get(None, 0), "is_active": False,
        }]
        for p in profiles:
            pid = p.get("id")
            ptype = p.get("profile_type", "tool_enabled")
            has_items = counts.get(pid, 0) > 0
            enabled = False
            try:
                enabled = memory_component_enabled(p, ptype, user_uuid)
            except Exception:
                enabled = False
            if not (has_items or enabled or pid == active_id):
                continue
            owners.append({
                "key": pid, "label": p.get("tag") or pid, "owner": "agent",
                "profile_id": pid, "profile_tag": p.get("tag"), "profile_type": ptype,
                "color": p.get("color"), "count": counts.get(pid, 0),
                "is_active": pid == active_id, "enabled": enabled,
            })
        return owners


@rest_api_bp.route("/v1/memory/recall-preview", methods=["POST"])
async def memory_recall_preview():
    """Transparency: preview what WOULD be recalled for a query+profile (0-token, deterministic)."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"error": "Authentication required"}), 401
    try:
        from components.builtin.memory import runtime
        data = await request.get_json() or {}
        profile_id = data.get("profile_id")
        from trusted_data_agent.core.config_manager import get_config_manager
        profile = get_config_manager().get_profile(profile_id, user_uuid) if profile_id else {}
        profile = profile or {}
        result, block = runtime.recall_for_turn(
            user_uuid=user_uuid, profile=profile,
            profile_type=profile.get("profile_type", "tool_enabled"),
            query=data.get("query", ""), budget_tokens=2000)
        return jsonify({"items": [it.to_dict() for it in result.items],
                        "count": result.count, "considered": result.considered,
                        "scope": result.scope, "block": block})
    except Exception as e:
        app_logger.warning(f"[memory] recall-preview failed: {e}")
        return jsonify({"items": [], "count": 0, "block": ""}), 200


@rest_api_bp.route("/v1/sessions/<session_id>/query", methods=["POST"])
async def execute_query(session_id: str):
    """Submits a query to a session and starts a background task *for the requesting user*."""
    # --- MODIFICATION START: Get User UUID ---
    user_uuid = _get_user_uuid_from_request()
    # --- MODIFICATION END ---

    data = dict(await request.get_json() or {})
    data.pop("turn_relation", None)   # internal only — the lineage endpoints set it
    # PROP-011: the re-entry binding is internal — the answer route sets it, and the flow
    # engine resuming a paused node carries it under an INTERNAL token; a client token never may
    if not _request_is_internal():
        data.pop("input_answer", None)
        data.pop("display_message", None)
    # PROP-011: a client that declares it can read the interrupted state gets it; every other
    # client sees `complete` with the question as the answer and `input_required: true` beside it
    _acc = str(request.headers.get("X-Uderia-Accepts") or "").lower()
    data["_accepts_input_required"] = "input_required" in _acc
    return await _start_query_task(session_id, user_uuid, data)


async def _start_query_task(session_id: str, user_uuid: str, data: dict):
    """The ONE task starter behind `/query` and the S8 lineage endpoints (regenerate · edit):
    validates the session + the effective profile, registers the background task, wires the
    event/notification plumbing and returns the 202. `data["turn_relation"]` (internal —
    never read from a client body) makes the turn a sibling or a branch head."""
    prompt = data.get("prompt")
    turn_relation = data.get("turn_relation") if isinstance(data.get("turn_relation"), dict) else None
    # PROP-011 re-entry (internal — set by input_resume.accept through the answer route, never a
    # client body): the structured block is the prompt, the person's line is what they see.
    input_answer = data.get("input_answer") if isinstance(data.get("input_answer"), dict) else None
    display_message = data.get("display_message") if input_answer else None
    accepts_input_required = bool(data.get("_accepts_input_required")) or bool(
        getattr(APP_CONFIG, "INPUT_REQUIRED_STATE_DEFAULT", False))
    if not prompt and not turn_relation:
        return jsonify({"error": "The 'prompt' field is required."}), 400

    # Optional MCP prompt execution (same as UI resource panel invoke_prompt_stream)
    active_prompt_name = data.get("prompt_name")        # MCP prompt name (e.g., "base_tableBusinessDesc")
    prompt_arguments = data.get("prompt_arguments")      # Dict of prompt arguments (e.g., {"database_name": "mydb"})

    # Optional file attachments (uploaded via /api/v1/chat/upload)
    attachments = data.get("attachments")  # [{file_id, filename, ...}]

    # Post-processing extensions [{"name": "json", "param": null}]
    extension_specs = data.get("extensions")

    # Pre-processing skills [{"name": "sql-expert", "param": "strict"}]
    skill_specs = data.get("skills")

    # Canvas bidirectional context {title, language, content, modified}
    canvas_context = data.get("canvas_context")

    # Orchestration origin: the flow engine posts source="flow" to mark a
    # flow-driven turn. That is an ORIGIN, not a transport — the transport is
    # still a REST call — so we split it: the turn stays source='rest' (Rest Call
    # tag) and carries origin='flow' (Flow tag). 'genie' is auto-detected
    # server-side in run_agent_execution from the profile type, not from the body.
    _query_origin = ("flow" if data.get("source") == "flow"
                     else "ask" if data.get("source") == "ask"   # PROP-011: asked by another agent (unattended)
                     else None)

    # --- MODIFICATION START: Validate session for this user ---
    _query_session_data = await session_manager.get_session(user_uuid, session_id)
    if not _query_session_data:
        app_logger.warning(f"REST API: Session '{session_id}' not found for user '{user_uuid}'.")
        return jsonify({"error": f"Session '{session_id}' not found."}), 404
    # --- MODIFICATION END ---

    # --- NEW: Switch to profile context for query execution (with optional override) ---
    from trusted_data_agent.core.config_manager import get_config_manager
    from trusted_data_agent.core.configuration_service import switch_profile_context

    config_manager = get_config_manager()

    # Allow optional profile_id parameter; defaults to user's default profile
    profile_id_override = data.get("profile_id")
    profile_id_to_use = profile_id_override or config_manager.get_default_profile_id(user_uuid)

    # --- REST activation firewall: the effective profile (default OR @TAG override) must be
    # activated (all tests passed). Rejects an unactivated/untested profile up front with an honest
    # error instead of letting it fail deep in the planner. Genie SLAVE sessions are exempt: a
    # genie coordinator (itself activated) drives its validated child profiles internally via this
    # same endpoint (genie_coordinator posts to /query), and those children are not required to be
    # independently activated. ---
    _is_genie_slave_session = bool(
        (_query_session_data or {}).get("genie_metadata", {}).get("is_genie_slave")
    )
    if not _is_genie_slave_session:
        _fw_ok, _fw_err = _assert_profile_activated(profile_id_to_use, user_uuid)
        if not _fw_ok:
            app_logger.warning(f"REST firewall: blocked query on non-activated profile {profile_id_to_use}: {_fw_err.get('code')}")
            return jsonify(_fw_err), 403

    # Session primer flag - marks messages as initialization
    is_session_primer = data.get("is_session_primer", False)

    if profile_id_to_use:
        # Activate profile context to ensure correct LLM and profile badges are associated
        profile_context = await switch_profile_context(profile_id_to_use, user_uuid, validate_llm=False)
        if "error" in profile_context:
            app_logger.warning(f"REST API: Could not activate profile {profile_id_to_use} for query execution: {profile_context.get('error')}")
    # --- END NEW ---

    # PROP-011: the answer to a REST question continues under the SAME task id (the client that
    # asked keeps polling it); any other turn is a new task.
    task_id = (str(data.get("_resume_task_id")) if data.get("_resume_task_id")
               and str(data.get("_resume_task_id")) in (APP_STATE.get("background_tasks") or {})
               else generate_task_id())

    # Initialize the task state (a resumed task's record is read before the prune, which may
    # drop a settled record past the retention window — then the continuation is a new task)
    _prev_task = (APP_STATE.get("background_tasks") or {}).get(task_id) or {}
    from trusted_data_agent.core.config import prune_background_tasks
    prune_background_tasks()
    APP_STATE.setdefault("background_tasks", {})[task_id] = {
        "task_id": task_id,
        "user_uuid": user_uuid, # Store the user UUID with the task
        "session_id": session_id, # Store session ID for reference
        "profile_id_override": profile_id_override, # Track which profile was used for this query
        "status": "pending",
        "last_updated": datetime.now(timezone.utc).isoformat(),
        "events": list(_prev_task.get("events") or []),   # a resumed task keeps its history
        "intermediate_data": list(_prev_task.get("intermediate_data") or []),
        "result": None,
        "accepts_input_required": accepts_input_required or bool(_prev_task.get("accepts_input_required")),
        **({"resumed_from": _prev_task.get("result", {}).get("input_request", {}).get("id")}
           if isinstance(_prev_task.get("result"), dict) and _prev_task.get("result", {}).get("input_request") else {}),
    }

    async def event_handler(event_data, event_type):
        """This handler is called by the execution service for each event."""
        task_status_dict = APP_STATE["background_tasks"].get(task_id)
        sanitized_event_data = _sanitize_for_json(event_data)

        # 1. Update the persistent task state (for polling clients)
        if task_status_dict:
            task_status_dict["events"].append({
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "event_data": sanitized_event_data,
                "event_type": event_type
            })
            if event_type == "tool_result" and isinstance(sanitized_event_data, dict):
                details = sanitized_event_data.get("details", {})
                if isinstance(details, dict) and details.get("status") == "success" and "results" in details:
                    task_status_dict["intermediate_data"].append({
                        "tool_name": details.get("metadata", {}).get("tool_name", "unknown_tool"),
                        "data": details["results"]
                    })
            task_status_dict["last_updated"] = datetime.now(timezone.utc).isoformat()

        # 2. Create and send a canonical event to the UI notification stream
        notification_queues = APP_STATE.get("notification_queues", {}).get(user_uuid, set())
        if notification_queues:
            try:
                # --- MODIFICATION START: Build canonical_event directly ---
                # No need to format/re-parse. Just build the dict.
                canonical_event = copy.deepcopy(sanitized_event_data)
                # Preserve original event type (e.g. 'plan_generated', 'conversation_agent_start')
                # if present; only fall back to SSE event_type when the event has no type field.
                # The executor embeds the real type in event_data['type']. The SSE event_type
                # is just the wrapper type (often 'notification' or None) and must not overwrite it.
                if 'type' not in canonical_event:
                    canonical_event['type'] = event_type or 'notification'
                # --- MODIFICATION END ---
                    
                # --- MODIFICATION START: Handle session_name_update as a top-level event ---
                # --- MODIFICATION START: Handle status_indicator_update directly ---
                if event_type == "status_indicator_update":
                    notification = {
                        "type": "status_indicator_update",
                        "payload": canonical_event # canonical_event already contains target and state
                    }
                # --- MODIFICATION END ---
                elif event_type == "session_name_update":
                    notification = {
                        "type": "session_name_update",
                        "payload": canonical_event # Payload already contains session_id and newName
                    }
                else:
                    notification = {
                        "type": "rest_task_update",
                        "payload": {
                            "task_id": task_id,
                            "session_id": session_id,
                            "event": canonical_event
                        }
                    }
                # --- MODIFICATION END ---
                for queue in notification_queues:
                    asyncio.create_task(queue.put(notification))

            except Exception as e:
                app_logger.error(f"Failed to format or send canonical event for REST task {task_id}: {e}", exc_info=True)

    async def background_wrapper():
        """Wraps the execution to handle context, final state updates, and notifications."""
        task_status_dict = APP_STATE["background_tasks"].get(task_id)
        final_result_payload = None
        try:
            if task_status_dict: task_status_dict["status"] = "processing"

            final_result_payload = await execution_service.run_agent_execution(
                user_uuid=user_uuid,
                session_id=session_id,
                user_input=prompt,
                event_handler=event_handler,
                active_prompt_name=active_prompt_name,  # MCP prompt name (from resource panel)
                prompt_arguments=prompt_arguments,      # MCP prompt arguments
                source='prompt_library' if active_prompt_name else 'rest',
                task_id=task_id, # Pass the task_id here
                profile_override_id=profile_id_override, # Pass profile override for per-message tracking
                is_session_primer=is_session_primer, # Pass session primer flag
                attachments=attachments,  # File attachments (uploaded via /api/v1/chat/upload)
                extension_specs=extension_specs,  # Post-processing extensions
                skill_specs=skill_specs,  # Pre-processing skills
                canvas_context=canvas_context,  # Canvas bidirectional context
                origin=_query_origin,  # Orchestration origin ('flow' for flow-driven turns)
                turn_relation=turn_relation,  # S8: a sibling or a branch head; None = ordinary
                display_message=display_message,  # PROP-011: the person's line on a re-entry
                input_answer=input_answer,  # PROP-011: the answer the ledger binds on a re-entry
            )

            if task_status_dict:
                _status, _result = _task_outcome(final_result_payload, task_status_dict.get("events"),
                                                 accepts_input_required=bool(task_status_dict.get("accepts_input_required")))
                task_status_dict["status"] = _status
                task_status_dict["result"] = _sanitize_for_json(_result)
                task_status_dict["last_updated"] = datetime.now(timezone.utc).isoformat()
                # Promote extension_results to top-level for easy n8n/Flowise access
                if final_result_payload and isinstance(final_result_payload, dict):
                    ext_results = final_result_payload.get("extension_results")
                    if ext_results:
                        task_status_dict["extension_results"] = ext_results

        except asyncio.CancelledError:
            app_logger.info(f"REST background task {task_id} (user {user_uuid}) was cancelled.")
            if task_status_dict:
                task_status_dict["status"] = "cancelled"
                task_status_dict["result"] = {"message": "Task cancelled by user."}
                task_status_dict["last_updated"] = datetime.now(timezone.utc).isoformat()
        except Exception as e:
            app_logger.error(f"Background task {task_id} (user {user_uuid}) failed: {e}", exc_info=True)
            if task_status_dict:
                task_status_dict["status"] = "error"
                task_status_dict["result"] = {"error": str(e)}
                task_status_dict["last_updated"] = datetime.now(timezone.utc).isoformat()
        finally:
            # Remove from ACTIVE tasks registry
            if task_id in APP_STATE.get("active_tasks", {}):
                del APP_STATE["active_tasks"][task_id]

            # Send final notification to UI clients on success — and on a turn that stopped to
            # ask (PROP-011): the chat renders the question card from the same notice
            if final_result_payload and task_status_dict and task_status_dict.get("status") in ("complete", "input_required"):
                notification_queues = APP_STATE.get("notification_queues", {}).get(user_uuid, set())
                if notification_queues:
                    # Get the session to retrieve profile tag
                    profile_tag = None
                    try:
                        session_data = await session_manager.get_session(user_uuid, session_id)
                        profile_tag = session_data.get("profile_tag") if session_data else None
                    except Exception as e:
                        app_logger.warning(f"Could not retrieve profile tag for session {session_id}: {e}")
                    
                    completion_notification = {
                        "type": "rest_task_complete",
                        "payload": {
                            "task_id": task_id,
                            "session_id": session_id,
                            "turn_id": final_result_payload.get("turn_id"),
                            "user_input": prompt,
                            "final_answer": final_result_payload.get("final_answer"),
                            "profile_tag": profile_tag,
                            # Orchestration origin (flow/genie) — server-authoritative,
                            # so the live REST render tags the turn like the persisted one.
                            "origin": final_result_payload.get("origin"),
                            "extension_specs": extension_specs,
                            "skill_specs": skill_specs,
                            # S8: the relation the turn ran under — a client re-reads the
                            # session's lineage instead of appending a bubble
                            "lineage": final_result_payload.get("lineage"),
                            # PROP-011: the question the turn stopped for (with the owner's binding)
                            "input_request": final_result_payload.get("input_request"),
                        }
                    }
                    for queue in notification_queues:
                        asyncio.create_task(queue.put(completion_notification))

            app_logger.info(f"Background task {task_id} (user {user_uuid}) finished with status: {task_status_dict.get('status', 'unknown') if task_status_dict else 'unknown'}")

    # Start the agent execution in the background
    task_object = asyncio.create_task(background_wrapper())
    # Store the actual task object for potential cancellation (uses task_id)
    APP_STATE.setdefault("active_tasks", {})[task_id] = task_object

    status_url = f"/api/v1/tasks/{task_id}"

    return jsonify({"task_id": task_id, "status_url": status_url}), 202

# ── S8 · Regenerate as an Experiment — sibling turns + edit branches ──────────────────────────
# Every act here is append-only over the session record (a turn is never removed or rewritten);
# what moves is which sibling stands for a question and which branch the view follows. The
# switch (`TURN_LINEAGE`) gates all five endpoints — off ⇒ 404, the same as "does not exist".

def _lineage_gate():
    from trusted_data_agent.agent import turn_lineage as _tl
    if not _tl.enabled():
        return jsonify({"error": "turn lineage is not enabled on this deployment", "code": "turn_lineage_disabled"}), 404
    return None


async def _lineage_start(session_id: str, kind: str, of: int, body: dict):
    """Validate against the session FIRST (a 400 with the reason, not a task that fails later),
    then start the ordinary query task with the relation attached."""
    from trusted_data_agent.agent import turn_lineage as _tl
    user_uuid = _get_user_uuid_from_request()
    session_data = await session_manager.get_session(user_uuid, session_id)
    if not session_data:
        return jsonify({"error": f"Session '{session_id}' not found."}), 404
    relation = {"kind": kind, "of": of}
    if kind == "edit":
        relation["prompt"] = (body or {}).get("prompt")
    try:
        rel = _tl.build_relation(session_data, relation)
    except ValueError as ve:
        return jsonify({"error": str(ve), "code": "invalid_lineage_request"}), 400
    data = {"prompt": rel.query, "turn_relation": relation}
    # the profile: the caller's choice, else the turn's own agent (a regenerate "with another
    # model" is a regenerate under another profile — the platform's unit of model choice)
    pid = (body or {}).get("profile_id")
    if not pid and kind == "regenerate":
        root_rec = _tl.find_turn(session_data, rel.root) or {}
        tag = root_rec.get("profile_tag")
        if tag:
            from trusted_data_agent.core.config_manager import get_config_manager
            _p = next((p for p in (get_config_manager().get_profiles(user_uuid) or []) if p.get("tag") == tag), None)
            if _p:
                pid = _p.get("id")
    if pid:
        data["profile_id"] = pid
    for k in ("attachments", "extensions", "skills", "canvas_context"):
        if (body or {}).get(k) is not None:
            data[k] = body[k]
    resp = await _start_query_task(session_id, user_uuid, data)
    return resp


@rest_api_bp.route("/v1/sessions/<session_id>/turns/<int:turn>/regenerate", methods=["POST"])
async def regenerate_turn(session_id: str, turn: int):
    """S8 — run the turn's question again as a SCORED SIBLING (same or another profile). The new
    turn is adopted on arrival; `adopt` switches. Body: {profile_id?, attachments?, extensions?, skills?}."""
    g = _lineage_gate()
    if g: return g
    body = await request.get_json(silent=True) or {}
    return await _lineage_start(session_id, "regenerate", turn, body)


@rest_api_bp.route("/v1/sessions/<session_id>/turns/<int:turn>/edit", methods=["POST"])
async def edit_turn(session_id: str, turn: int):
    """S8 — edit-and-resend as a BRANCH: the new text becomes a branch head at `turn`; the turns it
    displaces stay in the record (switch back with `/branches/<head>/activate`). Body: {prompt, profile_id?}."""
    g = _lineage_gate()
    if g: return g
    body = await request.get_json(silent=True) or {}
    return await _lineage_start(session_id, "edit", turn, body)


@rest_api_bp.route("/v1/sessions/<session_id>/turns/<int:turn>/adopt", methods=["POST"])
async def adopt_turn(session_id: str, turn: int):
    """S8 — make `turn` the sibling the conversation continues from (append-only: the others stay)."""
    g = _lineage_gate()
    if g: return g
    from trusted_data_agent.agent import turn_lineage as _tl
    user_uuid = _get_user_uuid_from_request()
    try:
        async with session_manager._session_transaction(user_uuid, session_id) as session_data:
            if not session_data:
                return jsonify({"error": f"Session '{session_id}' not found."}), 404
            if not _tl.is_sibling_set(session_data, _tl.sibling_root(session_data, turn)):
                return jsonify({"error": f"turn {turn} has no siblings to adopt among", "code": "not_a_sibling_set"}), 400
            moved = _tl.apply_adoption(session_data, turn)
            payload = _tl.lineage_payload(session_data)
    except ValueError as ve:
        return jsonify({"error": str(ve), "code": "invalid_lineage_request"}), 400
    return jsonify({"status": "success", "adopted": moved, "lineage": payload}), 200


@rest_api_bp.route("/v1/sessions/<session_id>/branches/<int:head>/activate", methods=["POST"])
async def activate_branch(session_id: str, head: int):
    """S8 — follow a branch (0 = the root branch). Only the turns whose membership changes move."""
    g = _lineage_gate()
    if g: return g
    from trusted_data_agent.agent import turn_lineage as _tl
    user_uuid = _get_user_uuid_from_request()
    try:
        async with session_manager._session_transaction(user_uuid, session_id) as session_data:
            if not session_data:
                return jsonify({"error": f"Session '{session_id}' not found."}), 404
            moved = _tl.switch_branch(session_data, head)
            payload = _tl.lineage_payload(session_data)
    except ValueError as ve:
        return jsonify({"error": str(ve), "code": "invalid_lineage_request"}), 400
    return jsonify({"status": "success", "branch": moved, "lineage": payload}), 200


@rest_api_bp.route("/v1/sessions/<session_id>/lineage", methods=["GET"])
async def get_session_lineage(session_id: str):
    """S8 — the session's sibling sets and branches as the reader sees them (null when nothing
    ever regenerated or branched)."""
    g = _lineage_gate()
    if g: return g
    from trusted_data_agent.agent import turn_lineage as _tl
    user_uuid = _get_user_uuid_from_request()
    session_data = await session_manager.read_session(user_uuid, session_id)
