@rest_api_bp.route("/v1/llm/provider-health", methods=["GET"])
@operation("llm.provider_health", effect="read", scope="instance",
           summary="Each LLM provider's circuit breaker on this deployment: its state and recent failures")
async def get_llm_provider_health():
    """S4 — the per-provider circuit breakers (process-wide): state, consecutive failures, the
    open period and the seconds until the next probe. Read by the header strip on open so a
    reload never shows a stale reading; `degraded` is the subset the strip renders. Authenticated
    (the estate's provider health is operational state, not public), never user-specific."""
    try:
        user_uuid = _get_user_uuid_from_request()
        if not user_uuid:
            return jsonify({"status": "error", "message": "Authentication required"}), 401
        from trusted_data_agent.core import provider_health as _ph
        from trusted_data_agent.core.config import APP_CONFIG
        snaps = _ph.snapshot()
        return jsonify({"status": "success", "enabled": bool(getattr(APP_CONFIG, "RESILIENCE_ENVELOPE", False)),
                        "providers": snaps, "degraded": [s for s in snaps if s.get("degraded")]})
    except Exception as e:
        app_logger.error(f"provider-health: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


def _litellm_context_limit(provider: str, model: str):
    """(max input tokens, source) for a model from LiteLLM's map; 128K default."""
    try:
        import litellm
        model_key = f"{provider}/{model}" if provider else model
        model_info = litellm.model_cost.get(model_key) or litellm.model_cost.get(model or "")
        if model_info:
            return (model_info.get("max_input_tokens") or model_info.get("max_tokens") or 128_000,
                    "litellm")
    except Exception:
        pass
    return 128_000, "default"


@rest_api_bp.route("/v1/llm/configurations/<config_id>/context-limit", methods=["GET"])
@operation("llm.configurations_context_limit", effect="read", scope="own",
           summary="The model's maximum context window for an LLM configuration",
           path={"config_id": "the LLM configuration's id"})
async def get_llm_context_limit(config_id: str):
    """Get the model's maximum context window size for the given LLM configuration."""
    try:
        user_uuid = _get_user_uuid_from_request()
        if not user_uuid:
            return jsonify({"status": "error", "message": "Authentication required"}), 401

        from trusted_data_agent.core.config_manager import get_config_manager
        config_manager = get_config_manager()

        configurations = config_manager.get_llm_configurations(user_uuid)
        config = next((c for c in configurations if c.get("id") == config_id), None)
        if not config:
            return jsonify({"status": "error", "message": "LLM configuration not found"}), 404

        provider = config.get("provider", "")
        model = config.get("model", "")

        # Off the event loop: the FIRST call in a process pays `import litellm` (2.5 s
        # locally, ~9 s on the production host), and inline that froze every concurrent
        # request during login — this endpoint is fetched by the resource panel at boot.
        max_tokens, source = await asyncio.to_thread(_litellm_context_limit, provider, model)

        return jsonify({
            "status": "success",
            "config_id": config_id,
            "provider": provider,
            "model": model,
            "max_context_tokens": max_tokens,
            "source": source
        }), 200

    except Exception as e:
        app_logger.error(f"Error getting context limit: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


