_IFOC_LABEL = {"llm_only": "Ideate", "rag_focused": "Focus", "tool_enabled": "Optimize", "genie": "Coordinate"}


async def _route_json(rv):
    """``(body, status)`` from a route handler's own return value."""
    resp, status = (rv[0], rv[1]) if isinstance(rv, tuple) else (rv, getattr(rv, "status_code", 200))
    try:
        body = await resp.get_json()
    except Exception:  # noqa: BLE001
        body = None
    return body if isinstance(body, dict) else {}, int(status or 200)


@rest_api_bp.route("/v1/profiles/<profile_id>/overview", methods=["GET"])
@operation("profiles.overview", effect="read", scope="own",
           summary=("One agent in one answer: its class, model and data source, the knowledge repositories it "
                    "answers from, the experts it consults, the components and skills in effect, its trust state "
                    "with what decides it, and whether it is the default or open to REST use"),
           path={"profile_id": "the agent's (profile's) id"})
async def get_profile_overview(profile_id: str):
    """One agent, composed from the routes that each answer one part of it — the components,
    skills and trust routes are CALLED here, never re-derived, so every figure is exactly what
    those routes answer. One call instead of four: a model holding a playbook that asked for
    four calls stopped after the first (the platform live probe, 2026-11-01)."""
    try:
        user_uuid = _get_user_uuid_from_request()
        if not user_uuid:
            return jsonify({"error": "Authentication required"}), 401
        from trusted_data_agent.core.config_manager import get_config_manager
        cm = get_config_manager()
        profile = cm.get_profile(profile_id, user_uuid)
        if not profile:
            return jsonify({"error": "Profile not found"}), 404

        from trusted_data_agent.api.skills_routes import get_profile_skills
        from trusted_data_agent.api.trust_routes import get_agent_trust
        comps, comps_status = await _route_json(await get_profile_components(profile_id))
        skills, skills_status = await _route_json(await get_profile_skills(profile_id))
        trust, trust_status = await _route_json(await get_agent_trust(profile_id))

        llm = next((c for c in (cm.get_llm_configurations(user_uuid) or [])
                    if c.get("id") == profile.get("llmConfigurationId")), None)
        from trusted_data_agent.core.agent_mcp_servers import primary_of
        _primary = primary_of(profile)
        server = next((m for m in (cm.get_mcp_servers(user_uuid) or []) if m.get("id") == _primary), None) \
            if _primary else None
        t = (trust.get("trust") or {}) if trust_status == 200 else {}
        # What it answers from and whom it consults — named, never ids (the builder composes
        # these; an overview that showed only ids would send a model back to look each one up).
        kc = profile.get("knowledgeConfig") or {}
        knowledge = None
        if kc.get("enabled") and kc.get("collections"):
            from trusted_data_agent.core.collection_db import get_collection_db
            names = {str(c.get("id")): c.get("name")
                     for c in (get_collection_db().get_all_collections(user_id=user_uuid) or [])}
            ids = [str(c.get("id")) for c in kc["collections"] if isinstance(c, dict) and c.get("id") is not None]
            knowledge = {"repositories": [names.get(i) or f"repository {i} (not yours)" for i in ids],
                         **{k: kc[k] for k in ("minRelevanceScore", "maxDocs", "maxTokens") if k in kc}}
        experts = None
        if profile.get("profile_type") == "genie":
            tags = {p.get("id"): p.get("tag") for p in (cm.get_profiles(user_uuid) or [])}
            experts = [("@" + tags[i]) if tags.get(i) else f"{i} (no longer an agent of yours)"
                       for i in ((profile.get("genieConfig") or {}).get("slaveProfiles") or [])]
        cwt = None
        if profile.get("contextWindowTypeId"):
            cwt = next((c.get("name") for c in (cm.get_context_window_types(user_uuid) or [])
                        if c.get("id") == profile.get("contextWindowTypeId")), profile.get("contextWindowTypeId"))
        deciding = [{"label": i.get("label"), "kind": i.get("kind"), "state": i.get("state")}
                    for i in (t.get("ingredients") or []) if i.get("state") not in (None, "trusted")]
        enabled = [c for c in (comps.get("components") or []) if c.get("profile_enabled")]
        skill_rows = skills.get("skills") or []
        out = {
            "id": profile_id,
            "tag": profile.get("tag"),
            "name": profile.get("name"),
            "class": _IFOC_LABEL.get(profile.get("profile_type"), profile.get("profile_type")),
            "description": profile.get("description"),
            "model": ({"name": llm.get("name"), "provider": llm.get("provider"), "model": llm.get("model")}
                      if llm else None),
            "data_source": (server.get("name") if server else None),
            "knowledge": knowledge,
            "experts": experts,
            "context_window": cwt,
            "components": [c.get("display_name") or c.get("component_id") for c in enabled
                           if c.get("component_type") == "action"],
            "system_components": [c.get("display_name") or c.get("component_id") for c in enabled
                                  if c.get("component_type") != "action"],
            "skills": {"active": [s.get("name") or s.get("id") for s in skill_rows if s.get("active")],
                       "when_asked": [s.get("name") or s.get("id") for s in skill_rows
                                      if s.get("enabled") and not s.get("active")]},
            "trust": ({"state": t.get("state"), "deciding": deciding,
                       "blocking": [b.get("label") if isinstance(b, dict) else b for b in (t.get("blocking") or [])],
                       "deployment_drift": ((t.get("deployment") or {}).get("drift") or [])} if t else None),
            "default": cm.get_default_profile_id(user_uuid) == profile_id,
            "open_to_rest": profile_id in set(cm.get_active_for_consumption_profile_ids(user_uuid) or []),
        }
        unread = [n for n, st in (("components", comps_status), ("skills", skills_status), ("trust", trust_status)) if st != 200]
        if unread:
            out["not_read"] = unread   # a part that could not be read is named, never shown empty
        return jsonify(out), 200
    except Exception as e:
        app_logger.error(f"Failed to build the overview of {profile_id}: {e}", exc_info=True)
        return jsonify({"error": "Failed to build the agent overview."}), 500


def _profile_components_sync(user_uuid, profile, profile_type, component_config):
    """The per-component rows behind ``GET /v1/profiles/<id>/components`` (worker thread)."""
    from trusted_data_agent.components.manager import get_component_manager
    from trusted_data_agent.components import enablement
    from trusted_data_agent.components.settings import (
        get_component_settings,
        is_component_available,
    )
    with sqlite_util.reuse_connections():
        settings = get_component_settings()
        manager = get_component_manager()

        components = []
        for comp in manager.get_all_components():
            if not settings.get("user_components_enabled", True) and comp.source != "builtin":
                continue

            d = comp.to_api_dict()

            globally_disabled = not is_component_available(comp.component_id, user_uuid)

            prof_cfg = component_config.get(comp.component_id, {})
            # user_disabled = user explicitly set enabled:false in componentConfig
            user_disabled = prof_cfg.get("enabled") is False

            # THE one rule (components/enablement.py) — this view used to re-implement
            # the chain, and the copy omitted the per-user default step entirely.
            is_default_on = enablement.manifest_default(comp, profile_type)
            profile_enabled = enablement.decide(
                comp, profile,
                available=not globally_disabled,
                profile_type=profile_type,
            )

            intensity = prof_cfg.get("intensity") or comp.profile_defaults.get("default_intensity")

            d["globally_disabled"] = globally_disabled
            d["profile_enabled"] = profile_enabled
            d["user_disabled"] = user_disabled
            d["is_default_on"] = is_default_on
            # the vocabulary (resourceBadge.js): Auto = the platform holds the switch (no stored
            # entry — the agent follows the manifest default); active = in effect every turn
            # without being called (the manifest's acts_every_turn), always a subset of enabled
            d["auto"] = enablement.is_auto(comp, profile)
            d["acts_every_turn"] = enablement.acts_every_turn(comp)
            d["active"] = bool(profile_enabled and d["acts_every_turn"])
            d["intensity"] = intensity
            components.append(d)

        return components


@rest_api_bp.route("/v1/user/component-profile-defaults", methods=["GET"])
async def get_component_profile_defaults():
    """Return per-user component-profile-defaults dict {component_id: bool}."""
    try:
        user_uuid = _get_user_uuid_from_request()
        if not user_uuid:
            return jsonify({"error": "Authentication required"}), 401
        from trusted_data_agent.core.config_manager import get_config_manager
        config = get_config_manager().load_config(user_uuid)
        defaults = config.get("component_profile_defaults", {})
        return jsonify({"component_profile_defaults": defaults}), 200
    except Exception as e:
        app_logger.error(f"Failed to get component profile defaults: {e}", exc_info=True)
        return jsonify({"error": "Failed to get component profile defaults"}), 500


@rest_api_bp.route("/v1/user/component-profile-defaults", methods=["PUT"])
async def update_component_profile_defaults():
    """Update per-user component-profile-defaults. Body: {component_id: bool, ...}"""
    try:
        user_uuid = _get_user_uuid_from_request()
        if not user_uuid:
            return jsonify({"error": "Authentication required"}), 401
        body = await request.get_json()
        if not isinstance(body, dict):
            return jsonify({"error": "Expected a JSON object"}), 400
        # Validate: values must be booleans
        for k, v in body.items():
            if not isinstance(v, bool):
                return jsonify({"error": f"Value for '{k}' must be a boolean"}), 400
        from trusted_data_agent.core.config_manager import get_config_manager
        _cm = get_config_manager()
        config = _cm.load_config(user_uuid)
        existing = config.get("component_profile_defaults", {})
        existing.update(body)
        config["component_profile_defaults"] = existing
        _cm.save_config(config, user_uuid)
        return jsonify({"component_profile_defaults": existing}), 200
    except Exception as e:
        app_logger.error(f"Failed to update component profile defaults: {e}", exc_info=True)
        return jsonify({"error": "Failed to update component profile defaults"}), 500


@rest_api_bp.route("/v1/components", methods=["GET"])
@operation("components.list", effect="read", scope="instance",
           summary=("The components available on this deployment — capabilities such as charts, canvas, "
                    "dashboards, memory: what each component does, which classes it supports, whether it starts on"),
           query={"profile_type": Arg("string", "an agent class: adds whether each component starts on for it",
                                      enum=("llm_only", "rag_focused", "tool_enabled", "genie"))},
           summary_fields=("component_id", "display_name", "description"))
async def list_components():
    """
    List all installed components with status and governance filtering.
    Returns component list + governance settings for frontend enforcement.
    """
    try:
        user_uuid = _get_user_uuid_from_request()
        if not user_uuid:
            return jsonify({"error": "Authentication required"}), 401

        from trusted_data_agent.components import enablement
        from trusted_data_agent.components.manager import get_component_manager
        from trusted_data_agent.components.settings import (
            get_component_settings,
            is_component_available,
        )

        manager = get_component_manager()
        settings = get_component_settings()
        # Optional profile-type scoping: lets a caller (the profile editor creating a NEW
        # profile, which has no id yet) read a resolved default instead of deriving one.
        req_profile_type = (request.args.get("profile_type") or "").strip() or None

        # Per-user component profile defaults (which components start enabled on new profiles)
        from trusted_data_agent.core.config_manager import get_config_manager
        user_config = get_config_manager().load_config(user_uuid)
        user_comp_defaults = user_config.get("component_profile_defaults", {})

        components = []
        for comp in manager.get_all_components():
            # If user components disabled, hide non-builtin entirely
            if not settings.get("user_components_enabled", True) and comp.source != "builtin":
                continue
            d = comp.to_api_dict()
            # Effective access = global disabled list + per-user override for the requesting user
            d["globally_disabled"] = not is_component_available(comp.component_id, user_uuid)
            # Per-user profile default: the user's own setting, else "on for the profile
            # types this component supports". The retired `default_enabled` key was a
            # SECOND manifest default that contradicted `enabled_for` — see
            # docs/assessments/COMPONENT_ENABLEMENT_ASSESSMENT_2026-08.md.
            supports_any = _new_agent_default(d.get("profile_defaults"))
            d["user_profile_default_enabled"] = user_comp_defaults.get(
                comp.component_id, supports_any)
            # Profile-type-scoped resolution, so the profile editor reads a final answer
            # instead of deriving one. Only present when ?profile_type= is supplied.
            if req_profile_type:
                # the pure manifest default for the class — what an agent with no stored entry
                # (Auto) resolves to at runtime; the creation default below adds the user's own
                d["manifest_default"] = enablement.manifest_default(comp, req_profile_type)
                # the CREATION default for this class: the user's own choice first ("On for my
                # new agents"), else the manifest's new-agent declaration where it makes one
                # (`on_for_new_agents` — creation-only, signature-preserving), else the class
                # default an Auto entry follows. Unavailable (admin) is never on.
                if d["globally_disabled"]:
                    d["profile_enabled_default"] = False
                elif comp.component_id in user_comp_defaults:
                    d["profile_enabled_default"] = bool(user_comp_defaults[comp.component_id])
                elif "on_for_new_agents" in (comp.profile_defaults or {}):
                    d["profile_enabled_default"] = bool(comp.profile_defaults.get("on_for_new_agents")) and d["manifest_default"]
                else:
                    d["profile_enabled_default"] = d["manifest_default"]
            components.append(d)

        return jsonify({
            "components": components,
            "_settings": {
                "user_components_enabled": settings.get("user_components_enabled", True),
                "marketplace_enabled": settings.get("user_components_marketplace_enabled", True),
            },
        }), 200

    except Exception as e:
        app_logger.error(f"Failed to list components: {e}", exc_info=True)
        return jsonify({"error": "Failed to list components."}), 500


