# ─── Canvas Inline AI (M7) ───────────────────────────────────────────────────

@rest_api_bp.route("/v1/canvas/inline-ai", methods=["POST"])
async def canvas_inline_ai():
    """
    Lightweight LLM endpoint for canvas inline AI (M7).
    Modifies selected code based on user instruction.
    No planner/executor — direct LLM call with <2s latency.

    Request body:
    {
        "selected_code": "code the user selected",
        "instruction": "what to do with it",
        "full_content": "entire file content for context",
        "language": "python"
    }

    Returns:
    {
        "status": "success",
        "modified_code": "the replacement code",
        "input_tokens": 123,
        "output_tokens": 45
    }
    """
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401

    data = await request.get_json()
    selected_code = data.get("selected_code", "").strip()
    instruction = data.get("instruction", "").strip()
    full_content = data.get("full_content", "")
    language = data.get("language", "text")

    if not selected_code or not instruction:
        return jsonify({"status": "error", "message": "selected_code and instruction are required"}), 400

    llm_instance = APP_STATE.get("llm")
    if not llm_instance:
        return jsonify({"status": "error", "message": "LLM not initialized"}), 500

    system_prompt = (
        "You are an expert code editor. The user has selected a portion of code "
        "and wants you to modify ONLY that selection.\n\n"
        "RULES:\n"
        "- Output ONLY the replacement code — no explanations, no markdown fences, no commentary\n"
        "- Preserve the indentation level of the original selection\n"
        "- The replacement must integrate correctly with the surrounding code\n"
        "- If the instruction is unclear, make the most reasonable improvement\n"
        "- Do NOT include any text before or after the replacement code"
    )

    user_prompt = (
        f"Language: {language}\n\n"
        f"=== FULL FILE ===\n{full_content}\n=== END FILE ===\n\n"
        f"=== SELECTED CODE (to modify) ===\n{selected_code}\n=== END SELECTION ===\n\n"
        f"Instruction: {instruction}\n\n"
        f"Output ONLY the replacement for the selected code:"
    )

    try:
        modified_code, input_tokens, output_tokens, provider, model = await llm_handler.call_llm_api(
            llm_instance,
            user_prompt,
            user_uuid=user_uuid,
            session_id=None,
            dependencies={"STATE": APP_STATE, "CONFIG": APP_CONFIG},
            reason=f"Canvas inline AI: {instruction[:80]}",
            system_prompt_override=system_prompt,
            disabled_history=True,
            source="canvas_inline_ai",
        )

        # Strip markdown fences if LLM wraps in ```
        cleaned = modified_code.strip()
        if cleaned.startswith("```") and cleaned.endswith("```"):
            lines = cleaned.split("\n")
            cleaned = "\n".join(lines[1:-1])

        app_logger.info(
            f"[Canvas InlineAI] {instruction[:50]} | "
            f"{input_tokens} in / {output_tokens} out | {provider}/{model}"
        )

        return jsonify({
            "status": "success",
            "modified_code": cleaned,
            "input_tokens": input_tokens,
            "output_tokens": output_tokens,
        }), 200

    except Exception as e:
        app_logger.error(f"Canvas inline AI failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


# ─── Canvas Code Execution (M8.1) ─────────────────────────────────────────────

CANVAS_GRID_MAX_ROWS = 500   # the grid a canvas result panel renders; the text keeps every row


def _json_cell(v):
    """A grid cell the wire can carry: JSON scalars stay themselves, everything else
    (Decimal, date, bytes …) becomes its string."""
    return v if v is None or isinstance(v, (str, int, float, bool)) else str(v)


def _canvas_result_grid(result, code: str, creds: dict) -> dict:
    """The structured half of a canvas execution: the columns, at most CANVAS_GRID_MAX_ROWS
    rows, whether the DATABASE truncated the result, whether the GRID did, and the columns a
    view masks (dbcatalog.intelligence.masked_columns — the navigator's rule, not a copy)."""
    from trusted_data_agent.dbcatalog.intelligence import masked_columns, statement_tables
    from trusted_data_agent.dbcatalog.service import SQLGLOT_DIALECT
    cols = [str(c) for c in (result.columns or [])]
    rows = list(result.rows or [])
    driver = str((creds or {}).get("driver") or "").lower()
    dialect = SQLGLOT_DIALECT.get(driver, driver) if driver and driver != "mongodb" else ""
    try:
        masked = masked_columns(cols, statement_tables(code, dialect) if driver != "mongodb" else [])
    except Exception:  # noqa: BLE001 — masking is presentation; a failure shows the values
        masked = []
    return {
        "columns": cols,
        "rows": [[_json_cell(v) for v in r] for r in rows[:CANVAS_GRID_MAX_ROWS]],
        "truncated": bool(result.truncated),
        "grid_truncated": len(rows) > CANVAS_GRID_MAX_ROWS,
        "masked_columns": masked,
    }


@rest_api_bp.route("/v1/canvas/explain", methods=["POST"])
async def canvas_explain():
    """The plan of the canvas's statement, without the agent: run ``EXPLAIN <statement>`` on
    the canvas's bound Database Connection and return the parsed plan — the SAME spec the
    agent's TDA_ExplainPlan produces, so the EXPLAIN Plan panel draws both alike.

    Teradata connections only (the parser reads Teradata plans). The statement must be ONE
    read-only SELECT (the Navigator's guard); it is explained, never executed, and the
    connection is opened read-only.

    Body: ``{"connection_id": "...", "code": "SELECT ..."}`` (a leading EXPLAIN is accepted).
    """
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    data = await request.get_json() or {}
    connection_id = data.get("connection_id")
    code = str(data.get("code") or "").strip()
    if not connection_id:
        return jsonify({"status": "error", "code": "no_connection",
                        "message": "Choose a Teradata Database Connection to explain this statement."}), 400
    if not code:
        return jsonify({"status": "error", "code": "empty", "message": "There is no statement to explain."}), 400
    try:
        from trusted_data_agent.core.database_connections import get_database_connection_store
        from trusted_data_agent.dbcatalog.sql_runner import single_select_guard
        from trusted_data_agent.dbcatalog.base import CatalogError
        from components.builtin.canvas.connectors import get_connector
        try:
            from components.builtin.explain_plan import plan_parser as P
        except ImportError:
            return jsonify({"status": "error", "code": "explain_plan_not_installed",
                            "message": "Explain Plan is an enterprise component and is not installed here."}), 404

        creds = get_database_connection_store().resolve(user_uuid, connection_id)
        if not creds:
            return jsonify({"status": "error", "code": "no_connection",
                            "message": "That connection was not found for your account."}), 404
        if str(creds.get("driver") or "").lower() != "teradata":
            return jsonify({"status": "error", "code": "not_teradata",
                            "message": "Plans can be drawn for Teradata connections only."}), 400
        if creds.get("username") and not creds.get("user"):
            creds = {**creds, "user": creds["username"]}
        sql = P.explained_sql(code)
        try:
            body = single_select_guard(sql)
        except CatalogError as exc:
            return jsonify({"status": "error", "code": "not_read_only",
                            "message": f"{exc} — only one SELECT can be explained here."}), 400
        connector = get_connector("sql_native")
        result = await connector.execute(f"EXPLAIN {body}", creds, readonly=True)
        if result.error:
            # the database's own message, without the driver's stack trace
            msg = str(result.error).split("\n at ")[0].split("\n")[0].strip()
            return jsonify({"status": "error", "code": "explain_failed", "message": msg}), 400
        cols = [str(c) for c in (result.columns or [])]
        rows = [dict(zip(cols, r)) for r in (result.rows or [])]
        plan = P.parse(P.explain_text(rows))
        if not P.work_steps(plan):
            return jsonify({"status": "error", "code": "unparsed",
                            "message": "The database answered, but not with a plan this panel can read."}), 422
        built = P.build_spec(plan, statement=None, sql=body, truncated=bool(result.truncated),
                             lines=len(rows), origin="canvas")
        return jsonify({"status": "success", **built}), 200
    except Exception as e:  # noqa: BLE001
        app_logger.error(f"Canvas explain failed: {e}", exc_info=True)
        return jsonify({"status": "error", "code": "explain_error", "message": str(e)}), 500


@rest_api_bp.route("/v1/canvas/execute", methods=["POST"])
async def canvas_execute():
    """
    Execute canvas code via MCP bridge or native connector.

    If `connector_id` is present → route to native connector (reads creds from encrypted store).
    If no `connector_id` + language='sql' → legacy MCP bridge.
    Other languages → 400 (frontend-only execution).

    Request body:
    {
        "code": "SELECT * FROM products",
        "language": "sql",
        "session_id": "session-xxx",
        "connector_id": "sql_native"   // optional — triggers native connector
    }
    """
    import time

    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401

    data = await request.get_json()
    code = data.get("code", "").strip()
    language = data.get("language", "").lower()
    session_id = data.get("session_id")
    connector_id = data.get("connector_id")
    connection_id = data.get("connection_id")

    if not code:
        return jsonify({"status": "error", "message": "Code is required"}), 400

    # ── Native connector path (via named connection) ─────────────────────────
    if connector_id or connection_id:
        try:
            from components.builtin.canvas.connectors import get_connector
            from trusted_data_agent.auth.encryption import decrypt_credentials

            cid = connector_id or 'sql_native'
            connector = get_connector(cid)
            if not connector:
                return jsonify({"status": "error", "message": f"Unknown connector: {cid}"}), 400

            # Read credentials. Named connections resolve through the centralized
            # Database Connection store (handles central + legacy ids); the store
            # uses 'username', the SQL connector expects 'user' — map it.
            if connection_id:
                from trusted_data_agent.core.database_connections import get_database_connection_store
                creds = get_database_connection_store().resolve(user_uuid, connection_id)
                if creds and creds.get("username") and not creds.get("user"):
                    creds = {**creds, "user": creds["username"]}
            else:
                creds = decrypt_credentials(user_uuid, f"canvas_{cid}")
            if not creds:
                return jsonify({"status": "error", "message": "No credentials found for this connection. Manage database connections under Components → Connectors → Database Connection."}), 400

            result = await connector.execute(code, creds)

            if result.error:
                return jsonify({
                    "status": "error",
                    "message": result.error,
                    "execution_time_ms": result.execution_time_ms,
                }), 400

            app_logger.info(
                f"[Canvas Execute] {connector_id} | {result.row_count} rows | "
                f"{result.execution_time_ms}ms | {len(code)} chars"
            )

            out = {
                "status": "success",
                "result": result.result or "",
                "row_count": result.row_count,
                "execution_time_ms": result.execution_time_ms,
            }
            # The result GRID (typed rows, bounded) beside the unchanged display text, and the
            # columns a view masks — by the ONE rule the navigator's query card uses, so the
            # canvas and the navigator mask the same columns of the same result.
            if result.columns is not None:
                out.update(_canvas_result_grid(result, code, creds))
            return jsonify(out), 200

        except Exception as e:
            app_logger.error(f"Canvas native connector execute failed: {e}", exc_info=True)
            return jsonify({"status": "error", "message": str(e)}), 500

    # ── Legacy MCP bridge path (SQL only) ────────────────────────────────────
    if language != "sql":
        return jsonify({"status": "error", "message": f"Execution not supported for language: {language}. Only SQL is supported via MCP bridge."}), 400

    mcp_client = APP_STATE.get("mcp_client")
    if not mcp_client:
        return jsonify({"status": "error", "message": "MCP server not connected. Please configure an MCP server in your profile."}), 503

    try:
        from trusted_data_agent.mcp_adapter.adapter import invoke_mcp_tool

        command = {
            "tool_name": "base_readQuery",
            "arguments": {"sql": code}
        }

        start_time = time.time()
        result, input_tokens, output_tokens = await invoke_mcp_tool(
            APP_STATE, command, user_uuid=user_uuid, session_id=session_id
        )
        execution_time_ms = int((time.time() - start_time) * 1000)

        # Check for MCP error
        if isinstance(result, dict) and result.get("status") == "error":
            error_msg = result.get("data") or result.get("error") or "SQL execution failed"
            app_logger.warning(f"[Canvas Execute] SQL error: {error_msg}")
            return jsonify({
                "status": "error",
                "message": str(error_msg),
                "execution_time_ms": execution_time_ms,
            }), 400

        # Extract result text
        result_text = ""
        row_count = 0
        if isinstance(result, dict):
            results_data = result.get("results", result)
            if isinstance(results_data, list):
                row_count = len(results_data)
                result_text = json.dumps(results_data, indent=2, default=str)
            elif isinstance(results_data, str):
                result_text = results_data
                row_count = result_text.count("\n")
            else:
                result_text = json.dumps(results_data, indent=2, default=str)
        elif isinstance(result, str):
            result_text = result
            row_count = result.count("\n")
        else:
            result_text = str(result)

        app_logger.info(
            f"[Canvas Execute] MCP SQL | {row_count} rows | "
            f"{execution_time_ms}ms | {len(code)} chars"
        )

        return jsonify({
            "status": "success",
            "result": result_text,
            "row_count": row_count,
            "execution_time_ms": execution_time_ms,
        }), 200

    except Exception as e:
        app_logger.error(f"Canvas execute failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


# ─── Canvas Named Connections ─────────────────────────────────────────────────

def _canvas_connection_view(rec):
    """A Database Connection as the Canvas connection UI reads it. The store says
    `username`; the Canvas SQL connector and its form say `user`."""
    creds = {k: rec.get(k) for k in ("name", "driver", "host", "port", "database", "ssl",
                                      "jdbc_url", "jdbc_driver_class", "jdbc_driver_path", "password")
             if rec.get(k) is not None}
    if rec.get("username") is not None:
        creds["user"] = rec.get("username")
    return {
        "connection_id": rec["id"],
        "name": rec.get("name", rec["id"]),
        "driver": rec.get("driver", "unknown"),
        "credentials": creds,
        "has_password": bool(rec.get("has_password")),
        "source": rec.get("source", "central"),
    }


def _canvas_payload(credentials):
    """The Canvas form's fields → the store's (`user` → `username`)."""
    payload = dict(credentials or {})
    if payload.get("user") and not payload.get("username"):
        payload["username"] = payload.pop("user")
    else:
        payload.pop("user", None)
    return payload


@rest_api_bp.route("/v1/canvas/connections", methods=["GET"])
async def canvas_connections_list():
    """List the user's database connections (passwords masked) — the one
    Database Connection store, which also surfaces not-yet-migrated legacy ones."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    try:
        from trusted_data_agent.core.database_connections import get_database_connection_store
        recs = get_database_connection_store().list(user_uuid, include_legacy=True)
        return jsonify({"status": "success", "connections": [_canvas_connection_view(r) for r in recs]}), 200
    except Exception as e:
        app_logger.error(f"Canvas list connections failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/canvas/connections/<connection_id>", methods=["GET"])
async def canvas_connection_get(connection_id):
    """Get a single connection (password masked), by any id form."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    try:
        from trusted_data_agent.core.database_connections import get_database_connection_store
        store = get_database_connection_store()
        legacy = store.legacy_provider(user_uuid, connection_id)
        rec = store.get(user_uuid, legacy or connection_id)
        if not rec:
            return jsonify({"status": "error", "message": "Connection not found"}), 404
        view = _canvas_connection_view(rec)
        return jsonify({"status": "success", "connection_id": view["connection_id"],
                        "credentials": view["credentials"], "has_password": view["has_password"]}), 200
    except Exception as e:
        app_logger.error(f"Canvas get connection failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/canvas/connections", methods=["PUT"])
async def canvas_connection_save():
    """Create or update a connection in the one store. Editing a legacy Canvas
    connection promotes it; a masked password sent back unchanged keeps the stored one."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    try:
        from trusted_data_agent.core.database_connections import (
            get_database_connection_store, DatabaseConnectionError)
        data = await request.get_json()
        credentials = data.get("credentials")
        if not credentials:
            return jsonify({"status": "error", "message": "credentials are required"}), 400
        try:
            rec = get_database_connection_store().save(user_uuid, data.get("connection_id"),
                                                       _canvas_payload(credentials))
        except DatabaseConnectionError as e:
            return jsonify({"status": "error", "message": str(e)}), 400
        app_logger.info(f"[Canvas Connection] Saved connection={rec['id']} user={user_uuid[:8]}...")
        return jsonify({"status": "success", "message": "Connection saved", "connection_id": rec["id"]}), 200
    except Exception as e:
        app_logger.error(f"Canvas save connection failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


