async def _test_db_connection_creds(creds):
    """Shared: test creds via the SQL native connector (maps username→user)."""
    from components.builtin.canvas.connectors import get_connector
    connector = get_connector('sql_native')
    if not connector:
        return jsonify({"status": "error", "message": "SQL native connector not available"}), 500
    # SQLNativeConnector expects 'user'; the central store uses 'username'.
    test_creds = dict(creds)
    if test_creds.get("username") and not test_creds.get("user"):
        test_creds["user"] = test_creds["username"]
    result = await connector.test_connection(test_creds)
    return jsonify({
        "status": "success" if result.valid else "error",
        "valid": result.valid,
        "message": result.message,
        "server_info": result.server_info,
    }), 200 if result.valid else 400


