# ─── Knowledge Graph ──────────────────────────────────────────────────────────

def _get_graph_store(user_uuid, profile_id=None):
    """Instantiate a GraphStore scoped to user + profile."""
    from components.builtin.knowledge_graph.graph_store import GraphStore
    if not profile_id:
        profile_id = request.args.get("profile_id", "__default__")
    return GraphStore(profile_id=profile_id, user_uuid=user_uuid)


def _resolve_active_kg_owner_profile(user_uuid, profile_id):
    """
    Resolve the OWNER profile of the KG active for `profile_id` via
    kg_profile_assignments — the same resolution the KG component uses. A KG can be
    assigned-active to a profile while being owned by another profile, and the
    active flag lives in kg_profile_assignments (not kg_metadata). Falls back to
    `profile_id` itself when there is no assignment.
    """
    import sqlite3
    try:
        from trusted_data_agent.core.config import APP_CONFIG
        db_path = APP_CONFIG.AUTH_DB_PATH.replace("sqlite:///", "")
    except Exception:
        db_path = "tda_auth.db"
    try:
        conn = sqlite_util.connect(db_path)
        row = conn.execute(
            "SELECT kg_owner_profile_id FROM kg_profile_assignments "
            "WHERE assigned_profile_id = ? AND user_uuid = ? AND is_active = 1",
            (profile_id, user_uuid),
        ).fetchone()
        conn.close()
        return row[0] if row and row[0] else profile_id
    except Exception:
        return profile_id


def _get_user_tier(current_user):
    """Resolve the user's tier string ('user', 'developer', 'admin').
    current_user is a User ORM object (from require_auth middleware).
    Falls back to 'user' on any error.
    """
    try:
        if isinstance(current_user, dict):
            # Fallback: JWT-decoded dict — query DB by user_id
            user_uuid = current_user.get("user_id") or current_user.get("sub")
            if not user_uuid:
                return "user"
            from trusted_data_agent.auth.database import get_db_session
            from trusted_data_agent.auth.models import User as _User
            with get_db_session() as db:
                record = db.query(_User).filter(_User.id == user_uuid).first()
                if record:
                    if record.is_admin or record.profile_tier == "admin":
                        return "admin"
                    return record.profile_tier or "user"
        else:
            # Normal path: current_user is a User ORM object
            if current_user.is_admin or current_user.profile_tier == "admin":
                return "admin"
            return current_user.profile_tier or "user"
    except Exception:
        pass
    return "user"


def _assert_kg_enabled(current_user):
    """
    Return a 403 response if KG feature is disabled for this user's tier,
    or None if access is allowed.  Call at the top of every /v1/knowledge-graph/* handler.
    """
    from trusted_data_agent.kgstore.settings import is_kg_enabled_for_tier
    tier = _get_user_tier(current_user)
    if not is_kg_enabled_for_tier(tier):
        return jsonify({
            "status": "error",
            "message": "Knowledge graph feature is not enabled for your account tier.",
        }), 403
    return None


