@operation("knowledge_graph.versions", effect="read", scope="own",
           summary="A graph's saved versions, oldest first — when each was saved, its label and its size",
           query={"kg_id": Arg("string", "the knowledge graph (knowledge_graph.list lists them)", required=True)},
           summary_fields=("version_id", "version_num", "label", "entity_count", "created_at"))
@require_auth
async def kg_list_versions(current_user):
    """List version history for the active KG (oldest first; metadata only)."""
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.core.kg_version_db import list_versions
    user_uuid = _get_user_uuid_from_request()
    # Optional kg_id scopes to a specific KG (the card's KG); else the active KG.
    kg_id = (request.args.get("kg_id") or "").strip()
    if kg_id:
        if not _kg_owner_profile_for_id(user_uuid, kg_id):
            return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
        target_kg_id = kg_id
    else:
        target_kg_id = _get_graph_store(user_uuid).kg_id
    try:
        versions = list_versions(target_kg_id, user_uuid)
        return jsonify({"status": "success", "versions": versions, "count": len(versions)})
    except Exception as e:
        app_logger.error(f"KG list versions failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/versions", methods=["POST"])
@operation("knowledge_graph.version_save", effect="write", scope="own",
           summary="Save a graph as it is now as a version — nothing is saved when it has not changed since the last one",
           body={"kg_id": Arg("string", "the knowledge graph (knowledge_graph.list lists them)", required=True), "label": "a short label for the version"})
@require_auth
async def kg_snapshot_version(current_user):
    """Capture the current graph as a new version (deduped, compressed, capped)."""
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.core.kg_version_db import snapshot_kg
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    try:   # "kg_id" names one of the caller's graphs; else "profile_id"'s active graph
        store = _resolve_kg_store_for_request(user_uuid, data.get("profile_id"),
                                              (data.get("kg_id") or "").strip() or None)
    except _KGNotFound:
        return _kg_not_found()
    try:
        entities = await store.list_entities(limit=999999)
        relationships = await store.list_relationships(limit=999999)
        result = snapshot_kg(store.kg_id, user_uuid, entities, relationships, label=data.get("label"))
        if result is None:
            return jsonify({"status": "unchanged", "message": "Graph unchanged — no snapshot created"})
        return jsonify({"status": "success", "version": result}), 201
    except Exception as e:
        app_logger.error(f"KG snapshot failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/versions/<version_id>/restore", methods=["POST"])
@operation("knowledge_graph.version_restore", effect="human_only", scope="own",
           summary="Put a graph back to a saved version — replaces what it holds now",
           path={"version_id": "the version (knowledge_graph.versions lists them)"}, body={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
@_signals.announces_route("knowledge_graph", "restored", aspect="versions")
async def kg_restore_version(current_user, version_id):
    """Restore the graph to a prior version (clear + bulk re-import)."""
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.core.kg_version_db import get_version_graph, snapshot_kg
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    # Optional kg_id scopes restore to a specific KG (the card's KG); else active.
    kg_id = (data.get("kg_id") or "").strip()
    if kg_id:
        profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
        if not profile_id:
            return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
        from components.builtin.knowledge_graph.graph_store import GraphStore
        store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
    else:
        store = _get_graph_store(user_uuid, data.get("profile_id"))
    try:
        graph = get_version_graph(version_id, store.kg_id, user_uuid)
        if not graph:
            return jsonify({"status": "error", "message": "Version not found"}), 404
        # A restore replaces the MODEL with that version; the authored/observed layers
        # are not part of a walked version and survive (PROP-008 A1).
        store.replace_model_layer(graph["entities"], graph["relationships"])
        snapshot_kg(store.kg_id, user_uuid, graph["entities"], graph["relationships"],
                    label=f"Restored v{graph['version_num']}")
        return jsonify({
            "status": "success",
            "restored_version": graph["version_num"],
            "entity_count": len(graph["entities"]),
            "rel_count": len(graph["relationships"]),
        })
    except Exception as e:
        app_logger.error(f"KG restore failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


# ── Update-from-source lifecycle (declarative KGs) ───────────────────────────

def _kg_owner_profile_for_id(user_uuid, kg_id):
    """Resolve the owner profile_id for a given kg_id (so a store can be scoped)."""
    import sqlite3
    try:
        conn = sqlite_util.connect(str(DB_PATH))
        row = conn.execute(
            "SELECT profile_id FROM kg_metadata WHERE kg_id=? AND user_uuid=?",
            (kg_id, user_uuid),
        ).fetchone()
        conn.close()
        return row[0] if row else None
    except Exception:
        return None


# A checked candidate is kept for the apply that follows it, so an update pays the
# rebuild (and, when asked, the source validation — minutes on a large product) ONCE.
# Keyed by (user, kg, override); bounded; a stale entry is simply rebuilt.
_REBUILD_CANDIDATES: dict = {}
_REBUILD_CANDIDATE_TTL = 1800


def _candidate_key(user_uuid, kg_id, options_override) -> str:
    return f"{user_uuid}|{kg_id}|{json.dumps(options_override or {}, sort_keys=True)}"


def _keep_candidate(key: str, value) -> None:
    import time as _t
    _REBUILD_CANDIDATES[key] = (_t.monotonic(), value)
    if len(_REBUILD_CANDIDATES) > 50:
        for k in sorted(_REBUILD_CANDIDATES, key=lambda k: _REBUILD_CANDIDATES[k][0])[:25]:
            _REBUILD_CANDIDATES.pop(k, None)


def _take_candidate(key: str):
    """Return and forget the candidate checked under ``key`` — once, and only while fresh."""
    import time as _t
    entry = _REBUILD_CANDIDATES.pop(key, None)
    if not entry or _t.monotonic() - entry[0] > _REBUILD_CANDIDATE_TTL:
        return None
    return entry[1]


async def _rebuild_candidate_for_kg(store, options_override=None):
    """Resolve a KG's source descriptor + strategy, return (descriptor, entities, relationships).

    Returns (None, None, None) with a reason string if the KG is not re-syncable.

    options_override (optional dict) extends/reduces the source scope — e.g. toggling
    include_columns / include_metrics / include_glossary, the physical (PDM) layer, or
    divisions. It is merged onto the stored descriptor's options so the rebuild (and thus
    the diff / apply) reflects the user's new selection. The returned descriptor carries
    the merged options so apply-update can persist them.
    """
    from trusted_data_agent.agent.kg_constructors import registry as _kg_registry

    descriptor = store.get_source_descriptor()
    if not descriptor:
        return None, None, None, "This knowledge graph has no source to update from."
    # `discovery_mode` is the fallback for graphs stamped before the key was
    # written: those descriptors are otherwise unreadable, and the graph they
    # describe cannot be updated at all.
    strat_mode = descriptor.get("strategy") or descriptor.get("discovery_mode")
    try:
        strategy = _kg_registry.resolve(strat_mode)
    except Exception:
        return None, None, None, f"Unknown constructor strategy '{strat_mode}'."
    if not strategy.supports_resync:
        return None, None, None, f"The '{strat_mode}' constructor does not support updates."
    if options_override:
        descriptor = dict(descriptor)
        merged_opts = dict(descriptor.get("options") or {})
        # Only override known scope keys; ignore anything else the client sends.
        for k in ("include_columns", "include_metrics", "include_glossary", "layers", "divisions",
                  "validate_with_source"):
            if k in options_override:
                merged_opts[k] = options_override[k]
        descriptor["options"] = merged_opts
    cand_entities, cand_relationships = await strategy.rebuild(descriptor)
    # A resync rebuilds the LOGICAL model from its source.  The physical layer of a
    # DEPLOYED industry model does not come from that source — it came from the
    # warehouse the model was deployed to — so a candidate that carries none must
    # not replace it: carry the deployed layer (and every edge touching it, incl.
    # `implements`) into the candidate.  Without this, "Apply update" on a
    # deployed graph silently stripped its physical layer.
    if strat_mode == "industry_model" and not any(
            ((e.get("properties") or {}).get("layer") == "physical") for e in cand_entities):
        cur_e = await store.list_entities(limit=999999)
        phys = [e for e in cur_e if (e.get("properties") or {}).get("layer") == "physical"]
        if phys:
            cur_r = await store.list_relationships(limit=999999)
            phys_keys = {(str(e.get("name")).lower(), e.get("entity_type")) for e in phys}
            keep = [r for r in cur_r
                    if (str(r.get("source_name")).lower(), r.get("source_type")) in phys_keys
                    or (str(r.get("target_name")).lower(), r.get("target_type")) in phys_keys]
            cand_entities = list(cand_entities) + [
                {"name": e["name"], "entity_type": e["entity_type"], "properties": e.get("properties") or {},
                 "source": e.get("source") or "deployment", "source_detail": e.get("source_detail")}
                for e in phys]
            cand_relationships = list(cand_relationships) + keep
    return descriptor, cand_entities, cand_relationships, None


@rest_api_bp.route("/v1/knowledge-graph/declare-concept", methods=["POST"])
async def kg_declare_concept():
    """Declare a business concept on a graph the caller owns: a glossary term, a compilable
    metric and a recipe grounded in an entity's declared columns. Deterministic, product-
    neutral, fails closed. Body: kg_id, concept_name, definition, predicate, entity,
    dimensions (optional). Returns what was declared and the product's Memory-module
    statements as TEXT — the platform never writes to a product's database."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    try:
        from components.builtin.knowledge_graph.handler import KnowledgeGraphHandler
        from components.builtin.knowledge_graph.graph_store import GraphStore
        h = KnowledgeGraphHandler.__new__(KnowledgeGraphHandler)  # identifiers are constant properties
        store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
        h._get_store = lambda _ctx: store
        payload = await h._handle_declare_concept(
            {"concept_name": data.get("concept_name"), "definition": data.get("definition"),
             "predicate": data.get("predicate"), "entity": data.get("entity"), "dimensions": data.get("dimensions")},
            {"user_uuid": user_uuid})
        spec = payload.spec or {}
        if spec.get("error"):
            return jsonify({"status": "error", "message": spec["error"]}), 422
        return jsonify({"status": "success", **spec, "links": (payload.metadata or {}).get("links")}), 200
    except Exception as e:
        app_logger.error(f"KG declare-concept failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/propose", methods=["POST"])
async def kg_propose():
    """PROP-008 OBDA-MODEL — the proposal row's one-click Draft, and the REST face of
    ``propose_attribute`` / ``propose_entity``. Body: kg_id, action, the action's own args.
    Runs the SAME handler path a turn runs (the OBDA-MODEL · OBDA-ACT master, the modelAuthoring grant, the
    advisor, the authored-layer write) — one implementation, two faces."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    action = (data.get("action") or "").strip()
    if not kg_id or action not in ("propose_attribute", "propose_entity"):
        return jsonify({"status": "error", "message": "kg_id and action (propose_attribute | propose_entity) are required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    try:
        from components.builtin.knowledge_graph.handler import KnowledgeGraphHandler
        from components.builtin.knowledge_graph.graph_store import GraphStore
        h = KnowledgeGraphHandler.__new__(KnowledgeGraphHandler)  # identifiers are constant properties
        store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
        h._get_store = lambda _ctx: store
        args = {k: v for k, v in data.items() if k != "kg_id"}
        payload = await h.process(args, {"user_uuid": user_uuid, "profile_id": profile_id})
        spec = payload.spec or {}
        if spec.get("error"):
            return jsonify({"status": "error", "message": spec["error"]}), 422
        return jsonify({"status": "success", "html": payload.html, "title": payload.title, **spec}), 200
    except Exception as e:
        app_logger.error(f"KG propose failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/propose/suggest", methods=["POST"])
async def kg_propose_suggest():
    """PROP-008 OBDA-MODEL — what a concept the model lacks probably records, in plain words, for
    the model-gap proposal form (``agent/proposal_suggest.py``). One small call on the answering
    agent's own model, booked to the turn the note belongs to. Body: kg_id, name, and optionally
    definition, question, profile_id (the agent that answered), session_id, turn_id."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    _gate_model = _assert_model_enabled()
    if _gate_model:
        return _gate_model
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    name = " ".join(str(data.get("name") or "").split())[:80]
    if not kg_id or not name:
        return jsonify({"status": "error", "message": "kg_id and name are required"}), 400
    owner_pid = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not owner_pid:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    try:
        from components.builtin.knowledge_graph.graph_store import GraphStore
        from trusted_data_agent.core.config_manager import get_config_manager
        from trusted_data_agent.agent import proposal_suggest
        cm = get_config_manager()
        profile = (cm.get_profile(str(data.get("profile_id") or ""), user_uuid) if data.get("profile_id") else None) \
            or cm.get_profile(owner_pid, user_uuid) or {}
        try:
            turn_id = int(data.get("turn_id")) if data.get("turn_id") not in (None, "") else None
        except (TypeError, ValueError):
            turn_id = None
        out = await proposal_suggest.suggest(
            user_uuid=user_uuid, store=GraphStore(profile_id=owner_pid, user_uuid=user_uuid, kg_id=kg_id),
            profile=profile, name=name, definition=str(data.get("definition") or ""),
            question=str(data.get("question") or ""), session_id=(data.get("session_id") or None), turn_id=turn_id)
        return jsonify({"status": "success", "profile_tag": profile.get("tag"), **out}), 200
    except Exception as e:
        app_logger.error(f"KG proposal suggestion failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/authored", methods=["GET"])
@operation("knowledge_graph.authored", effect="read", scope="own",
           summary="What people added to a graph by hand — drafted entities and attributes, and the design decisions behind them",
           query={"kg_id": "the knowledge graph (knowledge_graph.list lists them)", "profile_id": "or: the agent whose graph to read"})
async def kg_authored():
    """The AUTHORED layer of a graph the caller can read: its drafts (entities, attributes)
    and the design decisions behind them — what the Workspace lists and the Govern dialog
    steps through. Read-only; empty for a graph nobody extended."""
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    kg_id = (request.args.get("kg_id") or "").strip()
    # `?profile_id=` — the agent's own graph (the OBDA-MODEL panel and Workspace ask per agent)
    if not kg_id and (request.args.get("profile_id") or "").strip():
        kg_id = _profile_graph_id(user_uuid, request.args.get("profile_id").strip()) or ""
        if not kg_id:
            return jsonify({"status": "success", "kg_id": None, "nodes": [], "extensions": [],
                            "note": "no knowledge graph is bound to this agent"}), 200
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    # The caller's tier reads the request, so it is resolved here, on the loop.
    tier = None
    try:
        from trusted_data_agent.auth.middleware import get_current_user as _gcu
        tier = _get_user_tier(_gcu())
    except Exception:  # noqa: BLE001
        tier = None
    try:
        # Off the event loop: the listing decodes EVERY entity of the graph (and every
        # `contains` edge) to find its authored nodes — ~1 s on an industry model locally,
        # several on production, and the Workspace panel requests it at every login.
        out = await asyncio.to_thread(_kg_authored_sync, user_uuid, kg_id, profile_id, tier)
        # the graph's name, for a per-agent listing that must head its section ("Your extension · Fitness")
        try:
            from components.builtin.knowledge_graph.graph_store import GraphStore
            _meta = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id).get_kg_metadata() or {}
            out.setdefault("kg_name", _meta.get("kg_name") or _meta.get("name") or None)
        except Exception:  # noqa: BLE001 — a name is a courtesy
            out.setdefault("kg_name", None)
        return jsonify({"status": "success", "kg_id": kg_id, **out}), 200
    except Exception as e:
        app_logger.error(f"KG authored listing failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


def _kg_authored_sync(user_uuid, kg_id, profile_id, tier):
    """The body of ``kg_authored`` — request-free, run in a worker thread."""
    with sqlite_util.reuse_connections():
        from components.builtin.knowledge_graph.handler import KnowledgeGraphHandler
        from components.builtin.knowledge_graph.graph_store import GraphStore
        store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
        # The store calls are `async def` over synchronous bodies — driven on this
        # worker thread's own loop, never the server's.
        out = asyncio.run(KnowledgeGraphHandler.authored_nodes(store))
        from trusted_data_agent.core import obda_planes as _planes
        # `act_enabled` — the key the Govern dialog reads: OBDA-MODEL available to this caller
        out["act_enabled"] = bool(_planes.plane_available("model", user_uuid))
        # a landing is owed → the connection it starts on, by the ONE rule the Actions Designer
        # uses (action_types.default_connection: the connection this graph's tables were landed
        # through, else the only one) — Govern preselects it and says why
        if out["act_enabled"] and any(str(n.get("status") or "draft") in ("draft", "validated")
                                      for n in out.get("nodes", [])):
            try:
                from trusted_data_agent.core.action_types import default_connection
                out["default_target"] = default_connection(store, user_uuid, purpose="model")
            except Exception as _dc:  # noqa: BLE001 — a preselection is a courtesy
                app_logger.debug(f"KG authored listing: default target skipped: {_dc}")
        # who drafted it, as a person reads it: "you", a username, or the agent's @TAG
        labels: Dict[str, str] = {}
        def _label(actor: str) -> str:
            if not actor:
                return ""
            if actor in labels:
                return labels[actor]
            lab = actor
            try:
                if actor.startswith("agent:"):
                    from trusted_data_agent.core.config_manager import ConfigManager
                    prof = ConfigManager().get_profile(actor[6:], user_uuid)
                    lab = f"agent @{prof.get('tag')}" if prof and prof.get("tag") else "an agent"
                elif actor == user_uuid:
                    lab = "you"
                else:
                    uname = _usernames_for([actor]).get(actor)
                    lab = uname or "another user"
            except Exception:  # noqa: BLE001 — a label is a courtesy
                pass
            labels[actor] = lab
            return lab
        for n in out.get("nodes", []):
            n["authored_by_label"] = _label(str(n.get("authored_by") or ""))
        for d in out.get("decisions", []):
            d["decided_by_label"] = _label(str(d.get("decided_by") or ""))
        # A5: each extension's trust reading (signed · changed with the mover named ·
        # unsigned), whose layer it is, and whether THIS caller may publish it
        try:
            from trusted_data_agent.kgstore import types as _T
            mine = _T.extension_id_for(user_uuid)
            try:
                from trusted_data_agent.core.trust import extensions as _ext
                from trusted_data_agent.kgstore import settings as _kgs
                policy = _kgs.get_ontology_governance_policy()
            except Exception:  # noqa: BLE001 — the trust suite is removable
                _ext = None
            for x in out.get("extensions", []):
                eid = x.get("extension_id")
                x["mine"] = eid == mine
                x["label"] = "your extension" if eid == mine else (
                    f"extension by {_label(eid[4:])}" if str(eid).startswith("ext-") else f"extension {eid}")
                x["can_publish"] = bool(out["act_enabled"] and tier and _ext is not None
                                        and _ext.publish_decision(user_uuid, tier, policy, "conformant")["allowed"])
                # the publish-order rule (`awaits_landing`) — the same one publish_extension refuses on
                x["unlanded"] = sum(1 for n in out.get("nodes", [])
                                    if (n.get("extension_id") or eid) == eid
                                    and _T.awaits_landing(n.get("entity_type"), n.get("status")))
                if _ext is not None:
                    try:
                        x["trust"] = _ext.extension_state(kg_id, eid)
                    except Exception as _te:  # noqa: BLE001
                        x["trust"] = {"state": "unsigned", "drift": [], "error": str(_te)}
        except Exception as _xe:  # noqa: BLE001 — a reading is a courtesy, never a failed listing
            app_logger.debug(f"KG authored listing: extension readings skipped: {_xe}")
        return out


@rest_api_bp.route("/v1/knowledge-graph/authored/<extension_id>", methods=["DELETE"])
@operation("knowledge_graph.authored_withdraw", effect="human_only", scope="own", governs=True,
           summary="Withdraw a published extension from a graph",
           path={"extension_id": "the extension"}, query={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
@_signals.announces_route("knowledge_graph", "withdrawn", aspect="authored")
async def kg_authored_withdraw(current_user, extension_id):
    """Withdraw an extension from the caller's graph — the inverse of publish (PROP-008 A5).

    Every authored node of ``extension_id`` and its design decisions, the physical nodes a
    landing wrote for them (and the landing's schema node once nothing else realises into
    it), their retrieval telemetry, and the extension's signature go in one act; the
    warehouse is NOT touched (a person owns what was landed) and the act log keeps every
    act. Agents grounded on the graph read `changed` until re-signed, as after a publish.
    Gated like publish: the OBDA-MODEL component, the KG tier, graph ownership."""
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    gate = _assert_model_enabled()
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    kg_id = (request.args.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    try:
        from components.builtin.knowledge_graph.graph_store import GraphStore
        try:
            from trusted_data_agent.core.authored_withdraw import withdraw_extension
        except ImportError:
            return jsonify({"status": "error", "code": "obda_model_not_installed",
                            "message": "OBDA-MODEL is an enterprise component and is not installed here."}), 404
        store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
        result = await withdraw_extension(store, kg_id=kg_id, extension_id=extension_id, actor_uuid=user_uuid)
    except Exception as e:  # noqa: BLE001
        app_logger.error(f"KG authored withdraw failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": f"the withdrawal failed: {str(e)[:300]}"}), 500
    if not result.get("removed"):
        return jsonify({"status": "error", "error": "not_found",
                        "message": f"no node of extension {extension_id} on this graph"}), 404
    app_logger.info(f"[Govern] extension {extension_id} withdrawn from {kg_id} by {user_uuid}: "
                    f"{result['authored']} authored, {result['physical']} physical node(s)")
    try:
        from trusted_data_agent.core import kg_derived_state as _kds
        _kds._content_hash(kg_id); _kds._content_memo(kg_id)   # the content hash moved
    except Exception:  # noqa: BLE001 — best effort; the next read recomputes
        pass
    return jsonify({"status": "success", **result,
                    "note": ("The extension is withdrawn from the graph. Whatever it landed stays in the "
                             "warehouse until a person drops it there; the act log keeps every act.")})


@rest_api_bp.route("/v1/knowledge-graph/tuning/proposals/<rid>", methods=["DELETE"])
@operation("knowledge_graph.tuning_proposal_delete", effect="human_only", scope="own",
           summary="Remove a tuning proposal that landed nothing",
           path={"rid": "the proposal"})
@require_auth
@_signals.announces_route("knowledge_graph", "deleted", aspect="tuning")
async def kg_tuning_delete(current_user, rid):
    """Remove a tuning proposal that landed nothing (pending · failed · rejected · expired);
    an approved or landed one is a record of a structure that exists — refused (409)."""
    gate = _tuning_gate(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    from trusted_data_agent.core import tuning_proposals as _tp
    try:
        row = _tp.delete_proposal(user_uuid, rid)
    except _tp.TuningError as e:
        code = 404 if e.code == "not_found" else 409
        return jsonify({"status": "error", "error": e.code, "message": str(e)}), code
    return jsonify({"status": "success", "deleted": {"id": rid, "status": row.get("status")}})


@rest_api_bp.route("/v1/knowledge-graph/versions/<version_id>", methods=["DELETE"])
@operation("knowledge_graph.version_delete", effect="human_only", scope="own",
           summary="Delete a saved version of a graph",
           path={"version_id": "the version"}, query={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
async def kg_delete_version(current_user, version_id):
    """Remove one snapshot of the caller's graph (``?kg_id=``)."""
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    kg_id = (request.args.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    if not _kg_owner_profile_for_id(user_uuid, kg_id):
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    from trusted_data_agent.core.kg_version_db import delete_version
    if not delete_version(version_id, kg_id, user_uuid):
        return jsonify({"status": "error", "message": "no such version"}), 404
    return jsonify({"status": "success", "deleted": version_id})


@rest_api_bp.route("/v1/knowledge-graph/authored/publish", methods=["POST"])
@operation("knowledge_graph.authored_publish", effect="human_only", scope="own", governs=True,
           summary="Publish what people drafted on a graph as an extension of it",
           body={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
@_signals.announces_route("knowledge_graph", "published", aspect="authored")
async def kg_authored_publish(current_user):
    """PROP-008 A5 — publish an extension (its unpublished authored nodes) on the
    Govern dialog's road. **A person's act**: the REST runs under a user's own token and
    the pure decision refuses an ``agent:`` actor whatever the approval policy says
    (§13); the caller must hold an approver tier. Body: ``kg_id`` (the caller's own
    graph), ``extension_id`` (default: the caller's extension), ``names`` (optional —
    publish these nodes only), ``override_nonconformant``. Refused 409 ``act_off`` while
    the master is off; 403 for an agent actor or a non-approver; 409 with the reason
    when the conformance gate blocks. A refusal changes nothing."""
    _gate_model = _assert_model_enabled()
    if _gate_model:
        return _gate_model
    user_uuid = _get_user_uuid_from_request()
    if not user_uuid:
        return jsonify({"status": "error", "message": "Authentication required"}), 401
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    from trusted_data_agent.kgstore import types as _T
    extension_id = (data.get("extension_id") or "").strip() or _T.extension_id_for(user_uuid)
    try:
        from components.builtin.knowledge_graph.graph_store import GraphStore
        from trusted_data_agent.core import ontology_governance
        store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
        result = await ontology_governance.publish_extension(
            store, extension_id, actor=user_uuid, actor_tier=_get_user_tier(current_user),
            user_uuid=user_uuid, names=data.get("names") or None,
            override_nonconformant=bool(data.get("override_nonconformant")))
        if not result.get("allowed"):
            code = 403 if result.get("code") in ("agent_publish_refused", "not_an_approver") else 409
            return jsonify({"status": "blocked", "kg_id": kg_id, **result}), code
        try:
            from trusted_data_agent.core.trust import extensions as _ext
            result["trust"] = _ext.extension_state(kg_id, extension_id)
        except Exception:  # noqa: BLE001
            pass
        return jsonify({"status": "success", "kg_id": kg_id, **result}), 200
    except Exception as e:
        app_logger.error(f"KG extension publish failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/check-update", methods=["POST"])
@require_auth
async def kg_check_update(current_user):
    """Re-acquire a declarative KG's source, diff it against the live graph.

    No mutation — returns the proposed change set for user confirmation.
    """
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.kgstore.graph_diff import diff_graphs
    from trusted_data_agent.agent.kg_constructors.base import SourceError
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404

    options_override = data.get("options_override") if isinstance(data.get("options_override"), dict) else None
    from components.builtin.knowledge_graph.graph_store import GraphStore
    store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
    try:
        descriptor, cand_e, cand_r, reason = await _rebuild_candidate_for_kg(store, options_override)
        if reason:
            return jsonify({"status": "not_resyncable", "message": reason}), 200
        # Keep the checked candidate for the apply that follows: the rebuild (and, when
        # asked, the source validation — minutes on a large product) is paid ONCE.
        _keep_candidate(_candidate_key(user_uuid, kg_id, options_override), (descriptor, cand_e, cand_r))
        cur_e = await store.list_entities(limit=999999)
        cur_r = await store.list_relationships(limit=999999)
        diff = diff_graphs(cur_e, cur_r, cand_e, cand_r)
        # The toggles' baseline: a nested `options` (industry model) or the FLAT keys an ANDP
        # descriptor carries — so "Validate against the source data" reflects the build.
        _flat = {k: descriptor[k] for k in ("include_columns", "validate_with_source") if k in descriptor}
        _public_desc = {k: v for k, v in descriptor.items() if not str(k).startswith("_")}
        return jsonify({
            "status": "success",
            "kg_id": kg_id,
            "descriptor": _public_desc,
            "options": {**_flat, **(descriptor.get("options") or {})},   # current/merged scope for the toggles
            "is_empty": diff.is_empty(),
            "diff": diff.as_dict(),
        })
    except SourceError as se:
        return jsonify({"status": "error", "message": str(se)}), 502
    except Exception as e:
        app_logger.error(f"KG check-update failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/reload-demo-data", methods=["POST"])
@operation("knowledge_graph.reload_demo_data", effect="human_only", scope="own", governs=True,
           summary="Replace the demo rows in an industry-model graph's database",
           body={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
async def kg_reload_demo_data(current_user):
    """Regenerate + reload the demo rows of a DEPLOYED industry-model KG — data only.

    Tables, keys and the graph's physical layer stay as deployed; the plan's tables
    are emptied and refilled by the chosen data source (``data_profile`` semantic |
    basic, ``rows_per_table``, ``max_rows_per_model``).  Body: ``kg_id`` (required),
    ``deployment_target_id`` (a Database Connection; defaults to the one the KG was
    deployed with), ``root_database`` (defaults to the deployed one).
    """
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.agent.kg_constructors import registry as _kg_registry
    from trusted_data_agent.agent.kg_constructors.base import SourceError
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    from components.builtin.knowledge_graph.graph_store import GraphStore
    store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
    descriptor = store.get_source_descriptor() or {}
    if (descriptor.get("strategy") or "") != "industry_model":
        return jsonify({"status": "error", "message": "Only an industry-model knowledge graph carries deployed demo data"}), 400
    stored = descriptor.get("deploy") or {}
    target_id = (data.get("deployment_target_id") or "").strip() or stored.get("deployment_target_id")
    if not target_id:
        return jsonify({"status": "error",
                        "message": "deployment_target_id is required (this graph was deployed before the target was recorded on it)"}), 400
    deployment_config = _resolve_deployment_target(current_user, user_uuid, target_id)
    if not deployment_config:
        return jsonify({"status": "error", "message": "The deployment target could not be resolved"}), 400
    opts = {
        "deployment_config": deployment_config,
        "deployment_backend_type": (data.get("deployment_backend_type") or "teradata"),
        "root_database": (data.get("root_database") or "").strip() or None,
        "data_profile": (data.get("data_profile") or "").strip().lower() or None,
        "rows_per_table": int(data["rows_per_table"]) if data.get("rows_per_table") else None,
        "max_rows_per_model": int(data["max_rows_per_model"]) if data.get("max_rows_per_model") else None,
    }
    try:
        strategy = _kg_registry.resolve("industry_model")
        info = await strategy.reload_demo_data(descriptor, opts)
    except SourceError as se:
        return jsonify({"status": "error", "message": str(se)}), 502
    except Exception as e:
        app_logger.error(f"[KG reload-demo-data] failed for {kg_id}: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500
    # remember the data choices on the graph so the next reload starts from them
    try:
        descriptor.setdefault("deploy", {}).update({
            "deployment_target_id": target_id,
            "data_profile": info["data_profile"]["profile"],
            "rows_per_table": info["data_profile"]["base_rows"],
            "max_rows_per_model": info["data_profile"]["max_rows_per_model"],
            "root_database": info.get("root_database") or stored.get("root_database"),
        })
        store.set_source_descriptor(descriptor)
    except Exception as _de:  # noqa: BLE001 — the reload succeeded; the memo is best-effort
        app_logger.debug(f"[KG reload-demo-data] descriptor memo skipped: {_de}")
    app_logger.info(f"[KG reload-demo-data] {kg_id}: {info.get('status')} — "
                    f"{(info.get('load') or {}).get('total_rows', 0):,} rows into {info.get('root_database')}")
    return jsonify({"status": "success", "kg_id": kg_id, "reload": info})


@rest_api_bp.route("/v1/knowledge-graph/redeploy-physical", methods=["POST"])
@operation("knowledge_graph.redeploy_physical", effect="human_only", scope="own", governs=True,
           summary="Re-create an industry-model graph's database — its tables, and optionally its views and demo data",
           body={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
async def kg_redeploy_physical(current_user):
    """Re-deploy an industry-model KG's PHYSICAL layer in place (same kg_id).

    The graph is rebuilt from its descriptor; the target database is (re)created
    under ``root_database`` (default: the one it was deployed in), tables + keys +
    demo data + statistics (+ metric views when ``deploy_metric_views``) are
    deployed with ``replace_existing`` and the physical layer re-imported.  A
    different ``root_database`` is a RENAME: the previous database is dropped
    afterwards unless it holds an object the plan does not own (then it stays and
    the response names the object).  Optional ``kg_name`` renames the graph.
    Body: ``kg_id`` (required), ``deployment_target_id`` (defaults to the recorded
    one), ``root_database``, ``deploy_metric_views``, ``drop_previous_root`` (true),
    ``data_profile`` / ``rows_per_table`` / ``max_rows_per_model``, ``comments``,
    ``kg_name``.  A pre-sync snapshot keeps the prior graph switchable.
    """
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.agent.kg_constructors import registry as _kg_registry
    from trusted_data_agent.agent.kg_constructors.base import SourceError
    from trusted_data_agent.core.kg_version_db import snapshot_kg
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    from components.builtin.knowledge_graph.graph_store import GraphStore
    store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
    descriptor = store.get_source_descriptor() or {}
    if (descriptor.get("strategy") or "") != "industry_model":
        return jsonify({"status": "error", "message": "Only an industry-model knowledge graph has a deployable physical model"}), 400
    stored = descriptor.get("deploy") or {}
    target_id = (data.get("deployment_target_id") or "").strip() or stored.get("deployment_target_id")
    if not target_id:
        return jsonify({"status": "error", "message": "deployment_target_id is required"}), 400
    deployment_config = _resolve_deployment_target(current_user, user_uuid, target_id)
    if not deployment_config:
        return jsonify({"status": "error", "message": "The deployment target could not be resolved"}), 400
    opts = {
        "deployment_config": deployment_config,
        "deployment_target_id": target_id,
        "deployment_backend_type": (data.get("deployment_backend_type") or "teradata"),
        "root_database": (data.get("root_database") or "").strip() or None,
        "root_database_mode": (data.get("root_database_mode") or "create"),
        "root_perm_bytes": int(data["root_perm_bytes"]) if data.get("root_perm_bytes") else None,
        "deploy_metric_views": bool(data.get("deploy_metric_views", stored.get("deploy_metric_views", False))),
        "drop_previous_root": bool(data.get("drop_previous_root", True)),
        "load_demo_data": bool(data.get("load_demo_data", True)),
        "data_profile": (data.get("data_profile") or "").strip().lower() or None,
        "rows_per_table": int(data["rows_per_table"]) if data.get("rows_per_table") else None,
        "max_rows_per_model": int(data["max_rows_per_model"]) if data.get("max_rows_per_model") else None,
        "comments": (data.get("comments") or "").strip().lower() or None,
    }
    # pre-sync snapshot: the prior graph stays switchable whatever happens below
    try:
        cur_e = await store.list_entities(limit=999999)
        cur_r = await store.list_relationships(limit=999999)
        snapshot_kg(kg_id, user_uuid, cur_e, cur_r, label="Pre-redeploy snapshot")
    except Exception as _snap_err:  # noqa: BLE001 — a snapshot failure must not block the redeploy
        app_logger.warning(f"[KG redeploy] pre-redeploy snapshot skipped: {_snap_err}")
    try:
        strategy = _kg_registry.resolve("industry_model")
        info, new_desc = await strategy.redeploy_physical(store, descriptor, opts)
    except SourceError as se:
        return jsonify({"status": "error", "message": str(se)}), 502
    except Exception as e:
        app_logger.error(f"[KG redeploy] failed for {kg_id}: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500
    if info.get("status") == "success":
        try:
            store.set_source_descriptor(new_desc)
            kg_name = (data.get("kg_name") or "").strip() or None
            root = info.get("root_database")
            GraphStore.rename_kg(kg_id, kg_name or (store.get_kg_metadata() or {}).get("name") or root,
                                 database_name=root)
        except Exception as _me:  # noqa: BLE001 — the deploy succeeded; the memo is best-effort
            app_logger.warning(f"[KG redeploy] metadata memo skipped: {_me}")
    app_logger.info(f"[KG redeploy] {kg_id}: {info.get('status')} -> {info.get('root_database')} "
                    f"(previous {info.get('previous_root_database')}, dropped={info.get('previous_root_dropped')})")
    return jsonify({"status": "success" if info.get("status") == "success" else "error",
                    "kg_id": kg_id, "redeploy": info,
                    "message": info.get("message", "")}), (200 if info.get("status") == "success" else 500)


# ── PROP-008 C1 — the workload recommender's faces ───────────────────────────

def _tuning_gate(current_user):
    """The OBDA-MODEL component (403 `obda_model_off`) + the KG tier gate, shared by every tuning route."""
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    _gate_model = _assert_model_enabled()
    if _gate_model:
        return _gate_model
    return None


@rest_api_bp.route("/v1/knowledge-graph/tuning/review", methods=["POST"])
@require_auth
async def kg_tuning_review(current_user):
    """Review the recorded workload of the agents grounded on a graph against its deployed
    tables (read-only: dictionary reads + EXPLAIN of guarded SELECTs) and record the
    proposals. Body: ``kg_id``, ``connection_id`` (a Teradata Database Connection). Nothing
    is applied — a person approves, then lands."""
    gate = _tuning_gate(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    conn = (data.get("connection_id") or "").strip()
    if not kg_id or not conn:
        return jsonify({"status": "error", "message": "kg_id and connection_id are required"}), 400
    if not _kg_owner_profile_for_id(user_uuid, kg_id):
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    try:
        from trusted_data_agent.core import tuning_evidence as _te, tuning_proposals as _tp
    except ImportError:
        return jsonify({"status": "error", "error": "tuning_not_installed",
                        "message": "Workload tuning is part of the enterprise package."}), 404
    try:
        review = await _te.review_graph(user_uuid, kg_id, conn)
    except ValueError as e:
        return jsonify({"status": "error", "message": str(e)}), 400
    except Exception as e:  # noqa: BLE001
        app_logger.error(f"tuning review failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": f"the workload review failed: {str(e)[:300]}"}), 500
    _tp.expire_stale(user_uuid, kg_id)
    rows = _tp.record_review(user_uuid, kg_id, review, connection_id=conn)
    return jsonify({"status": "success", "review": {k: v for k, v in review.items() if k != "proposals"},
                    "proposals": rows})


@rest_api_bp.route("/v1/knowledge-graph/tuning/proposals", methods=["GET"])
@operation("knowledge_graph.tuning_proposals", effect="read", scope="own",
           summary="Proposed database tuning for a graph's tables — from what its agents actually ran — and where each proposal stands",
           query={"kg_id": Arg("string", "the knowledge graph (knowledge_graph.list lists them)", required=True),
                  "status": Arg("string", "only proposals in this state", enum=("pending", "approved", "failed", "landed", "rejected", "expired"))},
           summary_fields=("id", "purpose", "table_name", "status"))
@require_auth
async def kg_tuning_list(current_user):
    gate = _tuning_gate(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    kg_id = (request.args.get("kg_id") or "").strip()
    if not kg_id or not _kg_owner_profile_for_id(user_uuid, kg_id):
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    from trusted_data_agent.core import tuning_proposals as _tp
    return jsonify({"status": "success", "proposals": _tp.list_proposals(user_uuid, kg_id,
                                                                         status=request.args.get("status") or None)})


def _tuning_refusal(e):
    status = {"not_found": 404, "person_required": 403}.get(getattr(e, "code", ""), 409)
    return jsonify({"status": "error", "code": getattr(e, "code", "refused"), "message": str(e)}), status


@rest_api_bp.route("/v1/knowledge-graph/tuning/proposals/<rid>/<action>", methods=["POST"])
@operation("knowledge_graph.tuning_decide", effect="human_only", scope="own", governs=True,
           summary="Approve or reject a tuning proposal, or land an approved one on the database",
           path={"rid": "the proposal", "action": "approve · reject · land"})
@require_auth
async def kg_tuning_decide(current_user, rid, action):
    """``approve`` | ``reject`` a pending proposal (the graph owner, a person), or ``land``
    an approved one: measured before/after, one statement per round trip, signed receipt,
    a ``ddl_artifact`` node in the graph."""
    gate = _tuning_gate(current_user)
    if gate:
        return gate
    if action not in ("approve", "reject", "land"):
        return jsonify({"status": "error", "message": "action must be approve | reject | land"}), 400
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    from trusted_data_agent.core import tuning_proposals as _tp
    row = _tp.get_proposal(user_uuid, rid)
    if not row:
        return jsonify({"status": "error", "message": "no such tuning proposal"}), 404
    profile_id = _kg_owner_profile_for_id(user_uuid, row["kg_id"])
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    actor = getattr(current_user, "username", None) or user_uuid
    if action in ("approve", "reject"):
        try:
            return jsonify({"status": "success",
                            "proposal": _tp.decide(user_uuid, rid, action, actor=actor, note=data.get("note"))})
        except _tp.TuningError as e:
            return _tuning_refusal(e)
    conn = (data.get("connection_id") or row.get("connection_id") or "").strip()
    deployment_config = _resolve_deployment_target(current_user, user_uuid, conn) if conn else None
    if not deployment_config:
        return jsonify({"status": "error", "message": "the proposal's Database Connection could not be resolved"}), 400
    from trusted_data_agent.core.database_connections import get_database_connection_store
    try:
        from trusted_data_agent.core.tuning_evidence import explain_workload
    except ImportError:
        return jsonify({"status": "error", "error": "tuning_not_installed",
                        "message": "Workload tuning is part of the enterprise package."}), 404
    from trusted_data_agent.dbdeploy import factory as _deploy_factory
    creds = get_database_connection_store().resolve(user_uuid, conn)
    try:
        backend = await _deploy_factory.get_backend("teradata", dict(deployment_config))
    except Exception as e:  # noqa: BLE001
        return jsonify({"status": "error", "message": f"deployment backend unavailable: {e}"}), 400

    try:
        await backend.initialize()
    except Exception as e:  # noqa: BLE001
        return jsonify({"status": "error", "message": f"could not connect to the warehouse: {e}"}), 400

    async def _execute(sql):
        await backend._execute_sql(sql)

    async def _measure(sqls):
        items = [{"sql": q} for q in sqls]
        await explain_workload(creds, items)
        secs = [it["est_seconds"] for it in items if it.get("est_seconds") is not None]
        unconf = sum(1 for it in items if it.get("guessed"))
        return {"seconds": sum(secs) if secs else None, "unconfident": unconf if secs else None,
                "shapes": [it.get("shape") for it in items]}

    try:
        out = await _tp.land(user_uuid, rid, actor=actor, execute=_execute, measure=_measure)
    except _tp.TuningError as e:
        return _tuning_refusal(e)
    if out.get("status") == "landed":
        from components.builtin.knowledge_graph.graph_store import GraphStore
        out["artifact_node"] = await _tp.stamp_artifact(
            GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=row["kg_id"]), out)
    return jsonify({"status": "success", "proposal": out}), (200 if out.get("status") == "landed" else 422)


@rest_api_bp.route("/v1/knowledge-graph/authored/deploy", methods=["POST"])
@operation("knowledge_graph.authored_deploy", effect="human_only", scope="own", governs=True,
           summary="Create what people drafted on a graph in its database — tables and views",
           body={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
async def kg_authored_deploy(current_user):
    """PROP-008 OBDA-MODEL (A3) — land a graph's AUTHORED layer on its warehouse.

    The person's act on the Govern dialog's road (an agent only drafts, §13): plan the
    delta between what was drafted and what the target holds, land it one statement
    per round trip, stamp the physical layer and seal a ``model_change`` receipt.
    Body: ``kg_id`` (required), ``deployment_target_id`` (a Database Connection the
    caller owns — required), ``dry_run`` (default false: plan + the SQL + the summary in
    words, no DDL), ``force_drop`` (default false: a realisation whose authored node is
    gone is refused, never dropped), ``comments`` (``table`` default | ``all`` | ``none``),
    ``database_parent`` / ``database_perm_bytes`` (provisioning knobs for a platform sibling
    database when one must be created; default: the connection's own).
    Where a new table lands is deployment policy (the model's own database when the
    deploy login owns it, else ``UDERIA_EXT_<root>``) — never a field of this request.
    Refused with 409 ``act_off`` while the OBDA-MODEL · OBDA-ACT master is off.
    """
    from trusted_data_agent.core.config import APP_CONFIG
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    _gate_model = _assert_model_enabled()
    if _gate_model:
        return _gate_model
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    target_id = (data.get("deployment_target_id") or "").strip()
    if not target_id:
        return jsonify({"status": "error", "message": "deployment_target_id is required (a Database Connection)"}), 400
    deployment_config = _resolve_deployment_target(current_user, user_uuid, target_id)
    if not deployment_config:
        return jsonify({"status": "error", "message": "The deployment target could not be resolved"}), 400
    dry_run = bool(data.get("dry_run", False))
    comments = (data.get("comments") or "table").strip().lower()
    if comments not in ("table", "all", "none"):
        return jsonify({"status": "error", "message": "comments must be table | all | none"}), 400
    from components.builtin.knowledge_graph.graph_store import GraphStore
    from trusted_data_agent.agent.kg_constructors import authored_deploy as _ad
    from trusted_data_agent.core.kg_version_db import snapshot_kg
    from trusted_data_agent.dbdeploy import factory as _deploy_factory
    store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
    # the backend follows the connection's driver (C3): a Teradata connection lands Teradata
    # DDL, a PostgreSQL connection PostgreSQL DDL — the request never has to say which
    from trusted_data_agent.dbdeploy.connection import DEPLOYABLE_DRIVERS, backend_type_for_driver
    driver = str(deployment_config.get("driver") or "teradata").strip().lower()
    if driver not in DEPLOYABLE_DRIVERS:
        return jsonify({"status": "error", "code": "driver_not_deployable",
                        "message": f"a model delta cannot land on a {driver} connection — "
                                   f"deployable: {', '.join(DEPLOYABLE_DRIVERS)}"}), 400
    try:
        backend = await _deploy_factory.get_backend(backend_type_for_driver(driver), dict(deployment_config))
    except Exception as e:
        return jsonify({"status": "error", "message": f"deployment backend unavailable: {e}"}), 400
    if not dry_run:
        # the pre-deploy snapshot: the graph before the physical layer grew stays switchable
        try:
            cur_e = await store.list_entities(limit=999999)
            cur_r = await store.list_relationships(limit=999999)
            snapshot_kg(kg_id, user_uuid, cur_e, cur_r, label="Pre-authored-deploy snapshot")
        except Exception as _snap_err:  # noqa: BLE001 — a snapshot failure must not block the landing
            app_logger.warning(f"[OBDA-MODEL deploy] pre-deploy snapshot skipped: {_snap_err}")
    try:
        perm = data.get("database_perm_bytes")
        info = await _ad.deploy_authored(store, backend, actor=user_uuid, dry_run=dry_run,
                                         force_drop=bool(data.get("force_drop", False)), comments=comments,
                                         sibling_parent=(data.get("database_parent") or "").strip() or None,
                                         sibling_perm_bytes=int(perm) if perm not in (None, "") else None,
                                         landed_via=target_id)
    except Exception as e:
        app_logger.error(f"[OBDA-MODEL deploy] failed for {kg_id}: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500
    ok = info.get("status") in ("success", "partial", "dry_run", "noop")
    app_logger.info(f"[OBDA-MODEL deploy] {kg_id}: {info.get('status')} — {info.get('summary')}")
    return jsonify({"status": "success" if ok else "error", "kg_id": kg_id, "deploy": info,
                    "message": info.get("message", "")}), (200 if ok else 409 if info.get("code") == "access_missing" else 500)


@rest_api_bp.route("/v1/knowledge-graph/redeploy-metric-views", methods=["POST"])
@operation("knowledge_graph.redeploy_metric_views", effect="human_only", scope="own", governs=True,
           summary="Re-create an industry-model graph's metric views in its database",
           body={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
async def kg_redeploy_metric_views(current_user):
    """Re-land an industry-model KG's METRIC VIEWS on its deployed database — views only.

    The views-only sibling of ``reload-demo-data`` (data only) and
    ``redeploy-physical`` (everything): the model's metric views are recompiled
    with the CURRENT compiler and created-or-replaced against the existing tables
    (Teradata ``REPLACE VIEW`` — atomic, a refused definition leaves the old view
    standing); tables, rows and statistics are untouched, so a compiler fix reaches
    a deployed model in seconds instead of through the hours-long rebuild.  A view
    the target still refuses is skipped and named.  The graph's physical layer is
    patched to what exists afterwards (``ddl_artifact`` nodes upserted for created
    views, removed for refused ones).  Body: ``kg_id`` (required),
    ``deployment_target_id`` (defaults to the recorded one), ``missing_only``
    (false — only views absent from the target), ``dry_run`` (false — plan + SQL,
    no database I/O beyond listing the target).
    """
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.agent.kg_constructors import registry as _kg_registry
    from trusted_data_agent.agent.kg_constructors.base import SourceError
    from trusted_data_agent.core.kg_version_db import snapshot_kg
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404
    from components.builtin.knowledge_graph.graph_store import GraphStore
    store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
    descriptor = store.get_source_descriptor() or {}
    if (descriptor.get("strategy") or "") != "industry_model":
        return jsonify({"status": "error", "message": "Only an industry-model knowledge graph has deployed metric views"}), 400
    stored = descriptor.get("deploy") or {}
    if not stored:
        return jsonify({"status": "error", "message": "This graph was never deployed — there is no database to land views in"}), 400
    target_id = (data.get("deployment_target_id") or "").strip() or stored.get("deployment_target_id")
    if not target_id:
        return jsonify({"status": "error", "message": "deployment_target_id is required"}), 400
    deployment_config = _resolve_deployment_target(current_user, user_uuid, target_id)
    if not deployment_config:
        return jsonify({"status": "error", "message": "The deployment target could not be resolved"}), 400
    dry_run = bool(data.get("dry_run", False))
    opts = {
        "deployment_config": deployment_config,
        "deployment_target_id": target_id,
        "deployment_backend_type": (data.get("deployment_backend_type") or "teradata"),
        "root_database": (data.get("root_database") or "").strip() or None,
        "missing_only": bool(data.get("missing_only", False)),
        "dry_run": dry_run,
    }
    if not dry_run:
        # pre-repair snapshot: the prior physical layer stays switchable whatever happens below
        try:
            cur_e = await store.list_entities(limit=999999)
            cur_r = await store.list_relationships(limit=999999)
            snapshot_kg(kg_id, user_uuid, cur_e, cur_r, label="Pre-metric-view-repair snapshot")
        except Exception as _snap_err:  # noqa: BLE001 — a snapshot failure must not block the repair
            app_logger.warning(f"[KG metric-views] pre-repair snapshot skipped: {_snap_err}")
    try:
        strategy = _kg_registry.resolve("industry_model")
        info, new_desc = await strategy.redeploy_metric_views(store, descriptor, opts)
    except SourceError as se:
        return jsonify({"status": "error", "message": str(se)}), 502
    except Exception as e:
        app_logger.error(f"[KG metric-views] failed for {kg_id}: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500
    ok = info.get("status") in ("success", "partial", "dry_run")
    if info.get("status") in ("success", "partial"):
        try:
            store.set_source_descriptor(new_desc)
        except Exception as _me:  # noqa: BLE001 — the repair succeeded; the memo is best-effort
            app_logger.warning(f"[KG metric-views] descriptor memo skipped: {_me}")
    app_logger.info(f"[KG metric-views] {kg_id}: {info.get('status')} — created {len(info.get('created') or [])}, "
                    f"refused {len(info.get('refused') or [])}, missing before {len(info.get('missing_before') or [])}")
    return jsonify({"status": "success" if ok else "error", "kg_id": kg_id, "metric_views": info,
                    "message": info.get("message", "")}), (200 if ok else 500)


@rest_api_bp.route("/v1/knowledge-graph/apply-update", methods=["POST"])
@operation("knowledge_graph.apply_update", effect="human_only", scope="own",
           summary="Rebuild a graph from its source and replace it — saved as a version before and after",
           body={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
@_signals.announces_route("knowledge_graph", "updated", aspect="sync")
async def kg_apply_update(current_user):
    """Apply an update-from-source: snapshot current → rebuild + replace → snapshot new.

    The pre-sync snapshot preserves the prior graph as a switchable version; the
    rebuild is content-hash deduped, so an unchanged source is a clean no-op.
    """
    gate = _assert_kg_enabled(current_user)
    if gate:
        return gate
    from trusted_data_agent.core.kg_version_db import snapshot_kg
    from trusted_data_agent.agent.kg_constructors.base import SourceError
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404

    options_override = data.get("options_override") if isinstance(data.get("options_override"), dict) else None
    from components.builtin.knowledge_graph.graph_store import GraphStore
    store = GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id)
    try:
        _cached = _take_candidate(_candidate_key(user_uuid, kg_id, options_override))
        if _cached:
            descriptor, cand_e, cand_r, reason = _cached[0], _cached[1], _cached[2], None
            app_logger.info(f"[KG update] applying the candidate checked moments ago for {kg_id} (no second rebuild)")
        else:
            descriptor, cand_e, cand_r, reason = await _rebuild_candidate_for_kg(store, options_override)
        if reason:
            return jsonify({"status": "not_resyncable", "message": reason}), 200
        _vstats = descriptor.pop("_validation_stats", None) if isinstance(descriptor, dict) else None

        # 1) snapshot current state (pre-sync) so the prior graph stays switchable
        cur_e = await store.list_entities(limit=999999)
        cur_r = await store.list_relationships(limit=999999)
        snapshot_kg(kg_id, user_uuid, cur_e, cur_r, label="Pre-sync snapshot")

        # 2) replace with the freshly walked candidate — and if the import fails,
        #    put the prior graph back from the in-memory pre-sync copy (this was
        #    clear-then-import with no transaction: a failed import left an EMPTY graph)
        # ONE operation (PROP-008 A1): the walked layer is replaced, the authored and
        # observed layers survive — a routine update can never silently delete a node
        # a person or an agent added on top of the model.
        try:
            import_res = store.replace_model_layer(cand_e, cand_r)
            # The source-validation stamp follows the candidate's CONTENT: set when the
            # rebuild validated (stamps present), cleared when it did not — never stale.
            try:
                from trusted_data_agent.agent.kg_constructors import source_validation as _sv
                if hasattr(store, "set_source_validation"):
                    _summary = None
                    if _sv.has_source_validation(cand_e):
                        _summary = _sv.summarize(cand_e)
                        if isinstance(_vstats, dict):
                            _summary["probe_errors"] = int(_vstats.get("probe_errors", 0))
                            _summary["seconds"] = round(sum((_vstats.get("seconds") or {}).values()), 1)
                    store.set_source_validation(_summary)
            except Exception as _sv_err:  # noqa: BLE001 — never fail an update on the stamp
                app_logger.warning(f"[KG update] could not stamp source validation: {_sv_err}")
        except Exception as _imp_err:
            app_logger.error(f"apply-update: import failed, restoring the pre-sync graph: {_imp_err}")
            try:
                store.replace_model_layer(cur_e, cur_r)
                restored = True
            except Exception as _rest_err:  # noqa: BLE001
                app_logger.error(f"apply-update: RESTORE FAILED too: {_rest_err}")
                restored = False
            return jsonify({"status": "error", "message": f"Import failed: {_imp_err}",
                            "restored_previous_graph": restored, "kg_id": kg_id}), 500

        # 2b) if the scope was extended/reduced, persist the new descriptor so future
        # syncs use the new option set (the merged descriptor is returned by the rebuild).
        if options_override:
            try:
                store.set_source_descriptor(descriptor)
            except Exception as _desc_err:
                app_logger.warning(f"apply-update: could not persist updated descriptor: {_desc_err}")

        # 3) snapshot the new state (canonical stored shape; content-hash deduped)
        new_e = await store.list_entities(limit=999999)
        new_r = await store.list_relationships(limit=999999)
        src = descriptor.get("industry", "source")
        try:
            from trusted_data_agent.agent.kg_constructors import model_naming as _nm
            size = _nm.scope_token(descriptor.get("model_size"))
        except Exception:  # noqa: BLE001 — a non-industry descriptor has no scope
            size = descriptor.get("model_size", "")
        ref = descriptor.get("repo_ref", "main")
        version = snapshot_kg(
            kg_id, user_uuid, new_e, new_r,
            label=f"Synced to {src}/{size}@{ref}",
        )
        return jsonify({
            "status": "success",
            "kg_id": kg_id,
            "entities_added": import_res.get("entities_added", 0),
            "relationships_added": import_res.get("relationships_added", 0),
            "version": version,
        })
    except SourceError as se:
        return jsonify({"status": "error", "message": str(se)}), 502
    except Exception as e:
        app_logger.error(f"KG apply-update failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/subgraph", methods=["GET"])
@operation("knowledge_graph.subgraph", effect="read", scope="own",
           summary="The part of a graph around one entity — the entities near it and the relationships between them",
           query={"kg_id": Arg("string", "the knowledge graph (knowledge_graph.list lists them)", required=True),
                  "entity_name": "the entity at the centre, by its exact name",
                  "max_nodes": Arg("integer", "at most this many entities (default 500)")})
@require_auth
async def kg_subgraph(current_user):
    """Extract a subgraph around an entity using adaptive extraction."""
    user_uuid = _get_user_uuid_from_request()
    try:   # ?kg_id= names one of the caller's graphs; else ?profile_id='s active graph
        store = _resolve_kg_store_for_request(user_uuid, request.args.get("profile_id"),
                                              (request.args.get("kg_id") or "").strip() or None)
    except _KGNotFound:
        return _kg_not_found()

    entity_name = request.args.get("entity_name")
    max_nodes = int(request.args.get("max_nodes", 500))

    try:
        if entity_name:
            entity = store.get_entity_by_name(entity_name)
            if not entity:
                return jsonify({"status": "error", "message": f"Entity '{entity_name}' not found"}), 404
            subgraph = store.extract_subgraph_adaptive(
                seed_entity_ids=[entity["id"]], max_nodes=max_nodes,
            )
        else:
            subgraph = store.get_full_graph(max_nodes=max_nodes)
        return jsonify({"status": "success", **subgraph})
    except Exception as e:
        app_logger.error(f"Knowledge graph subgraph failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


