@rest_api_bp.route("/v1/knowledge-graph/import", methods=["POST"])
@require_auth
@_signals.announces_route("knowledge_graph", "imported")
async def kg_import(current_user):
    """Bulk import entities and relationships.

    Two modes:
    - Create new KG (default): always mints a fresh kg_id so existing KGs are never touched.
    - Merge into existing (target_kg_id provided): merges into the specified KG.
    """
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json()

    profile_id = (data.get("profile_id") or "__default__")
    target_kg_id = (data.get("target_kg_id") or "").strip() or None
    entities = data.get("entities", [])
    relationships = data.get("relationships", [])

    if not entities and not relationships:
        return jsonify({"status": "error", "message": "No entities or relationships provided"}), 400

    try:
        import uuid as _uuid_mod
        from components.builtin.knowledge_graph.graph_store import GraphStore as _GS

        if target_kg_id:
            # Merge mode — import into an existing KG
            # Resolve the owning profile_id for this kg_id
            import sqlite3 as _sq_imp
            _ci = _sq_imp.connect(str(DB_PATH))
            _ri = _ci.execute(
                "SELECT profile_id FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                (target_kg_id, user_uuid)
            ).fetchone()
            _ci.close()
            owner_pid = _ri[0] if _ri else profile_id
            store = _GS(profile_id=owner_pid, user_uuid=user_uuid, kg_id=target_kg_id)
            result = store.import_bulk(entities, relationships)
            return jsonify({"status": "success", "kg_id": target_kg_id, "mode": "merge", **result})
        else:
            # Create mode — always mint a fresh kg_id so no existing KG is touched
            new_kg_id = str(_uuid_mod.uuid4())
            store = _GS(profile_id=profile_id, user_uuid=user_uuid, kg_id=new_kg_id)

            # Check if this profile already has an active KG — if so, register the
            # imported KG as inactive so the existing one is not displaced
            import sqlite3 as _sq_chk
            _cc = _sq_chk.connect(str(DB_PATH))
            _has_active = _cc.execute(
                "SELECT 1 FROM kg_metadata WHERE profile_id = ? AND user_uuid = ? AND is_active = 1 LIMIT 1",
                (profile_id, user_uuid)
            ).fetchone() is not None
            _cc.close()

            # Register metadata BEFORE import_bulk so entities are written to new_kg_id
            kg_name = (data.get("kg_name") or "").strip() or "Imported Knowledge Graph"
            kg_description = (data.get("kg_description") or "").strip() or None
            kg_database_name = (data.get("kg_database_name") or "").strip() or None
            store.set_kg_metadata(
                name=kg_name,
                database_name=kg_database_name or "",
                description=kg_description,
                is_active=not _has_active,
            )

            result = store.import_bulk(entities, relationships)
            return jsonify({"status": "success", "kg_id": new_kg_id, "mode": "create", **result})
    except Exception as e:
        app_logger.error(f"Knowledge graph import failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/clear", methods=["DELETE"])
@operation("knowledge_graph.clear", effect="human_only", scope="own",
           summary="Delete a graph — its entities, relationships and assignments",
           query={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
async def kg_clear(current_user):
    """Clear (delete) a knowledge graph. Accepts kg_id (preferred) or profile_id (legacy)."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    profile_id = request.args.get("profile_id", "__default__")
    kg_id_param = request.args.get("kg_id")

    try:
        from components.builtin.knowledge_graph.graph_store import GraphStore as _GS

        if kg_id_param:
            import sqlite3 as _sq
            _c = _sq.connect(str(DB_PATH))
            _row = _c.execute(
                "SELECT profile_id FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                (kg_id_param, user_uuid)
            ).fetchone()
            _c.close()
            if not _row:   # not the caller's graph — never read or clear another user's by id
                raise _KGNotFound(kg_id_param)
            owner_pid = _row[0]
            store = _GS(profile_id=owner_pid, user_uuid=user_uuid, kg_id=kg_id_param)
        else:
            store = _get_graph_store(user_uuid, profile_id)

        resolved_kg_id = store.kg_id
        store.clear_graph()

        # Remove kg_metadata and kg_profile_assignments rows for this specific KG.
        # (sqlite_util, not raw sqlite3 — the process-wide serialization contract.)
        _conn2 = sqlite_util.connect(str(DB_PATH))
        try:
            _conn2.execute(
                "DELETE FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                (resolved_kg_id, user_uuid)
            )
            _conn2.execute(
                "DELETE FROM kg_profile_assignments WHERE kg_id = ? AND user_uuid = ?",
                (resolved_kg_id, user_uuid)
            )
            _conn2.commit()
            # Derived state (version history, usage telemetry) dies with its KG —
            # explicit per site because KG deletion has no single chokepoint, ONE
            # registry for what is purged (core.kg_derived_state). Fail-soft.
            try:
                from trusted_data_agent.core import kg_release as _kgrel
                _kgrel.drop_released_shadow(resolved_kg_id, user_uuid)   # Model B released view
            except Exception:  # noqa: BLE001
                pass
            try:
                from trusted_data_agent.core import kg_derived_state as _kgds
                _kgds.purge_for_kg(resolved_kg_id)
            except Exception as _ve:  # noqa: BLE001
                app_logger.warning(
                    f"Could not purge derived state for KG {resolved_kg_id}: {_ve}")
        except Exception:
            pass
        finally:
            _conn2.close()

        # #30 — the ontology's attestation retires with the KG.
        try:
            from trusted_data_agent.core.trust import store as _trust_store
            if _trust_store.retire(resolved_kg_id, ("ontology",)):
                app_logger.info(f"Retired trust attestation for deleted KG {resolved_kg_id}")
        except ImportError:
            pass

        return jsonify({"status": "success", "message": "Knowledge graph deleted", "kg_id": resolved_kg_id})
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"Knowledge graph clear failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/discover", methods=["POST"])
@require_auth
async def kg_discover(current_user):
    """MCP schema discovery — never built (the V2 stub in ``discovery.py``).

    It answered ``success`` with zero counts, which reads as "discovered nothing". It now
    says what is true: not implemented. Graphs are built by the KG constructors (agent
    discovery, industry / declared models) or the TDA_KnowledgeGraph tool.
    """
    return jsonify({
        "status": "error",
        "error": "not_implemented",
        "message": "MCP schema discovery is not implemented. Build a knowledge graph with "
                   "the KG constructor (Intelligence → Knowledge Graphs) or the "
                   "TDA_KnowledgeGraph tool.",
    }), 501


@rest_api_bp.route("/v1/knowledge-graph/context", methods=["GET"])
@operation("knowledge_graph.context", effect="read", scope="own",
           summary="What an agent would be told from its knowledge graph about a question — the context it adds before the agent answers",
           query={"profile_id": Arg("string", "the agent", required=True),
                  "query": Arg("string", "the question, in the user's words", required=True)})
@require_auth
async def kg_context(current_user):
    """Test context enrichment for a query."""
    user_uuid = _get_user_uuid_from_request()
    query = request.args.get("query", "")
    profile_id = request.args.get("profile_id", "__default__")

    if not query:
        return jsonify({"status": "error", "message": "query parameter is required"}), 400

    try:
        from trusted_data_agent.components.manager import get_component_context_enrichment
        enrichment = await get_component_context_enrichment(
            query=query,
            profile_id=profile_id,
            user_uuid=user_uuid,
        )
        return jsonify({
            "status": "success",
            "query": query,
            "enrichment": enrichment,
            "has_context": bool(enrichment),
        })
    except Exception as e:
        app_logger.error(f"Knowledge graph context test failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


def _kg_list_pack_subscription_context(user_uuid: str, pack_subs: list) -> dict:
    """For the KG list: the pack-side facts of every agent_pack-sourced copy, keyed by the
    pack listing id — the pack's name and publisher, the subscriber's installation
    ``synced_at`` and whether the pack is behind (``_update_available``, the marketplace
    card's own comparison). Fails soft: an unreadable pack leaves the copy plain."""
    out: dict = {}
    if not pack_subs:
        return out
    try:
        from trusted_data_agent.api.agent_pack_routes import _update_available
        import sqlite3 as _sq
        conn = sqlite_util.connect(str(DB_PATH))
        conn.row_factory = _sq.Row
        try:
            for listing_id in {s["source_marketplace_id"] for s in pack_subs}:
                row = conn.execute(
                    "SELECT p.name, p.content_updated_at, p.source_installation_id, "
                    "u.username, u.display_name FROM marketplace_agent_packs p "
                    "LEFT JOIN users u ON u.id = p.publisher_user_id WHERE p.id = ?",
                    (listing_id,)).fetchone()
                if not row:
                    continue
                inst = conn.execute(
                    "SELECT synced_at, installed_at FROM agent_pack_installations "
                    "WHERE owner_user_id = ? AND json_extract(manifest_json, '$._source_installation_id') = ? "
                    "ORDER BY id DESC LIMIT 1",
                    (user_uuid, row["source_installation_id"])).fetchone()
                synced = (inst["synced_at"] or inst["installed_at"]) if inst else None
                out[listing_id] = {
                    "pack_name": row["name"],
                    "publisher_username": row["display_name"] or row["username"],
                    "synced_at": synced,
                    "update_available": _update_available(row["content_updated_at"], synced),
                }
        finally:
            conn.close()
    except Exception as _e:
        app_logger.debug(f"KG list: pack subscription context unavailable: {_e}")
    return out


@rest_api_bp.route("/v1/knowledge-graph/list", methods=["GET"])
@operation("knowledge_graph.list", effect="read", scope="own",
           summary="The caller's knowledge graphs: the agent each belongs to, the agents it is assigned to, its size and backend",
           summary_fields=("kg_id", "kg_name", "profile_tag", "total_entities"))
@require_auth
async def kg_list_all(current_user):
    """List all knowledge graphs for the current user across all profiles."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()

    try:
        # Off the event loop: the listing is ~10 SQLite reads plus enrichment over every
        # graph, all synchronous — run inline it stalled every concurrent request (the
        # Anatomy page fires seven at once and waited behind this one).
        graphs = await asyncio.to_thread(_kg_list_all_sync, user_uuid)
        return jsonify({"status": "success", "knowledge_graphs": graphs})
    except Exception as e:
        app_logger.error(f"Knowledge graph list failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


def _kg_list_all_sync(user_uuid):
    """The body of ``kg_list_all`` — synchronous, request-free, run in a worker thread."""
    with sqlite_util.reuse_connections():
        return _kg_list_all_in_scope(user_uuid)


def _kg_list_all_in_scope(user_uuid):
    from components.builtin.knowledge_graph.graph_store import GraphStore
    graphs = GraphStore.list_all_graphs(user_uuid)

    # Enrich with profile metadata (name, tag, type)
    from trusted_data_agent.core.config_manager import get_config_manager
    config_manager = get_config_manager()
    profiles = config_manager.get_profiles(user_uuid)
    profile_map = {p["id"]: p for p in profiles}

    # Load cross-profile assignment data (kg_id keyed)
    import sqlite3 as _sqlite3
    _conn = sqlite_util.connect(str(DB_PATH))
    _cursor = _conn.cursor()

    # Try loading with kg_id column (post-migration); fall back to kg_owner_profile_id
    try:
        _cursor.execute(
            "SELECT COALESCE(kg_id, kg_owner_profile_id), kg_owner_profile_id, "
            "assigned_profile_id, is_active FROM kg_profile_assignments WHERE user_uuid = ?",
            (user_uuid,),
        )
    except Exception:
        _cursor.execute(
            "SELECT kg_owner_profile_id, kg_owner_profile_id, assigned_profile_id, is_active "
            "FROM kg_profile_assignments WHERE user_uuid = ?",
            (user_uuid,),
        )
    assignment_rows = _cursor.fetchall()
    # Each row: (kg_id_or_owner, kg_owner_profile_id, assigned_profile_id, is_active)

    # Lazy migration: ensure every KG has a self-assignment row (keyed by kg_id)
    existing_kg_self = {row[0] for row in assignment_rows if row[0] == row[2] or row[1] == row[2]}
    kg_ids_needing_self = [kg["kg_id"] for kg in graphs if kg["kg_id"] and kg["kg_id"] not in existing_kg_self]
    committed = False
    for kid in kg_ids_needing_self:
        owner_pid = next((g["profile_id"] for g in graphs if g["kg_id"] == kid), None)
        if owner_pid:
            try:
                _cursor.execute(
                    "INSERT OR IGNORE INTO kg_profile_assignments "
                    "(kg_id, kg_owner_profile_id, assigned_profile_id, user_uuid, is_active) "
                    "VALUES (?, ?, ?, ?, 1)",
                    (kid, owner_pid, owner_pid, user_uuid),
                )
                assignment_rows.append((kid, owner_pid, owner_pid, 1))
                committed = True
            except Exception:
                pass
    if committed:
        _conn.commit()
    _conn.close()

    # Build lookup: kg_id → [(assigned_profile_id, is_active)]  (exclude self-rows)
    cross_assignments: dict = {}
    for kid, owner_pid, assigned_pid, is_active_flag in assignment_rows:
        if assigned_pid != owner_pid:  # cross-profile only
            cross_assignments.setdefault(kid, []).append((assigned_pid, is_active_flag))

    # Enrich with marketplace publish status (_sqlite3 alias already in scope above)
    _mp_conn = sqlite_util.connect(str(DB_PATH))
    _mp_conn.row_factory = _sqlite3.Row
    _mp_cursor = _mp_conn.cursor()
    try:
        _mp_cursor.execute(
            "SELECT id, kg_id, source_profile_id, visibility FROM marketplace_knowledge_graphs WHERE publisher_user_id = ?",
            (user_uuid,),
        )
    except Exception:
        _mp_cursor.execute(
            "SELECT id, source_profile_id, visibility FROM marketplace_knowledge_graphs WHERE publisher_user_id = ?",
            (user_uuid,),
        )
    _mp_rows = _mp_cursor.fetchall()
    _mp_conn.close()
    # Build lookup: kg_id → row (preferred), source_profile_id → row (fallback)
    _mp_by_kg = {}
    _mp_by_profile = {}
    for r in _mp_rows:
        kid = dict(r).get("kg_id")
        if kid:
            _mp_by_kg[kid] = r
        _mp_by_profile[r["source_profile_id"]] = r

    for kg in graphs:
        _mp_row = _mp_by_kg.get(kg.get("kg_id")) or _mp_by_profile.get(kg.get("profile_id"))
        kg["is_marketplace_listed"] = _mp_row is not None
        kg["marketplace_id"] = _mp_row["id"] if _mp_row else None
        kg["marketplace_visibility"] = _mp_row["visibility"] if _mp_row else None

    # Phase 7b enrichment: subscription state for each KG.
    # When a KG is a subscriber's local copy of a marketplace listing,
    # surface enough context for the panel to show the lock icon, sync
    # button, and "Subscribed from <publisher>" subline.
    kg_ids_for_subs = [kg["kg_id"] for kg in graphs if kg.get("kg_id")]
    sub_by_local_kg: dict = {}
    if kg_ids_for_subs:
        _subs_conn = sqlite_util.connect(str(DB_PATH))
        _subs_conn.row_factory = _sqlite3.Row
        _scur = _subs_conn.cursor()
        try:
            placeholders = ",".join("?" * len(kg_ids_for_subs))
            _scur.execute(
                f"""
                SELECT s.id, s.local_kg_id, s.source_marketplace_id,
                       s.source_kind,
                       s.last_synced_at, s.last_synced_export_hash,
                       s.last_sync_error,
                       m.name AS publisher_listing_name,
                       m.export_content_hash AS listing_hash,
                       u.username AS publisher_username,
                       u.display_name AS publisher_display_name
                FROM kg_subscriptions s
                LEFT JOIN marketplace_knowledge_graphs m ON m.id = s.source_marketplace_id
                LEFT JOIN users u ON u.id = m.publisher_user_id
                WHERE s.user_uuid = ? AND s.local_kg_id IN ({placeholders})
                """,
                [user_uuid] + kg_ids_for_subs,
            )
            for r in _scur.fetchall():
                sub_by_local_kg[r["local_kg_id"]] = dict(r)
        except Exception:
            # kg_subscriptions table missing on pre-migration installs
            pass
        finally:
            _subs_conn.close()

    # A copy made by an AGENT-PACK subscription (kg_subscriptions.source_kind =
    # 'agent_pack') is keyed to the PACK listing, not a KG listing: its publisher and
    # its "behind" signal are the pack's (content_updated_at vs the subscriber's
    # installation synced_at — the same comparison the marketplace card makes), and
    # the act it offers is the PACK sync, never the KG-marketplace routes.
    _pack_ctx = _kg_list_pack_subscription_context(
        user_uuid, [s for s in sub_by_local_kg.values() if s.get("source_kind") == "agent_pack"])

    for kg in graphs:
        sub = sub_by_local_kg.get(kg.get("kg_id"))
        kg["is_subscribed"] = bool(sub)
        kg["subscription_id"] = sub["id"] if sub else None
        kg["source_marketplace_id"] = sub["source_marketplace_id"] if sub else None
        kg["source_kind"] = (sub.get("source_kind") or "kg") if sub else None
        kg["last_synced_at"] = sub["last_synced_at"] if sub else None
        kg["last_sync_error"] = sub["last_sync_error"] if sub else None
        kg["publisher_username"] = (
            sub.get("publisher_display_name") or sub.get("publisher_username")
            if sub else None
        )
        if sub and kg["source_kind"] == "agent_pack":
            _pc = _pack_ctx.get(sub["source_marketplace_id"]) or {}
            kg["pack_name"] = _pc.get("pack_name")
            kg["publisher_username"] = _pc.get("publisher_username")
            kg["pack_synced_at"] = _pc.get("synced_at")
            kg["is_sync_available"] = bool(_pc.get("update_available"))
            continue
        # Out-of-date when publisher's listing hash differs from the
        # subscriber's last_synced_export_hash (and publisher hash exists)
        kg["is_sync_available"] = bool(
            sub
            and sub.get("listing_hash")
            and sub["listing_hash"] != sub.get("last_synced_export_hash")
        )

    # The pack pill the planner-repository card wears — the same ledger, the same
    # caller scope (a pack REFERENCE is named once per account, never once per
    # account that references it), so a graph a pack ships says so on its card.
    from trusted_data_agent.core.agent_pack_db import AgentPackDB
    try:
        _pack_db = AgentPackDB()
        for kg in graphs:
            kg["agent_packs"] = _pack_db.get_packs_for_resource(
                "knowledge_graph", str(kg.get("kg_id") or ""), owner_user_id=user_uuid)
    except Exception as e:
        app_logger.warning(f"kg_list_all: agent-pack enrichment failed: {e}")
        for kg in graphs:
            kg["agent_packs"] = []

    for kg in graphs:
        profile = profile_map.get(kg["profile_id"])
        if profile:
            kg["profile_name"] = profile.get("name", "")
            kg["profile_tag"] = profile.get("tag", "")
            kg["profile_type"] = profile.get("profile_type", "tool_enabled")
        else:
            # Orphaned KG — profile was deleted
            kg["profile_name"] = f"Deleted Profile ({kg['profile_id'][:20]}...)"
            kg["profile_tag"] = ""
            kg["profile_type"] = None

        # is_active_for_owner comes directly from kg_metadata.is_active
        kg["is_active_for_owner"] = kg.get("is_active", False)

        # Build assigned profiles list (cross-profile only)
        kg["assigned_profiles"] = []
        for apid, is_active_flag in cross_assignments.get(kg.get("kg_id", ""), []):
            ap = profile_map.get(apid)
            if ap:
                kg["assigned_profiles"].append({
                    "id": apid,
                    "name": ap.get("name", ""),
                    "tag": ap.get("tag", ""),
                    "profile_type": ap.get("profile_type", ""),
                    "is_active": bool(is_active_flag),
                })

    # Enrich each KG with its graph store backend info + live counts for non-SQLite backends
    try:
        from trusted_data_agent.kgstore.factory import get_backend_for_profile
        _kg_cfgs = config_manager.get_kg_backend_configurations(user_uuid)
        _kg_cfg_map = {c["id"]: c for c in _kg_cfgs}
        for kg in graphs:
            cfg_id = kg.get("kg_store_config_id")
            if cfg_id and cfg_id in _kg_cfg_map:
                _cfg = _kg_cfg_map[cfg_id]
                kg["backend_type"] = _cfg.get("backend_type", "sqlite")
                kg["backend_name"] = _cfg.get("name") or _cfg.get("backend_type", "SQLite").title()
                # For non-SQLite backends, fetch live counts since list_all_graphs()
                # only counts SQLite rows (which are empty for remote backends).
                if _cfg.get("backend_type", "sqlite") != "sqlite" and kg.get("kg_id"):
                    try:
                        _backend = get_backend_for_profile(
                            kg["profile_id"], user_uuid, config_id=cfg_id
                        )
                        _stats = _backend.get_stats(kg["kg_id"])
                        kg["total_entities"] = _stats.get("total_entities", kg["total_entities"])
                        kg["total_relationships"] = _stats.get("total_relationships", kg["total_relationships"])
                        kg["entity_types"] = _stats.get("entity_types", kg["entity_types"])
                        kg["relationship_types"] = _stats.get("relationship_types", kg["relationship_types"])
                    except Exception as _be:
                        app_logger.warning(f"KG list: could not fetch live stats for {kg['kg_id']}: {_be}")
            else:
                kg["backend_type"] = "sqlite"
                kg["backend_name"] = "SQLite (default)"
    except Exception:
        pass

    return graphs


# ---------------------------------------------------------------------------
# Generic component-instance portability (export / import)
# ---------------------------------------------------------------------------
# Uniform file-level export/import for ANY component whose handler declares
# supports_instance_io=True (flow today; dashboard/canvas next). Cross-references
# (profiles, tools) travel in the export as tags/names and are remapped on import
# via a mapping the import dialog gathers from a two-phase flow: dry_run preflight
# → commit. New instance-bearing components inherit this with zero endpoint/UI
# changes. See BaseComponentHandler.export_instance / import_instance.

def _get_instance_io_handler(component_id):
    """Return the component handler iff it opts into instance export/import."""
    from trusted_data_agent.components.manager import get_component_manager
    mgr = get_component_manager()
    comp = mgr.get_component(component_id) if mgr else None
    handler = getattr(comp, "handler", None) if comp else None
    if not handler or not getattr(handler, "supports_instance_io", False):
        return None
    return handler


@rest_api_bp.route("/v1/components/<component_id>/instances/<instance_id>/export", methods=["GET"])
@require_auth
async def export_component_instance(current_user, component_id, instance_id):
    """Download one component instance as a portable JSON envelope."""
    user_uuid = _get_user_uuid_from_request()
    handler = _get_instance_io_handler(component_id)
    if not handler:
        return jsonify({"status": "error", "message": f"Component '{component_id}' does not support instance export"}), 400
    try:
        envelope = await handler.export_instance(instance_id, {"user_uuid": user_uuid})
    except ValueError as e:
        return jsonify({"status": "error", "message": str(e)}), 404
    except Exception as e:
        app_logger.error(f"Instance export failed ({component_id}/{instance_id}): {e}", exc_info=True)
        return jsonify({"status": "error", "message": "Export failed"}), 500
    raw = f"{component_id}_{envelope.get('name') or instance_id}".replace(' ', '_')
    safe = re.sub(r'[^A-Za-z0-9_.-]', '', raw) or component_id
    # the one exit of a server-built export: the tier's download policy + the audit, or ?to=files
    from trusted_data_agent.api.files_routes import export_response
    return await export_response(user_uuid, json.dumps(envelope, indent=2), f"{safe}.json", "application/json",
                                 what=f"{component_id} instance", component_id=component_id,
                                 instance_id=str(instance_id), resource=f"{component_id}:{instance_id}")


@rest_api_bp.route("/v1/components/<component_id>/instances/import", methods=["POST"])
@require_auth
async def import_component_instance(current_user, component_id):
    """Import a component instance. Two-phase:
      dry_run=true  → returns a preflight report (auto-maps + decisions needed)
      dry_run=false → commits using the dialog-supplied `mapping`, returns the id.
    """
    user_uuid = _get_user_uuid_from_request()
    handler = _get_instance_io_handler(component_id)
    if not handler:
        return jsonify({"status": "error", "message": f"Component '{component_id}' does not support instance import"}), 400
    body = await request.get_json(silent=True) or {}
    payload = body.get("payload")
    if not isinstance(payload, dict):
        return jsonify({"status": "error", "message": "Missing or invalid import payload"}), 400
    try:
        result = await handler.import_instance(
            payload,
            {"user_uuid": user_uuid},
            mode=body.get("mode", "create"),
            target_id=body.get("target_id"),
            mapping=body.get("mapping"),
            dry_run=bool(body.get("dry_run")),
        )
        return jsonify(result)
    except ValueError as e:
        return jsonify({"status": "error", "message": str(e)}), 400
    except Exception as e:
        app_logger.error(f"Instance import failed ({component_id}): {e}", exc_info=True)
        return jsonify({"status": "error", "message": "Import failed"}), 500


@rest_api_bp.route("/v1/knowledge-graph/export", methods=["GET"])
@require_auth
async def kg_export(current_user):
    """Export a knowledge graph as a downloadable JSON file."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    profile_id = request.args.get("profile_id")
    kg_id_param = request.args.get("kg_id")

    if not profile_id and not kg_id_param:
        return jsonify({"status": "error", "message": "profile_id or kg_id query parameter is required"}), 400

    try:
        from components.builtin.knowledge_graph.graph_store import GraphStore as _GS

        if kg_id_param:
            import sqlite3 as _sq
            _c = _sq.connect(str(DB_PATH))
            _row = _c.execute(
                "SELECT profile_id FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                (kg_id_param, user_uuid)
            ).fetchone()
            _c.close()
            if not _row:   # not the caller's graph — never read or clear another user's by id
                raise _KGNotFound(kg_id_param)
            owner_pid = _row[0]
            store = _GS(profile_id=owner_pid, user_uuid=user_uuid, kg_id=kg_id_param)
            if not profile_id:
                profile_id = owner_pid
        else:
            store = _get_graph_store(user_uuid, profile_id)
        entities, relationships = await store.export_graph()  # complete, count-derived
        stats = await store.get_stats()

        # Fetch KG metadata (name, description, database_name)
        kg_meta = {}
        try:
            import sqlite3 as _sq_m
            _cm = _sq_m.connect(str(DB_PATH))
            _mr = _cm.execute(
                "SELECT kg_id, name, description, database_name FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                (store.kg_id, user_uuid)
            ).fetchone()
            _cm.close()
            if _mr:
                kg_meta = {
                    "kg_id": _mr[0],
                    "kg_name": _mr[1] or "",
                    "kg_description": _mr[2] or "",
                    "kg_database_name": _mr[3] or "",
                }
        except Exception:
            pass

        # Resolve profile name for the export
        profile_name = profile_id
        profile_tag = ""
        try:
            from trusted_data_agent.core.config_manager import get_config_manager
            config_manager = get_config_manager()
            profiles = config_manager.get_profiles(user_uuid)
            profile = next((p for p in profiles if p.get("id") == profile_id), None)
            if profile:
                profile_name = profile.get("name", profile_id)
                profile_tag = profile.get("tag", "")
        except Exception:
            pass  # Use profile_id as fallback name

        export_data = {
            "export_version": "2.0",
            "kg_id": store.kg_id,
            **kg_meta,
            "profile_id": profile_id,
            "profile_name": profile_name,
            "profile_tag": profile_tag,
            "exported_at": datetime.now(timezone.utc).isoformat(),
            "stats": stats,
            "entities": entities,
            "relationships": relationships,
        }

        # Build filename — prefer KG name, fall back to profile tag
        timestamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
        name_part = kg_meta.get("kg_name", "").strip()
        if name_part:
            safe_name = re.sub(r"[^a-zA-Z0-9_-]", "_", name_part)[:40]
            tag_part = f"-{safe_name}"
        else:
            tag_part = f"-{profile_tag}" if profile_tag else ""

        # --- Open-standards export (Tier 4.1) -----------------------------
        # `format=json` (default) is the existing behaviour, byte-identical.
        # Any RDF format re-serializes the SAME export_data via the pure
        # semantic_interchange converter (SKOS/OWL/RDF Data Cube/PROV/DCAT).
        fmt = (request.args.get("format") or "json").strip().lower()
        if fmt != "json":
            from trusted_data_agent.semantic_interchange import (
                convert_kg, serialize as _rdf_serialize, mime_for, normalize, VALID_FORMATS,
            )
            if fmt not in VALID_FORMATS:
                return jsonify({"status": "error",
                                "message": f"unsupported format '{fmt}' (use: json, {', '.join(VALID_FORMATS)})"}), 400
            serialization = request.args.get("serialization") or "turtle"
            try:
                norm = normalize(serialization)
            except ValueError as ve:
                return jsonify({"status": "error", "message": str(ve)}), 400
            try:
                graph = convert_kg(export_data, vocab=fmt)
                body = _rdf_serialize(graph, serialization)
            except Exception as e:
                app_logger.error(f"KG open-standards export failed: {e}", exc_info=True)
                return jsonify({"status": "error", "message": str(e)}), 500
            ext = {"turtle": "ttl", "ttl": "ttl", "jsonld": "jsonld", "json-ld": "jsonld",
                   "xml": "rdf", "rdfxml": "rdf", "rdf-xml": "rdf",
                   "nt": "nt", "ntriples": "nt", "n-triples": "nt"}.get(norm, "ttl")
            filename = f"knowledge-graph{tag_part}-{timestamp}.{ext}"
            from trusted_data_agent.api.files_routes import export_response
            return await export_response(user_uuid, body, filename, mime_for(serialization),
                                         what=f"knowledge graph ({fmt})", component_id="knowledge_graph",
                                         instance_id=store.kg_id, profile_id=profile_id,
                                         resource=f"knowledge_graph:{store.kg_id}")

        export_json = json.dumps(export_data, indent=2, default=str)
        filename = f"knowledge-graph{tag_part}-{timestamp}.json"
        from trusted_data_agent.api.files_routes import export_response
        return await export_response(user_uuid, export_json, filename, "application/json",
                                     what="knowledge graph", component_id="knowledge_graph",
                                     instance_id=store.kg_id, profile_id=profile_id,
                                     resource=f"knowledge_graph:{store.kg_id}")
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"Knowledge graph export failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


class _KGNotFound(LookupError):
    """A ``kg_id`` that is not one of the caller's graphs — answered as not found."""


def _kg_not_found():
    return jsonify({"status": "error", "message": "Knowledge graph not found"}), 404


def _resolve_kg_store_for_request(user_uuid, profile_id, kg_id_param):
    """Resolve a GraphStore from kg_id (preferred, owner-profile lookup) or
    profile_id — the shared pattern used across the KG endpoints.

    A ``kg_id`` must be one of the caller's own graphs: the store reads a graph by its id for
    whoever asks, so until Nov 2026 any signed-in user could read — and transition, since
    the lifecycle route passes ``is_owner=True`` — another user's ontology by its id. A foreign
    id now raises ``_KGNotFound`` (the caller answers 404, never revealing that it exists)."""
    from components.builtin.knowledge_graph.graph_store import GraphStore as _GS
    if kg_id_param:
        _c = sqlite_util.connect(str(DB_PATH))
        try:
            _row = _c.execute(
                "SELECT profile_id FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                (kg_id_param, user_uuid),
            ).fetchone()
        finally:
            _c.close()
        if not _row:
            raise _KGNotFound(kg_id_param)
        return _GS(profile_id=_row[0], user_uuid=user_uuid, kg_id=kg_id_param)
    return _get_graph_store(user_uuid, profile_id)


@rest_api_bp.route("/v1/knowledge-graph/metrics/<path:metric_name>/export", methods=["GET"])
@require_auth
async def kg_metric_export(current_user, metric_name):
    """Export one semantic metric as W3C RDF Data Cube (QB) + PROV lineage (+ DCAT).

    ?format=qb|prov|dcat|all (default all) · ?serialization=turtle|jsonld|xml|nt
    · ?include_sql=true attaches the compiled-SQL annotation (dialect-specific).
    """
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    profile_id = request.args.get("profile_id")
    kg_id_param = request.args.get("kg_id")
    if not profile_id and not kg_id_param:
        return jsonify({"status": "error", "message": "profile_id or kg_id query parameter is required"}), 400

    try:
        store = _resolve_kg_store_for_request(user_uuid, profile_id, kg_id_param)
        entity = store.get_entity_by_name(metric_name, "metric")
        if not entity:
            return jsonify({"status": "error", "message": f"metric '{metric_name}' not found"}), 404

        # Resolve the deployed view / base table for PROV lineage (best-effort).
        deployment = None
        try:
            from components.builtin.knowledge_graph.resolver import resolve_metric_deployment
            dep = await resolve_metric_deployment(store, metric_name)
            if dep and (dep.view or dep.column or dep.base_table):
                deployment = {"view": dep.view, "column": dep.column,
                              "base_table": dep.base_table,
                              "infrastructure": dep.infrastructure}
        except Exception:
            deployment = None

        include_sql = str(request.args.get("include_sql", "")).strip().lower() in ("1", "true", "yes")
        if include_sql:
            try:
                from trusted_data_agent.dbdeploy.metric_compiler import (
                    resolve_metric_from_entity, compile_metric,
                )
                mdef, src_tbl = resolve_metric_from_entity(entity.get("properties") or {})
                base = (deployment or {}).get("base_table") or src_tbl
                # A direct column mapping is read, not aggregated — skip the
                # (aggregate) compiled-SQL annotation for it.
                if base and not (deployment or {}).get("column"):
                    cr = compile_metric(mdef, source_table=base)
                    deployment = dict(deployment or {})
                    deployment["compiled_sql"] = cr.sql
            except Exception:
                pass  # SQL is an optional annotation — never block the export

        from trusted_data_agent.semantic_interchange import (
            convert_metric, serialize as _rdf_serialize, mime_for, normalize,
        )
        serialization = request.args.get("serialization") or "turtle"
        try:
            norm = normalize(serialization)
        except ValueError as ve:
            return jsonify({"status": "error", "message": str(ve)}), 400

        metric_entity = {"name": metric_name, "entity_type": "metric",
                         "properties": entity.get("properties") or {}}
        graph = convert_metric(metric_entity, kg_id=store.kg_id,
                               deployment=deployment, include_sql=include_sql)
        body = _rdf_serialize(graph, serialization)

        ext = {"turtle": "ttl", "ttl": "ttl", "jsonld": "jsonld", "json-ld": "jsonld",
               "xml": "rdf", "rdfxml": "rdf", "nt": "nt", "ntriples": "nt"}.get(norm, "ttl")
        safe = re.sub(r"[^a-zA-Z0-9_-]", "_", metric_name)[:48]
        from trusted_data_agent.api.files_routes import export_response
        return await export_response(user_uuid, body, f"metric-{safe}.{ext}", mime_for(serialization),
                                     what="metric", component_id="knowledge_graph", instance_id=store.kg_id,
                                     profile_id=profile_id, resource=f"knowledge_graph:{store.kg_id}:{metric_name}")
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"KG metric export failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


# ─── Governed Metric Semantic API for BI (Tier 4.2 / T3) ──────────────────────
# "Define once, consume everywhere." A metric is defined once in the ontology and
# consumed by both the agent (the compile_metric tool) and BI tools (these endpoints),
# through the SAME pure semantic core (components/builtin/knowledge_graph/metric_api.py)
# — so the AI and BI faces of a metric can never drift. Governed: tier-gated, ownership-
# scoped, and the source ontology's lifecycle/trust/conformance state is surfaced so a BI
# consumer knows whether the metric comes from a governed, trusted ontology.

def _metric_store_for_profile(user_uuid, profile_id, kg_id_param=None):
    """Resolve the GraphStore serving a profile's metrics: an explicit ?kg_id wins, else the
    profile's *active* KG (via kg_profile_assignments — the same resolution the agent uses)."""
    if kg_id_param:
        return _resolve_kg_store_for_request(user_uuid, profile_id, kg_id_param)
    owner_pid = _resolve_active_kg_owner_profile(user_uuid, profile_id)
    return _get_graph_store(user_uuid, owner_pid)


def _ontology_governance_context(store, *, include_conformance=False):
    """Best-effort governed-ontology context for a metric response (never raises).

    Surfaces the source ontology's identity + lifecycle (Tier 4.3) + trust badge (Tier 5.2),
    so a BI consumer sees *whether the metric comes from a governed, trusted ontology*. Trust
    lives in the optional (removable) Ontology Suite → imported defensively; absent → omitted.
    """
    ctx = {"kg_id": getattr(store, "kg_id", None), "lifecycle_status": None,
           "semantic_version": None, "trust_state": None}
    try:
        state = store.get_lifecycle_state() or {}
        ctx["lifecycle_status"] = state.get("lifecycle_status")
        ctx["semantic_version"] = state.get("semantic_version")
    except Exception:
        pass
    try:  # trust is part of the isolatable Ontology Suite — tolerate its absence
        from trusted_data_agent.api.trust_routes import _resolve_artifact_state
        if ctx["kg_id"]:
            ctx["trust_state"] = _resolve_artifact_state("ontology", str(ctx["kg_id"]))
    except Exception:
        pass
    return ctx


@rest_api_bp.route("/v1/profiles/<profile_id>/metrics", methods=["GET"])
@operation("profiles.metrics", effect="read", scope="own",
           summary="The metric catalog of an agent's ontology, one summary row per metric",
           path={"profile_id": "the agent's (profile's) id"},
           query={"kg_id": "an ontology other than the agent's active one"})
@require_auth
async def profile_metrics_catalog(current_user, profile_id):
    """The metric catalog for a profile's active ontology — every metric as a summary row
    (name, description, dim/measure counts, deployed realization, queryable, access scope).
    The BI discovery surface. ?kg_id= targets a specific ontology."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    try:
        from components.builtin.knowledge_graph.metric_api import list_metric_catalog
        store = _metric_store_for_profile(user_uuid, profile_id, request.args.get("kg_id"))
        metrics = await list_metric_catalog(store)
        return jsonify({
            "status": "success",
            "profile_id": profile_id,
            "ontology": _ontology_governance_context(store),
            "count": len(metrics),
            "metrics": metrics,
        })
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"metric catalog failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/profiles/<profile_id>/metrics/<path:metric_name>", methods=["GET"])
@operation("profiles.metric", effect="read", scope="own",
           summary="A metric's governed definition (dimensions, measures, source)",
           path={"profile_id": "the agent's (profile's) id", "metric_name": "the metric's name"},
           query={"include_conformance": Arg("boolean", "also report how the source conforms to the definition"),
                  "kg_id": "an ontology other than the agent's active one"})
@require_auth
async def profile_metric_get(current_user, profile_id, metric_name):
    """A metric's full governed semantics: definition (dimensions/measures/source) + the
    default compiled SQL + the deployed-view/column pointer + access scope + the source
    ontology's governance/trust state + an open-standards (RDF Data Cube) export link.

    ?include_conformance=true adds the ontology conformance status (heavier — loads the graph).
    """
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    try:
        from components.builtin.knowledge_graph.metric_api import resolve_metric_semantics
        store = _metric_store_for_profile(user_uuid, profile_id, request.args.get("kg_id"))
        sem = await resolve_metric_semantics(store, metric_name)
        if not sem.found:
            return jsonify({"status": "error", "message": sem.error
                            or f"metric '{metric_name}' not found"}), 404

        ontology = _ontology_governance_context(store)
        if str(request.args.get("include_conformance", "")).strip().lower() in ("1", "true", "yes"):
            try:
                from trusted_data_agent.kgstore.conformance import check_conformance
                ents = await store.list_entities(limit=999999)
                rels = await store.list_relationships(limit=999999)
                ontology["conformance_status"] = check_conformance(ents, rels).status
            except Exception:
                ontology["conformance_status"] = None

        from urllib.parse import quote
        body = sem.to_dict()
        body["status"] = "success"
        body["profile_id"] = profile_id
        body["ontology"] = ontology
        # Open-standards face (Tier 4.1): consume the same metric as a W3C RDF Data Cube.
        _kg = ontology.get("kg_id")
        body["standards_export"] = (
            f"/api/v1/knowledge-graph/metrics/{quote(metric_name)}/export?format=qb"
            + (f"&kg_id={quote(str(_kg))}" if _kg else f"&profile_id={quote(profile_id)}")
        )
        return jsonify(body)
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"metric get failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/profiles/<profile_id>/metrics/<path:metric_name>/compile", methods=["POST"])
@operation("profiles.metric_compile", effect="read", scope="own",
           summary="Compile a slice of a metric into governed, ready-to-run SQL (nothing runs)",
           path={"profile_id": "the agent's (profile's) id", "metric_name": "the metric's name"},
           query={"kg_id": "an ontology other than the agent's active one"},
           body={"dimensions": Arg("array", "the dimensions to group by (default: the metric's)"),
                 "measures": Arg("array", "the measures to compute (default: the metric's)")})
@require_auth
async def profile_metric_compile(current_user, profile_id, metric_name):
    """Compile a metric *slice* → ready-to-run SQL. Body: {dimensions?: [...], measures?: [...]}
    (omit = all; [] = none — a coarser grain). Deterministic, ratio-safe. The parametrized BI
    consumption surface — a BI tool picks the grain, gets governed SQL back."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    try:
        data = await request.get_json(silent=True) or {}
        dims = data.get("dimensions")
        meas = data.get("measures")
        from components.builtin.knowledge_graph.metric_api import resolve_metric_semantics
        store = _metric_store_for_profile(user_uuid, profile_id, request.args.get("kg_id"))
        sem = await resolve_metric_semantics(store, metric_name, dimensions=dims, measures=meas)
        if not sem.found:
            return jsonify({"status": "error", "message": sem.error
                            or f"metric '{metric_name}' not found"}), 404
        if sem.error or not sem.compiled_sql:
            return jsonify({"status": "error", "message": sem.error
                            or "metric could not be compiled"}), 422
        return jsonify({
            "status": "success",
            "profile_id": profile_id,
            "metric": metric_name,
            "sql": sem.compiled_sql,
            "dimensions": sem.selected_dimensions,
            "measures": sem.selected_measures,
            "source_table": sem.source_table,
            "deployed_view": sem.deployed_view,
            "deployed_column": sem.deployed_column,
            "realization": sem.realization,
            "warnings": sem.warnings,
            "access_scope": sem.access_scope,
        })
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"metric compile failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/profiles/<profile_id>/metrics/<path:metric_name>/query", methods=["POST"])
@operation("profiles.metric_query", effect="read", scope="own",
           summary="Compile a slice of a metric and run it — one read-only SELECT — on a database connection",
           path={"profile_id": "the agent's (profile's) id", "metric_name": "the metric's name"},
           query={"kg_id": "an ontology other than the agent's active one"},
           body={"dimensions": Arg("array", "the dimensions to group by (default: the metric's)"),
                 "measures": Arg("array", "the measures to compute (default: the metric's)"),
                 "connection_id": "the database connection to run on (default: the deployed one)",
                 "max_rows": Arg("integer", "the most rows to return")})
@require_auth
async def profile_metric_query(current_user, profile_id, metric_name):
    """Compile a metric slice AND execute it against a deployed database connection, returning
    rows — "consume everywhere" made literal (a BI tool / curl gets DATA, not just SQL).

    Body: {dimensions?, measures?, connection_id?, max_rows?}. The user runs it under their own
    authority (their own DB connection). Read-only by construction: only the compiled aggregate
    SELECT runs, and it is re-checked to be a single SELECT before execution.
    """
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    try:
        data = await request.get_json(silent=True) or {}
        from components.builtin.knowledge_graph.metric_api import resolve_metric_semantics
        store = _metric_store_for_profile(user_uuid, profile_id, request.args.get("kg_id"))
        sem = await resolve_metric_semantics(store, metric_name,
                                             dimensions=data.get("dimensions"),
                                             measures=data.get("measures"))
        if not sem.found:
            return jsonify({"status": "error", "message": sem.error
                            or f"metric '{metric_name}' not found"}), 404
        if sem.error or not sem.compiled_sql:
            return jsonify({"status": "error", "message": sem.error
                            or "metric could not be compiled"}), 422

        # Resolve the DB connection: explicit connection_id, else the user's default.
        from trusted_data_agent.core.database_connections import get_database_connection_store
        conn_store = get_database_connection_store()
        conn_id = data.get("connection_id")
        creds = None
        if conn_id:
            creds = conn_store.resolve(user_uuid, conn_id)
            if not creds:
                return jsonify({"status": "error", "message": f"connection '{conn_id}' not found"}), 404
        else:
            try:
                conns = conn_store.list(user_uuid) or []
                chosen = next((c for c in conns if c.get("is_default")), None) or (conns[0] if conns else None)
                if chosen:
                    creds = conn_store.resolve(user_uuid, chosen.get("id"))
            except Exception:
                creds = None
        if not creds:
            # Honest, useful degradation: the SQL is still returned so the caller can run it.
            return jsonify({
                "status": "error",
                "message": "no database connection available — pass connection_id or set a default. "
                           "The compiled SQL is returned so you can run it yourself.",
                "sql": sem.compiled_sql,
                "access_scope": sem.access_scope,
            }), 409

        # Defensive: only a single read-only SELECT ever executes here.
        sql = (sem.compiled_sql or "").strip().rstrip(";").strip()
        if not sql.lower().startswith("select") or ";" in sql:
            return jsonify({"status": "error", "message": "refusing to execute non-SELECT SQL"}), 400

        from components.builtin.canvas.connectors import get_connector
        connector = get_connector("sql_native")
        if not connector:
            return jsonify({"status": "error", "message": "SQL execution connector unavailable"}), 500
        run_creds = dict(creds)
        if run_creds.get("username") and not run_creds.get("user"):
            run_creds["user"] = run_creds["username"]
        max_rows = int(data.get("max_rows") or 1000)
        result = await connector.execute(sql, run_creds)
        if result.error:
            return jsonify({"status": "error", "message": result.error,
                            "sql": sem.compiled_sql}), 502

        # Parse the connector's TSV result into structured columns + rows.
        columns, rows = [], []
        if result.result:
            lines = result.result.split("\n")
            if lines:
                columns = lines[0].split("\t")
                for ln in lines[1:]:
                    if ln == "":
                        continue
                    rows.append(ln.split("\t"))
                    if len(rows) >= max_rows:
                        break
        return jsonify({
            "status": "success",
            "profile_id": profile_id,
            "metric": metric_name,
            "sql": sem.compiled_sql,
            "columns": columns,
            "rows": rows,
            "row_count": result.row_count,
            "returned_rows": len(rows),
            "truncated": result.row_count > len(rows),
            "execution_time_ms": result.execution_time_ms,
            "dimensions": sem.selected_dimensions,
            "measures": sem.selected_measures,
            "access_scope": sem.access_scope,
        })
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"metric query failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


# ═══════════════════════════════════════════════════════════════════════════
# OBDA-READ data products — Phase A4 (TIER_5.5_OBDA_SCOPE.md §6 C2, Phase A subset)
#
# The producer faces of the signed-data-product surface: author (create/update
# the data_product KG node), validate (run the V1–V6 gate + stamp the report),
# catalog + definition (deterministic discovery — the obda.catalog reading).
# Sign-off lives with every other sign-off in trust_routes.py (the removable
# Ontology Suite owns signing); trust STATE is read here defensively, so a
# deployment without the suite still authors and validates.
#
# EVERY endpoint is gated on the OBDA-READ component's availability (core/obda_planes) —
# fails closed with a machine-readable code, so the whole feature family can be
# switched off on demand and the baseline stays byte-identical (charter #15).
# Node writes go through GraphStore (the KG-store abstraction owns entity
# writes); trust-side code only ever READS.
# ═══════════════════════════════════════════════════════════════════════════

def _assert_obda_enabled():
    """403 when OBDA-READ is not available to this caller — the OBDA-READ component's global
    gate and the caller's per-user override (core/obda_planes). Same fail-closed shape as the
    activation firewall. Returns a response to short-circuit with, else None."""
    from trusted_data_agent.core import obda_planes as _planes
    if not _planes.plane_available("read", _get_user_uuid_from_request()):
        code, msg = _planes.off_refusal("read")
        return jsonify({"status": "error", "error": code, "message": msg}), 403
    return None


def _assert_model_enabled():
    """403 when OBDA-MODEL is not available to this caller (the OBDA-MODEL component)."""
    from trusted_data_agent.core import obda_planes as _planes
    if not _planes.plane_available("model", _get_user_uuid_from_request()):
        code, msg = _planes.off_refusal("model")
        return jsonify({"status": "error", "error": code, "message": msg}), 403
    return None


@rest_api_bp.route("/v1/obda/planes", methods=["GET"])
@require_auth
async def obda_planes_available(current_user):
    """Which OBDA planes this caller can reach — the question the UI asks before it renders
    a plane's button or node. A plane's faces need its component (core/obda_planes) AND the
    knowledge-graph feature for the caller's tier, so both are folded in here, the same pair
    the faces' own gates refuse on. Replaces probing a face with a deliberately incomplete
    request and reading its 400 vs 403, which logged an error on every page load."""
    from trusted_data_agent.core import obda_planes as _planes
    user_uuid = _get_user_uuid_from_request()
    try:
        from trusted_data_agent.kgstore.settings import is_kg_enabled_for_tier
        kg_on = bool(is_kg_enabled_for_tier(_get_user_tier(current_user)))
    except Exception as exc:  # noqa: BLE001 — a broken gate fails CLOSED, as the faces do
        app_logger.warning(f"obda planes: KG tier gate failed: {exc}")
        kg_on = False
    planes = {p: kg_on and bool(_planes.plane_available(p, user_uuid)) for p in _planes.PLANES}
    return jsonify({"status": "success", "planes": planes})


def _product_store_for(user_uuid: str, kg_id: str):
    """Ownership-checked GraphStore for a product's ontology, or (None, response)."""
    profile_id = _kg_owner_profile_for_id(user_uuid, kg_id)
    if not profile_id:
        return None, (jsonify({"status": "error",
                               "message": "Knowledge graph not found"}), 404)
    from components.builtin.knowledge_graph.graph_store import GraphStore
    return GraphStore(profile_id=profile_id, user_uuid=user_uuid, kg_id=kg_id), None


def _product_trust_state(kg_id: str, name: str) -> dict:
    """Defensive trust read — the Ontology Suite is removable; its absence reads
    as an honest 'unavailable', never as unsigned (which would claim knowledge)."""
    try:
        from trusted_data_agent.core.trust import products as _tp
        return _tp.product_state(kg_id, name)
    except Exception:
        return {"state": "unavailable"}


def _product_summary_props(parsed) -> dict:
    """The flattened tip/summary fields stamped beside the manifest (the A1
    KG_TIP_FIELDS contract: the tooltip never parses the manifest)."""
    return {
        "version": parsed.version,
        "backend": parsed.backend,
        "description": parsed.description,
        "member_entities": ", ".join(parsed.entity_names()),
        "measure_names": ", ".join(ms.name for ms in parsed.measures),
    }


def _profile_graph_id(user_uuid: str, profile_id: str) -> "str | None":
    """The graph an agent reads: its active assignment, else its own — the resolution the
    knowledge-graph tool uses (`_get_store`), so a per-agent listing and the agent's own
    tool never disagree. None when nothing is bound."""
    try:
        from components.builtin.knowledge_graph.handler import KnowledgeGraphHandler
        store = KnowledgeGraphHandler()._get_store({"profile_id": profile_id, "user_uuid": user_uuid})
        kg_id = getattr(store, "kg_id", None)
        if not kg_id:
            return None
        from trusted_data_agent.core import obda_planes as _planes
        return kg_id if _planes.profile_has_graph(profile_id, user_uuid) else None
    except Exception as exc:  # noqa: BLE001
        app_logger.debug(f"profile graph resolution failed for {profile_id}: {exc}")
        return None


@rest_api_bp.route("/v1/data-products", methods=["GET"])
@operation("data_products.catalog", effect="read", scope="own",
           summary="The data products defined on a knowledge graph — each one's measures and dimensions, its trust state and whether a validation backs it",
           query={"kg_id": Arg("string", "the knowledge graph (knowledge_graph.list lists them, with the agent each belongs to)", required=True)},
           summary_fields=("product", "description", "trust", "validated"))
@require_auth
async def obda_product_catalog(current_user):
    """The product catalog for one ontology — deterministic discovery (the
    obda.catalog reading): every product, its trust state, and whether a
    validation report backs it. `?kg_id=` required."""
    gate = _assert_obda_enabled() or _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    kg_id = (request.args.get("kg_id") or "").strip()
    # `?profile_id=` — the agent's OWN graph (the Workspace and the OBDA-READ panel ask per
    # agent, the way the actions catalog does); the active assignment, else the agent's own
    surface = None   # the agent's grant, when asked per agent: {mode, products}
    if not kg_id and (request.args.get("profile_id") or "").strip():
        _pid = request.args.get("profile_id").strip()
        kg_id = _profile_graph_id(user_uuid, _pid) or ""
        if not kg_id:
            return jsonify({"status": "success", "kg_id": None, "products": [], "count": 0,
                            "note": "no knowledge graph is bound to this agent"})
        # ONE rule for the agent's surface (obda.profile_obda), so the panel, the Workspace and
        # the agent's own list_products never disagree about what is on it
        try:
            from trusted_data_agent.core.config_manager import get_config_manager
            from trusted_data_agent.agent.obda import profile_obda
            _mode, _grant = profile_obda(get_config_manager().get_profile(_pid, user_uuid))
            surface = {"mode": _mode, "products": sorted(_grant)}
        except Exception:  # noqa: BLE001
            surface = {"mode": "off", "products": []}
        try:   # the graph's name, so a surface that opens the Designer names it
            from components.builtin.knowledge_graph.graph_store import GraphStore
            _owner = _kg_owner_profile_for_id(user_uuid, kg_id) or _pid
            _meta = GraphStore(profile_id=_owner, user_uuid=user_uuid, kg_id=kg_id).get_kg_metadata() or {}
            surface["kg_name"] = _meta.get("kg_name") or _meta.get("name") or None
        except Exception:  # noqa: BLE001 — a name is a courtesy
            surface["kg_name"] = None
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    store, err = _product_store_for(user_uuid, kg_id)
    if err:
        return err
    try:
        nodes = await store.list_entities(entity_type="data_product", limit=500)
        items = []
        for n in nodes:
            props = n.get("properties") or {}
            report = props.get("validation_report")
            items.append({
                "product": n.get("name"),
                "version": props.get("version"),
                "backend": props.get("backend"),
                "description": props.get("description") or "",
                "validated": isinstance(report, dict),
                "signable": bool(report.get("signable")) if isinstance(report, dict) else False,
                "trust": _product_trust_state(kg_id, n.get("name")),
                **({"on_surface": n.get("name") in set(surface["products"])} if surface and surface["mode"] != "off" else {}),
            })
        if surface:
            # surface rows first — the rows the agent may actually ask
            items.sort(key=lambda it: (0 if it.get("on_surface") else 1, str(it.get("product"))))
        return jsonify({"status": "success", "kg_id": kg_id,
                        "products": items, "count": len(items),
                        **({"surface": surface, "kg_name": surface.get("kg_name")} if surface else {})})
    except Exception as e:
        app_logger.error(f"OBDA-READ catalog failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/data-products", methods=["POST"])
@require_auth
@_signals.announces_route("obda_read", "created", ids=("product_name", "name"))
async def obda_product_author(current_user):
    """Author (create or update) a data product on an ontology.

    Body: {kg_id, manifest}. The manifest is parsed against every M-rule — a
    violation is a 400 carrying the machine-readable REJECT code (self-correction
    food, never a guess). An UPDATED manifest DROPS the stored validation report:
    an edited manifest invalidates its proof, and signing without a fresh gate run
    would be the rubber stamp S1 forbids. Member edges (product → entity) are
    maintained for the entities that exist on the graph; missing ones are named.
    """
    gate = _assert_obda_enabled() or _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    store, err = _product_store_for(user_uuid, kg_id)
    if err:
        return err

    from trusted_data_agent.dbdeploy.product_model import (
        ProductManifestError, flatten_composed, is_composed, parse_composed,
        parse_manifest)
    _raw_manifest = data.get("manifest")
    try:
        if is_composed(_raw_manifest):
            # §8 — a composed product authors as members + bridges; its members
            # must EXIST here (the flatten proves it and every collision rule),
            # and the FLAT form must parse — refused with the verbatim REJECT.
            cm = parse_composed(_raw_manifest)
            _member_raw = {}
            for _m in cm.members:
                _mn = store.get_entity_by_name(_m, "data_product")
                _mraw = ((_mn or {}).get("properties") or {}).get("manifest")
                if isinstance(_mraw, dict):
                    _member_raw[_m] = _mraw
            parsed = parse_manifest(flatten_composed(cm, _member_raw))
            _stored_manifest = cm.to_dict()
        else:
            parsed = parse_manifest(_raw_manifest)
            _stored_manifest = parsed.to_dict()
    except ProductManifestError as e:
        return jsonify({"status": "error", "error": e.code,
                        "message": e.message}), 400

    try:
        props = {"layer": "logical",
                 "manifest": _stored_manifest,
                 **_product_summary_props(parsed)}
        existing = store.get_entity_by_name(parsed.product, "data_product")
        if existing:
            # Update in place. update_entity MERGES properties (backend contract),
            # so the old validation report must be cleared EXPLICITLY — an edited
            # manifest invalidates its proof, and leaving the stale report in
            # place would make this endpoint's own "re-validate" note a lie (the
            # A3 stale_report check would still refuse the sign, but a contract
            # that only holds because a deeper gate catches the breach is not a
            # contract).
            props["validation_report"] = None
            await store.update_entity(existing["id"], properties=props)
            product_id = existing["id"]
            action = "updated"
        else:
            product_id = await store.add_entity(
                parsed.product, "data_product", properties=props,
                source="manual", source_detail="obda_designer")
            action = "created"

        # member edges — only for entities present on the graph; absentees named
        linked, missing = [], []
        have = {r.get("target_name") for r in
                await store.list_relationships(entity_id=product_id,
                                               relationship_type="member",
                                               limit=500)}
        for ename in parsed.entity_names():
            ent = store.get_entity_by_name(ename, "entity")
            if not ent:
                missing.append(ename)
                continue
            if ename not in have:
                await store.add_relationship(product_id, ent["id"], "member",
                                             source="obda_designer")
            linked.append(ename)
        return jsonify({
            "status": "success", "action": action, "kg_id": kg_id,
            "product": parsed.product, "version": parsed.version,
            "members_linked": linked, "members_missing": missing,
            "note": ("the stored validation report was dropped — the manifest "
                     "changed, so re-validate before signing"
                     if action == "updated" else
                     "validate next — the signature is earned (V1–V6), never a "
                     "rubber stamp"),
        }), (200 if action == "updated" else 201)
    except Exception as e:
        app_logger.error(f"OBDA-READ author failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/data-products/<product_name>", methods=["GET"])
@operation("data_products.get", effect="read", scope="own",
           summary="One data product's full definition: its manifest, its validation report and which combinations are safe to ask",
           path={"product_name": "the product (data_products.catalog lists them)"},
           query={"kg_id": Arg("string", "its knowledge graph", required=True)})
@require_auth
async def obda_product_definition(current_user, product_name):
    """Full definition: the manifest, the stored validation report (incl. the
    grain-safety matrix — the admissible map, §3.2), and the trust state."""
    gate = _assert_obda_enabled() or _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    kg_id = (request.args.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    store, err = _product_store_for(user_uuid, kg_id)
    if err:
        return err
    try:
        node = store.get_entity_by_name(product_name, "data_product")
        if not node:
            return jsonify({"status": "error",
                            "message": f"no data product named '{product_name}'"}), 404
        props = node.get("properties") or {}
        # The admissible map (§3.2): what is askable, published BEFORE asking —
        # derived from the same grain function the compiler enforces, so a
        # query-time grain_conflict can only mean the consumer ignored it (G3).
        admissible = None
        try:
            from trusted_data_agent.dbdeploy.product_compiler import admissible_map
            from trusted_data_agent.dbdeploy.product_model import (
                load_flat_manifest, parse_manifest)
            _flat, _cm, _fe = load_flat_manifest(store, product_name)
            if _fe is None and isinstance(_flat, dict):
                admissible = admissible_map(parse_manifest(_flat))
        except Exception:
            pass   # an unparseable manifest still serves its raw definition
        return jsonify({
            "status": "success", "kg_id": kg_id, "product": product_name,
            "manifest": props.get("manifest"),
            "validation_report": props.get("validation_report"),
            "admissible": admissible,
            "trust": _product_trust_state(kg_id, product_name),
        })
    except Exception as e:
        app_logger.error(f"OBDA-READ definition failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


async def _obda_execute_readonly(user_uuid: str, sql: str,
                                 connection_id, max_rows: int):
    """Execute ONE read-only SELECT under the caller's own DB connection.

    The product face's execution seam (Phase B3), mirroring the metric query
    endpoint's proven machinery (which predates this helper and keeps its inline
    copy until a byte-equivalence pass unifies them — the A3 posture). Returns
    (payload_dict, http_status); read-only by construction: a single SELECT is
    re-checked before anything runs.
    """
    from trusted_data_agent.core.database_connections import get_database_connection_store
    conn_store = get_database_connection_store()
    creds = None
    if connection_id:
        creds = conn_store.resolve(user_uuid, connection_id)
        if not creds:
            return {"status": "error",
                    "message": f"connection '{connection_id}' not found"}, 404
    else:
        try:
            conns = conn_store.list(user_uuid) or []
            chosen = next((c for c in conns if c.get("is_default")), None) \
                or (conns[0] if conns else None)
            if chosen:
                creds = conn_store.resolve(user_uuid, chosen.get("id"))
        except Exception:
            creds = None
    if not creds:
        return {"status": "error",
                "message": "no database connection available — pass connection_id "
                           "or set a default. The compiled SQL is returned so you "
                           "can run it yourself.", "sql": sql}, 409

    body = (sql or "").strip().rstrip(";").strip()
    if not body.lower().startswith("select") or ";" in body:
        return {"status": "error",
                "message": "refusing to execute non-SELECT SQL"}, 400

    from components.builtin.canvas.connectors import get_connector
    connector = get_connector("sql_native")
    if not connector:
        return {"status": "error",
                "message": "SQL execution connector unavailable"}, 500
    run_creds = dict(creds)
    if run_creds.get("username") and not run_creds.get("user"):
        run_creds["user"] = run_creds["username"]
    result = await connector.execute(body, run_creds)
    if result.error:
        return {"status": "error", "message": result.error, "sql": sql}, 502
    columns, rows = [], []
    if result.result:
        lines = result.result.split("\n")
        if lines:
            columns = lines[0].split("\t")
            for ln in lines[1:]:
                if ln == "":
                    continue
                rows.append(ln.split("\t"))
                if len(rows) >= max_rows:
                    break
    return {"status": "success", "columns": columns, "rows": rows,
            "row_count": result.row_count, "returned_rows": len(rows),
            "truncated": result.row_count > len(rows),
            "execution_time_ms": result.execution_time_ms}, 200


@rest_api_bp.route("/v1/data-products/<product_name>/compile", methods=["POST"])
@operation("data_products.compile", effect="read", scope="own",
           summary="Turn a request against a data product into the SQL it would run — nothing is run; a refused request names the closest valid names",
           path={"product_name": "the product"},
           body={"kg_id": Arg("string", "its knowledge graph", required=True),
                 "request": Arg("object", "measures, dimensions, time grain, filters, order, limit", required=True)},
           notes="Running it is the agent's own data access (TDA_DataProduct), under its authority — not offered here.")
@require_auth
async def obda_product_compile(current_user, product_name):
    """Compile a REQUEST against a product — deterministic SQL back, no execution.

    Body: {kg_id, request}. The request is the §3 contract (measures/dimensions/
    time_grain/filters/order_by/limit, or the entity-read form). A REJECT is a 422
    carrying the machine-readable code + the closest declared names — the BI face
    gets the same self-correction food as the agent."""
    gate = _assert_obda_enabled() or _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    store, err = _product_store_for(user_uuid, kg_id)
    if err:
        return err
    from trusted_data_agent.dbdeploy.product_model import (
        ProductManifestError, parse_manifest)
    from trusted_data_agent.dbdeploy.product_compiler import (
        ProductRequestError, compile_request)
    try:
        node = store.get_entity_by_name(product_name, "data_product")
        if not node:
            return jsonify({"status": "error",
                            "message": f"no data product named '{product_name}'"}), 404
        try:
            from trusted_data_agent.dbdeploy.product_model import load_flat_manifest
            _flat, _cm, _fe = load_flat_manifest(store, product_name)
            if _fe is not None:
                raise _fe
            parsed = parse_manifest(_flat)
        except ProductManifestError as e:
            return jsonify({"status": "error", "error": e.code,
                            "message": e.message}), 422
        try:
            compiled = compile_request(parsed, data.get("request") or {})
        except ProductRequestError as e:
            return jsonify({"status": "error", "error": e.code,
                            "message": e.message}), 422
        return jsonify({
            "status": "success", "kg_id": kg_id, "product": product_name,
            "sql": compiled.sql,
            "measures": list(compiled.measures),
            "dimensions": list(compiled.dimensions),
            "anchors": list(compiled.anchors),
            "request_hash": compiled.request_hash,
            "warnings": list(compiled.warnings),
            "trust": _product_trust_state(kg_id, product_name),
        })
    except Exception as e:
        app_logger.error(f"OBDA-READ compile failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/data-products/<product_name>/query", methods=["POST"])
@require_auth
async def obda_product_query(current_user, product_name):
    """Compile AND execute a request → rows + the provenance stamp.

    Body: {kg_id, request, connection_id?, max_rows?}. Runs under the caller's
    own DB connection (their own authority); read-only by construction. The
    response carries the provenance stub — product, version, request_hash,
    row_count, trust state — the receipt the agent face seals into the EPC
    chain (O2)."""
    gate = _assert_obda_enabled() or _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    store, err = _product_store_for(user_uuid, kg_id)
    if err:
        return err
    from trusted_data_agent.dbdeploy.product_model import (
        ProductManifestError, parse_manifest)
    from trusted_data_agent.dbdeploy.product_compiler import (
        ProductRequestError, compile_request)
    try:
        node = store.get_entity_by_name(product_name, "data_product")
        if not node:
            return jsonify({"status": "error",
                            "message": f"no data product named '{product_name}'"}), 404
        try:
            from trusted_data_agent.dbdeploy.product_model import load_flat_manifest
            _flat, _cm, _fe = load_flat_manifest(store, product_name)
            if _fe is not None:
                raise _fe
            parsed = parse_manifest(_flat)
        except ProductManifestError as e:
            return jsonify({"status": "error", "error": e.code,
                            "message": e.message}), 422
        try:
            compiled = compile_request(parsed, data.get("request") or {})
        except ProductRequestError as e:
            return jsonify({"status": "error", "error": e.code,
                            "message": e.message}), 422

        payload, code = await _obda_execute_readonly(
            user_uuid, compiled.sql, data.get("connection_id"),
            int(data.get("max_rows") or 1000))
        provenance = {
            "product": product_name, "kg_id": kg_id,
            "version": parsed.version,
            "request_hash": compiled.request_hash,
            "trust": _product_trust_state(kg_id, product_name),
            "lane": "governed",
        }
        payload.update({"kg_id": kg_id, "product": product_name,
                        "sql": compiled.sql, "provenance": provenance})
        if code == 200:
            payload["provenance"]["row_count"] = payload.get("row_count")
        return jsonify(payload), code
    except Exception as e:
        app_logger.error(f"OBDA-READ query failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/data-products/<product_name>", methods=["DELETE"])
@require_auth
@_signals.announces_route("obda_read", "deleted", ids=("product_name",))
async def obda_product_delete(current_user, product_name):
    """Delete a data product from its ontology (the gap the C4 acceptance recorded).

    Removes the `data_product` node (its `member` edges cascade with it) AND
    revokes the product's trust attestation — a dangling signature over a deleted
    contract is a record that attests nothing. The ontology's own hash is
    unaffected by design (`kg_content_hash` excludes product nodes), so deleting
    a product never flips the ontology's seal.
    """
    gate = _assert_obda_enabled() or _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    kg_id = (request.args.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    store, err = _product_store_for(user_uuid, kg_id)
    if err:
        return err
    try:
        node = store.get_entity_by_name(product_name, "data_product")
        if not node:
            return jsonify({"status": "error",
                            "message": f"no data product named '{product_name}'"}), 404
        await store.delete_entity(node["id"])
        try:
            from trusted_data_agent.core.trust import store as _trust_store
            from trusted_data_agent.core.trust.products import (
                PRODUCT_KIND, product_artifact_id)
            _trust_store.revoke(PRODUCT_KIND, product_artifact_id(kg_id, product_name))
        except Exception:  # noqa: BLE001 — a dangling attestation resolves unavailable, never trusted
            pass
        return jsonify({"status": "success", "kg_id": kg_id,
                        "product": product_name, "deleted": True})
    except Exception as e:
        app_logger.error(f"OBDA-READ delete failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/data-products/<product_name>/validate", methods=["POST"])
@require_auth
@_signals.announces_route("obda_read", "validated", ids=("product_name",), aspect="signature")
async def obda_product_validate(current_user, product_name):
    """Run the sign-time gate (V1–V6) and STAMP the report onto the product node.

    Evidence is gathered from the ontology itself: each entity is resolved through
    the shipped `implements` resolver (V1 in schema mode where it answers); the
    deployed column catalog is not available here, so V2/V4's column checks run
    structurally — the report states its evidence mode honestly (S2), and the
    verdict carries it into the signature.
    """
    gate = _assert_obda_enabled() or _assert_kg_enabled(current_user)
    if gate:
        return gate
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    kg_id = (data.get("kg_id") or "").strip()
    if not kg_id:
        return jsonify({"status": "error", "message": "kg_id is required"}), 400
    store, err = _product_store_for(user_uuid, kg_id)
    if err:
        return err

    from trusted_data_agent.dbdeploy.product_model import (
        ProductManifestError, parse_manifest)
    from trusted_data_agent.dbdeploy.product_validation import validate_product
    try:
        node = store.get_entity_by_name(product_name, "data_product")
        if not node:
            return jsonify({"status": "error",
                            "message": f"no data product named '{product_name}'"}), 404
        props = dict(node.get("properties") or {})
        try:
            from trusted_data_agent.dbdeploy.product_model import load_flat_manifest
            _flat, _cm, _fe = load_flat_manifest(store, product_name)
            if _fe is not None:
                raise _fe
            parsed = parse_manifest(_flat)
        except ProductManifestError as e:
            return jsonify({"status": "error", "error": e.code,
                            "message": e.message}), 422

        # V1 evidence: the ontology's own resolver (best-effort; an entity the
        # resolver cannot place resolves to None and V1 fails honestly)
        from components.builtin.knowledge_graph.resolver import resolve_deployed_table
        resolution = {}
        for ename in parsed.entity_names():
            try:
                dep = await resolve_deployed_table(store, ename)
                resolution[ename] = dep.identifier if dep else None
            except Exception:
                resolution[ename] = None

        # V7 — live probes (scope §5): opt-in via `connection_id` (or `live:true`
        # with the caller's default connection). The plan is pre-executed through
        # the SAME read-only executor as product queries and served to the pure
        # gate from a cache — validate_product stays sync/pure. No usable
        # connection ⇒ the gate runs structurally and the response says so
        # honestly rather than failing every probe on a missing connection.
        probe_fn = None
        live_note = None
        _conn_id = (data.get("connection_id") or "").strip() or None
        if _conn_id or data.get("live"):
            from trusted_data_agent.dbdeploy.product_validation import build_probe_plan
            _cache: dict = {}
            _no_conn = False
            for _probe in build_probe_plan(parsed):
                _psql = _probe.get("sql")
                if not _psql or _psql in _cache:
                    continue
                _payload, _code = await _obda_execute_readonly(
                    user_uuid, _psql, _conn_id, 5)
                if _code == 409:      # no connection at all — structural, honestly
                    _no_conn = True
                    break
                if _code != 200:
                    _cache[_psql] = RuntimeError(
                        str(_payload.get("message") or f"HTTP {_code}")[:200])
                else:
                    _cols = _payload.get("columns") or []
                    _cache[_psql] = [dict(zip(_cols, r))
                                     for r in (_payload.get("rows") or [])]
            if _no_conn:
                live_note = ("live probes requested but no database connection is "
                             "available — the gate ran structurally (pass "
                             "connection_id or set a default connection)")
            else:
                def probe_fn(sql, _c=_cache):
                    v = _c.get(sql)
                    if isinstance(v, Exception):
                        raise v
                    if v is None:
                        raise RuntimeError("probe was not executed")
                    return v

        report = validate_product(parsed, resolution=resolution, probe_fn=probe_fn)
        props["validation_report"] = report.to_dict()
        await store.update_entity(node["id"], properties=props)
        _resp = {"status": "success", "kg_id": kg_id,
                 "product": product_name,
                 "report": report.to_dict()}
        # The trust state AFTER re-proving. Validation NEVER signs (there is no
        # sign call on this path) — but if the contract is once again byte-identical
        # to what was signed, the EXISTING attestation matches and the row reads 🟢
        # with no act by the operator. The caller needs that fact to say so; without
        # it the surface implies validation signed on the operator's behalf.
        try:
            from trusted_data_agent.core.trust import products as _tp_state
            _resp["trust"] = _tp_state.product_state(kg_id, product_name)
        except Exception:
            pass                                    # a badge read never breaks a gate run
        if live_note:
            _resp["live_note"] = live_note
        return jsonify(_resp)
    except Exception as e:
        app_logger.error(f"OBDA-READ validate failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@rest_api_bp.route("/v1/knowledge-graph/import-rdf", methods=["POST"])
@require_auth
@_signals.announces_route("knowledge_graph", "imported")
async def kg_import_rdf(current_user):
    """Import an RDF document (Turtle/JSON-LD/RDF-XML/N-Triples) back into a KG.

    Lossless for Uderia's own export (the uderia: annotation layer); best-effort
    for a foreign graph (standard predicates only), with `warnings` listing what
    could not be placed. Mirrors the JSON import: create (default) or merge.

    Params (query string): serialization, mode=create|merge, profile_id,
    target_kg_id, kg_name, kg_description. Body: the raw RDF text.
    """
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()

    raw = await request.get_data(as_text=True)
    if not raw or not raw.strip():
        return jsonify({"status": "error", "message": "empty request body (send RDF text)"}), 400

    serialization = request.args.get("serialization") or "turtle"
    profile_id = request.args.get("profile_id") or "__default__"
    target_kg_id = (request.args.get("target_kg_id") or "").strip() or None

    try:
        from trusted_data_agent.semantic_interchange import parse as _rdf_parse, parse_kg, normalize
        try:
            normalize(serialization)
            graph = _rdf_parse(raw, serialization)
        except ValueError as ve:
            return jsonify({"status": "error", "message": str(ve)}), 400
        except Exception as pe:
            return jsonify({"status": "error", "message": f"could not parse RDF: {pe}"}), 400

        entities, relationships, warnings = parse_kg(graph)
        if not entities and not relationships:
            return jsonify({"status": "error", "message": "no entities or relationships found in the RDF",
                            "warnings": warnings}), 400

        import uuid as _uuid_mod
        from components.builtin.knowledge_graph.graph_store import GraphStore as _GS

        if target_kg_id:
            import sqlite3 as _sq_imp
            _ci = _sq_imp.connect(str(DB_PATH))
            _ri = _ci.execute(
                "SELECT profile_id FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                (target_kg_id, user_uuid),
            ).fetchone()
            _ci.close()
            owner_pid = _ri[0] if _ri else profile_id
            store = _GS(profile_id=owner_pid, user_uuid=user_uuid, kg_id=target_kg_id)
            result = store.import_bulk(entities, relationships)
            return jsonify({"status": "success", "kg_id": target_kg_id, "mode": "merge",
                            "warnings": warnings, **result})

        new_kg_id = str(_uuid_mod.uuid4())
        store = _GS(profile_id=profile_id, user_uuid=user_uuid, kg_id=new_kg_id)
        import sqlite3 as _sq_chk
        _cc = _sq_chk.connect(str(DB_PATH))
        _has_active = _cc.execute(
            "SELECT 1 FROM kg_metadata WHERE profile_id = ? AND user_uuid = ? AND is_active = 1 LIMIT 1",
            (profile_id, user_uuid),
        ).fetchone() is not None
        _cc.close()
        kg_name = (request.args.get("kg_name") or "").strip() or "Imported (RDF) Knowledge Graph"
        kg_description = (request.args.get("kg_description") or "").strip() or None
        store.set_kg_metadata(name=kg_name, database_name="", description=kg_description,
                              is_active=not _has_active)
        result = store.import_bulk(entities, relationships)
        return jsonify({"status": "success", "kg_id": new_kg_id, "mode": "create",
                        "warnings": warnings, **result})
    except Exception as e:
        app_logger.error(f"KG RDF import failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


# ── Ontology as a governed product (Tier 4.3) ──────────────────────────────────

_LIFECYCLE_ACTIONS = {"propose", "approve", "reject", "publish", "deprecate"}


@rest_api_bp.route("/v1/knowledge-graph/<kg_id>/lifecycle", methods=["GET"])
@operation("knowledge_graph.lifecycle", effect="read", scope="own",
           summary="Where an ontology stands in its lifecycle — draft, proposed, approved, published, deprecated — with its version and its audit trail",
           path={"kg_id": "the knowledge graph (knowledge_graph.list lists them)"})
@require_auth
async def kg_lifecycle_state(current_user, kg_id):
    """Current lifecycle state + governance policy + audit trail for one ontology."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    try:
        store = _resolve_kg_store_for_request(user_uuid, None, kg_id)
        from trusted_data_agent.kgstore import settings as kg_settings
        policy = kg_settings.get_ontology_governance_policy()
        # who acted, as a person reads it ("you", a username); a row from before the actor was
        # stored names only the tier
        audit = store.get_lifecycle_audit(limit=100)
        try:
            names = _usernames_for(sorted({a["actor"] for a in audit if a.get("actor") and a["actor"] != user_uuid}))
        except Exception:  # noqa: BLE001 — a label is a courtesy
            names = {}
        for a in audit:
            act = a.get("actor")
            a["actor_label"] = ("you" if act == user_uuid else (names.get(act) or "another user")) if act \
                else (f"an {a['actor_tier']}" if str(a.get("actor_tier") or "")[:1] in "aeiou" and a.get("actor_tier")
                      else (f"a {a['actor_tier']}" if a.get("actor_tier") else ""))
        return jsonify({
            "status": "success", "kg_id": kg_id,
            "lifecycle": store.get_lifecycle_state(),
            "policy": {"require_approval": policy.require_approval,
                       "approver_tiers": sorted(policy.approver_tiers),
                       "block_nonconformant_publish": policy.block_nonconformant_publish},
            "audit": audit,
        })
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"KG lifecycle state failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


