@rest_api_bp.route("/v1/knowledge-graph/<kg_id>/lifecycle/<action>", methods=["POST"])
@operation("knowledge_graph.lifecycle_transition", effect="human_only", scope="own", governs=True,
           summary="Move an ontology along its lifecycle — propose, approve, reject, publish, deprecate — each a person's decision",
           path={"kg_id": "the knowledge graph (knowledge_graph.list lists them)", "action": "propose · approve · reject · publish · deprecate"})
@require_auth
async def kg_lifecycle_transition(current_user, kg_id, action):
    """Run a governance transition (propose/approve/reject/publish/deprecate).
    Publish is conformance-gated. Body: {semantic_version?, version_id?, override_nonconformant?}."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    if action not in _LIFECYCLE_ACTIONS:
        return jsonify({"status": "error", "message": f"unknown action '{action}'"}), 400
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    try:
        store = _resolve_kg_store_for_request(user_uuid, None, kg_id)
        from trusted_data_agent.core import ontology_governance
        result = await ontology_governance.run_transition(
            store, action, user_uuid=user_uuid,
            actor_tier=_get_user_tier(current_user), is_owner=True,
            semantic_version=data.get("semantic_version"),
            version_id=data.get("version_id"),
            override_nonconformant=bool(data.get("override_nonconformant")),
        )
        code = 200 if result.get("allowed") else 409
        return jsonify({"status": "success" if result.get("allowed") else "blocked",
                        "kg_id": kg_id, **result}), code
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"KG lifecycle transition failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


