@rest_api_bp.route("/v1/ontologies/<kg_id>", methods=["GET"])
@require_auth
async def ontology_published(current_user, kg_id):
    """Serve the **published** version of an ontology, content-negotiated to open
    standards (Turtle/JSON-LD/RDF-XML/N-Triples via Tier 4.1) or native JSON.
    `?version=` pins a snapshot; `?format=owl|skos|rdf` selects the vocabulary."""
    guard = _assert_kg_enabled(current_user)
    if guard:
        return guard
    user_uuid = _get_user_uuid_from_request()
    try:
        store = _resolve_kg_store_for_request(user_uuid, None, kg_id)
        state = store.get_lifecycle_state()
        if state.get("lifecycle_status") != "published":
            return jsonify({"status": "error", "message": "ontology is not published"}), 409
        version_id = request.args.get("version") or state.get("published_version_id")
        from trusted_data_agent.core import kg_version_db
        graph_data = kg_version_db.get_version_graph(version_id, store.kg_id, user_uuid) if version_id else None
        if not graph_data:
            return jsonify({"status": "error", "message": "no published snapshot found"}), 404

        meta = store.get_kg_metadata() or {}
        export_data = {
            "kg_id": store.kg_id, "kg_name": meta.get("name"),
            "kg_description": meta.get("description"),
            "semantic_version": state.get("semantic_version"),
            "entities": graph_data["entities"], "relationships": graph_data["relationships"],
        }

        # Content negotiation: explicit ?serialization wins; else sniff Accept.
        serialization = request.args.get("serialization")
        accept = (request.headers.get("Accept") or "").lower()
        if not serialization:
            if "ld+json" in accept or "json-ld" in accept:
                serialization = "jsonld"
            elif "rdf+xml" in accept:
                serialization = "xml"
            elif "n-triples" in accept:
                serialization = "nt"
            elif "application/json" in accept:
                return jsonify({"status": "success", **export_data})
            else:
                serialization = "turtle"

        from quart import Response
        from trusted_data_agent.semantic_interchange import (
            convert_kg, serialize as _rdf_serialize, mime_for, normalize, VALID_FORMATS,
        )
        fmt = (request.args.get("format") or "rdf").strip().lower()
        if fmt not in VALID_FORMATS:
            fmt = "rdf"
        try:
            normalize(serialization)
        except ValueError as ve:
            return jsonify({"status": "error", "message": str(ve)}), 400
        graph = convert_kg(export_data, vocab=fmt)
        body = _rdf_serialize(graph, serialization)
        return Response(body, mimetype=mime_for(serialization))
    except _KGNotFound:
        return _kg_not_found()
    except Exception as e:
        app_logger.error(f"Published ontology serve failed: {e}", exc_info=True)
        return jsonify({"status": "error", "message": str(e)}), 500


