@rest_api_bp.route("/v1/evals/datasets", methods=["GET", "POST"])
@require_auth
async def evals_datasets(current_user):
    denied = _eval_store_gate(current_user)   # TC-34: the offline store is instance-global
    if denied:
        return denied
    from trusted_data_agent.eval.store import get_eval_store
    store = get_eval_store()
    if request.method == "GET":
        return jsonify({"datasets": store.list_datasets()}), 200
    data = await request.get_json() or {}
    did = (data.get("id") or "").strip()
    if not did:
        return jsonify({"error": "id is required"}), 400
    ds = store.create_dataset(did, data.get("name", did), data.get("description", ""),
                              is_holdout=bool(data.get("is_holdout")))
    return jsonify({"dataset": ds}), 201


