class _BadParam(ValueError):
    """TC-71: a request parameter that failed numeric coercion — mapped to a 400."""
    def __init__(self, name):
        super().__init__(f"{name} must be a number")
        self.name = name


def _coerce_int(raw, name, default, lo=None, hi=None):
    """Coerce a numeric request parameter; raises _BadParam (→ 400) on garbage, clamps."""
    if raw is None or raw == "":
        v = default
    else:
        try:
            v = int(raw)
        except (TypeError, ValueError):
            raise _BadParam(name)
    if lo is not None:
        v = max(lo, v)
    if hi is not None:
        v = min(hi, v)
    return v


def _coerce_float(raw, name, default):
    if raw is None or raw == "":
        return default
    try:
        return float(raw)
    except (TypeError, ValueError):
        raise _BadParam(name)


def _eval_store_gate(current_user):
    """TC-34 — the offline EvalStore is INSTANCE-GLOBAL (runs/scores/annotations carry no
    user column; the CLI writes them), so its read/annotate surface is an ops surface, not
    a per-user one: any authenticated user could read every run's summaries/scores and post
    unlimited annotations under any case_id — and annotations feed judge calibration (κ),
    so a low-tier user could skew calibration. Gated behind VIEW_ALL_SESSIONS (the same
    feature that gates every other cross-user evals surface). Returns an error response
    tuple to return, or None when permitted."""
    from trusted_data_agent.auth.features import user_has_feature, Feature
    if not user_has_feature(current_user, Feature.VIEW_ALL_SESSIONS):
        return jsonify({"error": "the offline eval store requires VIEW_ALL_SESSIONS"}), 403
    return None


