@rest_api_bp.route("/v1/evals/score-turn", methods=["POST"])
@operation("evals.score_turn", effect="write", scope="own",
           summary="Score one turn of the caller's conversation again — against assertions or a reference answer, optionally with model judges",
           body={"session_id": Arg("string", "the conversation", required=True), "turn": Arg("integer", "the turn number (default: the last)"),
                 "reference_answer": "what a right answer says, to compare against",
                 "assertions": Arg("object", "extra checks, e.g. {\"must_contain\": [\"42\"]}"),
                 "include_judges": Arg("boolean", "also ask model judges — costs tokens"),
                 "judge_models": Arg("integer", "how many judge models (default 3)")},
           notes="It changes nothing — the turn and its recorded verdicts stay as they are — but with judges it spends "
                 "tokens, so it follows the agent's write mode.")
@require_auth
async def evals_score_turn(current_user):
    """Score an existing session turn against ad-hoc assertions (no execution).

    Body: {session_id, turn?, profile_class?, assertions?, reference_answer?}.
    Uses the real workflow_history — the basis of the online/UX scoring path.
    """
    from trusted_data_agent.core import session_manager
    from trusted_data_agent.eval.types import EvalCase, RunRecord
    from trusted_data_agent.eval.runner import score_run_record
    data = await request.get_json() or {}
    sid = data.get("session_id")
    if not sid:
        return jsonify({"error": "session_id is required"}), 400
    user_uuid = _get_user_uuid_from_request()
    wf = await session_manager.get_workflow_history(user_uuid, sid)
    if not wf:
        return jsonify({"error": "no workflow history for session"}), 404
    # Match the requested turn robustly: workflow_history entries key the turn as
    # "turn" (and historically "turn_number"), and the id may arrive as int or str.
    # Without this, a mismatch silently fell back to the LAST turn (wrong overlay).
    turn_no = data.get("turn")

    def _turn_matches(t):
        tid = t.get("turn", t.get("turn_number"))
        return tid is not None and str(tid) == str(turn_no)

    turn = (next((t for t in wf if _turn_matches(t)), wf[-1])
            if turn_no is not None else wf[-1])
    # the attachments the turn read are evidence — read now, through the guarded manifest
    from trusted_data_agent.filestore import session_files as _sf
    turn = await asyncio.to_thread(_sf.with_attachment_evidence, user_uuid, sid, turn)
    rr = RunRecord(turn)
    # Merge admin global default thresholds (explicit per-request assertions win),
    # so the manual "Score this turn" gates the same way live scoring does.
    from trusted_data_agent.eval.online import default_assertions
    _assertions = default_assertions()
    _assertions.update(data.get("assertions") or {})
    case = EvalCase(id="adhoc", query=turn.get("user_query", ""),
                    profile_class=data.get("profile_class") or rr.profile_type or "tool_enabled",
                    assertions=_assertions,
                    reference_answer=data.get("reference_answer"))
    want_judges = bool(data.get("include_judges"))
    include_judges = want_judges
    judge_fn = None
    judges_available = None
    judge_models = []
    if want_judges:
        # Live LLM-judge panel over the user's configured providers (opt-in: costs tokens).
        from trusted_data_agent.eval.judge import build_panel
        from trusted_data_agent.eval.scorers.judges import make_judge_fn
        panel = await build_panel(user_uuid=user_uuid,
                                  max_models=int(data.get("judge_models") or 3))
        judges_available = len(panel) > 0
        if judges_available:
            judge_fn = make_judge_fn(panel)
            judge_models = panel.models
        else:
            include_judges = False  # no usable judge model — skip (no dead judge chips)
    verdicts = await score_run_record(case, rr, include_judges=include_judges, judge_fn=judge_fn)

    # Judge token cost (deterministic scoring is free). Mirror the online hook: sum
    # the panel's per-model usage and price it via CostManager so the overlay can
    # show the user what the LLM-judge pass actually cost.
    judge_in = judge_out = 0
    judge_cost = 0.0
    judge_usage = []
    if want_judges and include_judges and judge_fn is not None:
        for _p, _m, _i, _o in getattr(panel, "usage", []):
            judge_in += _i or 0
            judge_out += _o or 0
        if judge_in or judge_out:
            try:
                from trusted_data_agent.core.cost_manager import CostManager
                _cm = CostManager()
                for _p, _m, _i, _o in panel.usage:
                    judge_cost += _cm.calculate_cost(_p, _m, _i or 0, _o or 0)
                # #46 — the same per-model split as the other two judge paths, priced by
                # the same CostManager so the parts sum to the aggregate above.
                from trusted_data_agent.eval.online import judge_usage_breakdown
                judge_usage = judge_usage_breakdown(
                    list(panel.usage),
                    cost_fn=lambda p, m, i, o: _cm.calculate_cost(p, m, i, o))
            except Exception as e:
                app_logger.debug(f"score-turn: judge cost calc failed: {e}")

    # Persist the manual score as a quality span so it feeds the Agent Performance
    # roster (the same sink the online sampler writes to). A manual "Score this
    # turn" is an explicit "evaluate this agent" intent — it should count, even
    # when ambient online eval is off. Re-scores of the same turn are de-duped at
    # read time (by session.id + turn.id). Fully defensive — never breaks scoring.
    persisted = False
    try:
        import time as _time
        from trusted_data_agent.eval.online import (
            build_quality_span, sign_attestation, _get_exporter)
        sess = await session_manager.get_session(user_uuid, sid) or {}
        prof_tag = turn.get("profile_tag") or sess.get("profile_tag")
        prof_id = turn.get("profile_id") or sess.get("profile_id")
        tip = rr.provenance_meta.get("chain_tip_hash") if hasattr(rr, "provenance_meta") else None
        attestation = sign_attestation(tip, verdicts, case.profile_class)
        span = build_quality_span(
            session_id=sid, turn_id=turn.get("turn", turn.get("turn_number")),
            profile_class=case.profile_class, verdicts=verdicts, sampled=True,
            anomalous=False, attestation=attestation, started_at=_time.time(),
            profile_tag=prof_tag, profile_id=prof_id, user_uuid=user_uuid,
            library_use=rr.library_use() if hasattr(rr, "library_use") else None)
        span["attributes"]["eval.source"] = "manual"
        # Carry the judge cost on the span so a plan reload shows it (the turn-score
        # GET reads these back for the Quality card note) — identical to the online hook.
        # `eval.judged` states what the RECORD holds, not what was attempted: the runs
        # ledger labels a row from this flag, so a span carrying real judge chips must
        # never read "deterministic scoring" (and one carrying none must never claim a
        # judgement just because a panel was assembled).
        from trusted_data_agent.eval.online import judged_from_record
        span["attributes"]["eval.judged"] = judged_from_record(verdicts)
        span["attributes"]["eval.cost_usd"] = judge_cost
        span["attributes"]["eval.input_tokens"] = judge_in
        span["attributes"]["eval.output_tokens"] = judge_out
        _get_exporter().export(span)
        persisted = True
    except Exception as e:
        app_logger.warning(f"score-turn: could not persist quality span: {e}")

    # DESIGN IMPERATIVE — consistent cost allocation at any time. A manual re-score
    # spends REAL judge tokens on the user's credentials, so it must be allocated
    # exactly like the online hook and the grounding judge: session + turn totals
    # (authoritative for plan reload), the consumption/billing ledger, and a live
    # KPI token_update (delivered over the per-user notification channel, since this
    # REST call has no request event_handler). Deterministic-only scoring spent 0
    # tokens → no-op. The Quality card itself survives reload via the persisted span.
    if judge_in or judge_out:
        try:
            from trusted_data_agent.eval.online import _record_score_usage
            _turn_id = turn.get("turn", turn.get("turn_number"))
            from trusted_data_agent.eval.online import judge_verdict_summary
            await _record_score_usage(
                user_uuid, sid, _turn_id, judge_in, judge_out, judge_cost, event_handler=None,
                judge_models=judge_models, judge_usage=judge_usage,
                judge_verdicts=judge_verdict_summary(verdicts),
                profile_class=case.profile_class, layer="post_hoc")
        except Exception as e:
            app_logger.debug(f"score-turn: judge cost allocation skipped: {e}")

    resp = {"verdicts": [v.to_dict() for v in verdicts], "persisted": persisted}

    if want_judges:
        resp["judges_available"] = bool(judges_available)
        resp["judge_models"] = judge_models
        resp["input_tokens"] = judge_in
        resp["output_tokens"] = judge_out
        resp["cost_usd"] = round(judge_cost, 6)
    return jsonify(resp), 200


@rest_api_bp.route("/v1/evals/scoring-thresholds", methods=["GET"])
@operation("evals.scoring_thresholds", effect="read", scope="instance",
           summary="Where green, amber and red begin for every quality measure on this deployment")
@require_auth
async def evals_scoring_thresholds(current_user):
    """The LIVE scoring bands, as any reader of the Quality Dimensions Guide needs them.

    The Guide used to state the *shipped default* ("unset by default") — a constant
    wearing a live reading's clothes. On a deployment whose admin has tuned the sliders
    that statement is simply false, and it is false in the direction that matters: it
    tells an operator nothing is banded while every metric is.

    **Not admin-gated, deliberately.** These bands are already visible to any user on
    every Quality card (each banded verdict carries its own `threshold`), so surfacing
    the same numbers in the Guide exposes nothing new — and the Guide must render for
    whoever opens it. Read-only; the *setter* stays behind the admin app-config route.

    Returns the config shape verbatim (`{key: {healthy?, danger?}}`) plus the scorers'
    own `CODE_FALLBACK_CUTS`, so the Guide can distinguish "not set, therefore not
    banded" from "not set, but code bands it anyway" without restating either.
    """
    from trusted_data_agent.core.config import APP_CONFIG
    live = getattr(APP_CONFIG, "ONLINE_EVAL_DEFAULT_THRESHOLDS", None)
    if not isinstance(live, dict):
        live = {}
    # Normalize the legacy scalar form (a bare number = a Danger line only) so the
    # client reads ONE shape and cannot mis-render an old stored value as a healthy cut.
    out = {}
    for key, val in live.items():
        if isinstance(val, dict):
            band = {k: v for k, v in val.items() if k in ("healthy", "danger") and v is not None}
            if band:
                out[key] = band
        elif val is not None:
            out[key] = {"danger": val}
    try:
        from trusted_data_agent.eval.scorers.deterministic import CODE_FALLBACK_CUTS
        fallbacks = {k: dict(v) for k, v in CODE_FALLBACK_CUTS.items()}
    except Exception as e:
        # Fail toward SILENCE, never toward a guess: an invented fallback would have the
        # Guide promise a band the scorers do not apply.
        app_logger.warning(f"scoring-thresholds: code fallbacks unavailable ({e})")
        fallbacks = {}
    return jsonify({"thresholds": out, "code_fallbacks": fallbacks}), 200


@rest_api_bp.route("/v1/assurance/vocabulary", methods=["GET"])
@operation("assurance.vocabulary", effect="read", scope="instance",
           summary="Every assurance mechanism in words — what each gate, measure and station checks, its modes and its limits")
@require_auth
async def assurance_vocabulary(current_user):
    """Every assurance mechanism, as Guide-shaped entries.

    Served rather than derived on the client so the Assurance Guide is COMPLETE from any
    entry point. Registering only what a rendered dial happened to list meant the Guide
    opened from the Quality card with no mechanisms and no back-links — a reader would
    have seen a different glossary depending on where they came from, which is the same
    fact rendering two ways.

    Static vocabulary: no user data, no turn data, safe to cache on the client.
    """
    try:
        from trusted_data_agent.agent import assurance_points as _ap
        out = []
        for p in _ap.REGISTRY:
            g = _ap.guide_entry(p.key)
            if not g:
                continue
            g = dict(g)
            g["label"] = p.label
            # Which station it feeds, and which agent classes it applies to. Without
            # this the live dial cannot tell "has not reported YET" from "will never
            # report on this class" — and would show `pending` for a gate that is not
            # coming, which is a promise rather than a reading.
            g["station"] = p.station
            g["applies_to"] = sorted(p.applies_to) if p.applies_to else []
            # A deliberate exclusion is still a member of its station (it is listed there,
            # so it has a parent), but it never reads on a turn — the Guide marks it so a
            # station that lists one more member than the dial does says why.
            if p.excluded:
                g["excluded"] = True
            out.append(g)
        # The eight STATIONS are Guide entries too — a card names the guarantee it
        # serves, and that guarantee must be lookupable like everything else.
        for _st in _ap.STATIONS:
            _se = _ap.station_entry(_st)
            if _se:
                out.append(_se)
        # The MEASUREMENT process model (eval/stages.py) — which stage of a turn each
        # scored dimension measures, and the order the stages run in. Served rather than
        # mirrored: this subsystem already carries five hand-kept JS copies of Python
        # facts, each pinned by CI *because it drifted*, and a sixth would be a sixth
        # place to disagree about where a check belongs. Absent-tolerant — an older
        # client ignores the key, and a client that gets no key groups nothing rather
        # than inventing a grouping.
        _stages = {}
        try:
            from trusted_data_agent.eval import stages as _stg
            _stages = _stg.vocabulary_payload()
            # The MOMENTS are Guide entries too — the sixth entry class. The Guide is the
            # mental model of the runtime, and it could explain a guarantee and a
            # mechanism but not a moment of the turn, while a moment is how 52 of its
            # entries are grouped. A shelf header with nothing to open is a dead end.
            out.extend(_stg.stage_entries())
        except Exception as _se2:  # noqa: BLE001 — the Guide degrades, it never errors
            app_logger.debug(f"[assurance] stage model unavailable: {_se2}")
        # The PROPERTIES — the seventh entry class. The Trust Circle's mechanism rows
        # expand to the modules assessing each property and route here; without these the
        # rows were dead ends, which the Guide's completeness rule bans. A property is the
        # thing being assessed that a guarantee, a mechanism and a measurement are all
        # ABOUT, and it is the unit a remapping UX operates on.
        try:
            from trusted_data_agent.agent import assurance as _asr
            _asr.bootstrap()
            _props = list(_asr.registry.guide_entries())
            # The scored dimension that grades each property, DERIVED from the scorers'
            # own `property` declaration rather than a second hand-kept map. Without it a
            # property entry read "No scored dimension measures this one" while the lanes
            # row directly beneath named the module that grades it after the turn — one
            # entry contradicting itself, and a module row with nowhere onward to go.
            #
            # Built here because the substrate must not import the eval package (eval
            # imports it); this is the one layer that already holds both.
            try:
                import trusted_data_agent.eval.scorers as _sc  # noqa: F401 — registers
                from trusted_data_agent.eval.scorer import scorers_for as _sf
                _by_prop: dict[str, list[str]] = {}
                for _cls in ("rag_focused", "tool_enabled", "llm_only", "genie",
                             "conversation_with_tools", "flow"):
                    for _s in _sf(_cls):
                        _p = getattr(_s, "property", None)
                        if _p and _s.dimension not in _by_prop.setdefault(_p, []):
                            _by_prop[_p].append(_s.dimension)
                for _e in _props:
                    _e["dims"] = tuple(sorted(_by_prop.get(_e.get("property"), ())))
            except Exception as _de:  # noqa: BLE001
                app_logger.debug(f"[assurance] property→dimension link unavailable: {_de}")
            out.extend(_props)
        except Exception as _pe:  # noqa: BLE001 — the Guide degrades, it never errors
            app_logger.debug(f"[assurance] property entries unavailable: {_pe}")
        # ── which entries read the SAME assessment ────────────────────────────
        # `graded by` says a measurement grades this mechanism. It does NOT say whether
        # the two are the same computation — and that is the difference the whole
        # symmetry programme is about. Of the nine dimensions grading the grounding gate,
        # exactly three read the module the gate itself acted on (so they cannot disagree
        # with it); the other six are independent readings. Nothing on the entry said
        # which, so a reader could not tell corroboration from coincidence.
        #
        # Served as ONE module→entries map rather than a per-entry sibling list: two
        # copies of one relation drift, and the client needs both directions anyway.
        try:
            _mods: dict[str, set[str]] = {}
            _prop_mod: dict[str, set[str]] = {}
            for _e in _props:
                for _l in _e.get("lanes", ()):
                    _a = _l.get("assessor")
                    if not _a:
                        continue
                    _mods.setdefault(_a, set()).add(_e["k"])
                    _prop_mod.setdefault(_e["property"], set()).add(_a)
            # a mechanism reads the modules of every property it is bound to
            from trusted_data_agent.agent import assurance_points as _ap
            for _mk, _mp in (getattr(_ap, "POINT_PROPERTIES", {}) or {}).items():
                for _p in (_mp if isinstance(_mp, (list, tuple, set)) else (_mp,)):
                    for _a in _prop_mod.get(_p, ()):
                        _mods.setdefault(_a, set()).add(_mk)
            # a scored dimension reads the module its declared property binds
            for _e in _props:
                for _d in _e.get("dims", ()):
                    for _a in _prop_mod.get(_e["property"], ()):
                        _mods.setdefault(_a, set()).add(_d)
            _shared = {_a: sorted(_ks) for _a, _ks in _mods.items() if len(_ks) > 1}
        except Exception as _se:  # noqa: BLE001 — the Guide degrades, it never errors
            app_logger.debug(f"[assurance] shared-module map unavailable: {_se}")
            _shared = {}
        # The TERMS glossary — every technical word a row may use, defined once. Served
        # here because the rule the rows live under ("a term is used on screen only if the
        # screen explains it") needs the definitions to travel with the vocabulary.
        try:
            _terms = _ap.guide_terms()
        except Exception:  # noqa: BLE001 — an older registry serves no terms
            _terms = []
        return jsonify({"entries": out, "count": len(out), "stages": _stages,
                        "shared_modules": _shared, "terms": _terms}), 200
    except Exception as e:  # noqa: BLE001 — the Guide degrades, it never errors
        app_logger.warning(f"[assurance] vocabulary unavailable: {e}")
        return jsonify({"entries": [], "count": 0}), 200


# ══════════════════════════════════════════════════════════════════════════════
#  The BINDING TABLE — which module assesses which property, in which lane.
#
#  The substrate has always held these as data (`registry.bindings()` is documented as
#  "what the remapping UX renders"); until now nothing served them, so the one artefact
#  an operator most needs to see — what is actually assessing their agents — was visible
#  only by reading source. These endpoints are that surface.
#
#  READS are open to any authenticated user: the vocabulary endpoint already discloses
#  every binding fact, and a reader who can see the Guide can already see which module
#  grades a property. WRITES are admin-only and fail CLOSED — a binding change alters
#  what every gate sees.
# ══════════════════════════════════════════════════════════════════════════════

def _assurance_module_trust(assessor_key: str) -> dict:
    """Trust state for a module, as the studio renders it.

    Builtins are trusted by shipping (the `builtin` state), exactly as component types
    are. Third-party keys are namespaced `<pack>.<key>`, and the dot is the ONE test —
    the same discriminator `conformance` uses for the bind gate, so the badge and the
    refusal can never disagree about what counts as third-party.

    Fails OPEN to `unknown`: this is a display read, and a trust suite that cannot be
    reached must not take the panel down. The BIND path fails closed independently.
    """
    if "." not in assessor_key:
        return {"state": "builtin"}
    return _assurance_pack_trust(assessor_key.split(".", 1)[0])


def _assurance_pack_trust(pack_id: str) -> dict:
    """Trust state for a PACK. Fails open to `unknown` — a display read."""
    try:
        from trusted_data_agent.core.trust import store as _tstore
        from trusted_data_agent.core.trust import content as _tcontent
        from trusted_data_agent.core.trust.attestation import resolve_state
        state = resolve_state(_tstore.attested_hash("assurance_module", pack_id),
                              _tcontent.live_hash("assurance_module", pack_id))
        return {"state": getattr(state, "value", str(state)), "pack_id": pack_id}
    except Exception:  # noqa: BLE001
        return {"state": "unknown", "pack_id": pack_id}


def _assurance_routes() -> dict:
    """pack property -> the mechanism whose gate consults it in flight. `{}` if unreadable."""
    try:
        from trusted_data_agent.agent.assurance import inflight as _if
        return dict(_if._ENFORCED_BY)
    except Exception:  # noqa: BLE001
        return {}


def _assurance_module_rows() -> list:
    """Every registered assessor, with the two facts the studio needs beyond `describe()`."""
    from trusted_data_agent.agent.assurance import registry as _reg
    out = []
    for a in _reg.assessors():
        out.append({**a.describe(),
                    "builtin": "." not in a.key,
                    "trust": _assurance_module_trust(a.key)})
    return out


def _assurance_mechanism_rows():
    """Every platform mechanism, per station — what ACTS, natively.

    Posture is deliberately NOT offered here: a gate's mode is per-agent (the profile
    editor's Trust section), not a deployment-wide switch, and rendering a select that
    silently meant something else would be worse than none. The row says where it is set.
    """
    try:
        from trusted_data_agent.agent.assurance_points import points, POINT_CLASS
        from trusted_data_agent.agent.assurance import controls as _c
        out = []
        for p in points():
            cls = POINT_CLASS.get(p.key) or "control"
            out.append({
                "key": p.key, "label": p.label, "station": p.station, "cls": cls,
                "origin": "platform", "third_party": False,
                "act_words": {"control": "acts during the turn",
                              "boundary": "constrains what may run",
                              "attestation": "records what was attested",
                              "measure": "records — never acts"}.get(cls, cls),
                "chokepoint": _c.chokepoint_of(p.key),
                "posture_note": ("posture is set per agent, in the profile editor"
                                 if cls == "control" else "always in force"),
            })
        return out
    except Exception:  # noqa: BLE001
        return []


def _assurance_control_rows():
    """Every registered control, with the posture an operator actually set.

    `posture` is the EFFECTIVE reading (dormant default included) and `configured` says
    whether anyone chose it — the same absent-vs-chosen distinction the binding table
    keeps, and for the same reason: "nobody has decided" and "somebody decided observe"
    are different facts about a deployment.
    """
    from trusted_data_agent.agent.assurance import controls as _ctl
    from trusted_data_agent.agent.assurance import store as _store
    try:
        configured = _store.control_postures()
    except Exception:  # noqa: BLE001
        configured = {}
    out = []
    for c in _ctl.controls():
        d = c.describe()
        d["posture"] = configured.get(c.key) or _ctl.DEFAULT_POSTURE
        d["configured"] = c.key in configured
        d["acts_now"] = _ctl.effective_act(c, d["posture"])
        out.append(d)
    return out


@rest_api_bp.route("/v1/assurance/controls/<path:key>/posture", methods=["POST"])
@require_admin
async def assurance_control_posture(key):
    """Set a control's posture — the one act that lets third-party machinery act at all.

    FAILS CLOSED on an unknown posture: the ladder is the platform's, and a value it does
    not recognise must not be persisted for `effective_act` to later resolve as `observe`.
    Refusing here means the stored state always means exactly what it says.
    """
    from trusted_data_agent.auth.admin import get_current_user_from_request
    from trusted_data_agent.agent.assurance import controls as _ctl
    from trusted_data_agent.agent.assurance import store as _store
    current_user = get_current_user_from_request()
    try:
        data = await request.get_json() or {}
    except Exception:  # noqa: BLE001
        data = {}
    posture = str(data.get("posture") or "").strip().lower()
    control = _ctl.get(key)
    if control is None:
        return jsonify({"error": "unknown_control", "message":
                        f"no control {key!r} is registered here"}), 404
    if posture not in _ctl._LADDER:
        return jsonify({"error": "unknown_posture", "message":
                        f"{posture!r} is not a posture — the ladder is "
                        f"{', '.join(_ctl._LADDER)}"}), 400
    try:
        _store.set_control_posture(
            key, posture, getattr(current_user, "username", None) or "admin",
            note=str(data.get("note") or ""))
    except Exception as e:  # noqa: BLE001
        return jsonify({"error": "not_saved", "message": str(e)}), 500
    return jsonify({
        "control": key, "posture": posture,
        "acts_now": _ctl.effective_act(control, posture),
        # What this posture MEANS for this control, in the operator's own words — so the
        # confirmation says what changed rather than echoing the value they just picked.
        "effect": (f"{control.label} {_ctl.ACT_WORDS.get(control.act, control.act)}"
                   if _ctl.effective_act(control, posture)
                   else f"{control.label} records what it would do, and changes nothing"),
    }), 200


@rest_api_bp.route("/v1/assurance/controls/<path:key>/posture", methods=["DELETE"])
@require_admin
async def assurance_control_posture_clear(key):
    """Forget the decision — the control returns to DORMANT.

    Not the same as setting `observe`, and the studio offers both: "restore" means nobody
    has decided (and the deployment envelope stops carrying a row), while `observe` is a
    decision that happens to be the default. Collapsing them would lose which of the two a
    reader is looking at.
    """
    from trusted_data_agent.agent.assurance import controls as _ctl
    from trusted_data_agent.agent.assurance import store as _store
    if _ctl.get(key) is None:
        return jsonify({"error": "unknown_control"}), 404
    try:
        _store.clear_control_posture(key)
    except Exception as e:  # noqa: BLE001
        return jsonify({"error": "not_saved", "message": str(e)}), 500
    return jsonify({"control": key, "posture": _ctl.DEFAULT_POSTURE,
                    "configured": False, "acts_now": None}), 200


@rest_api_bp.route("/v1/assurance/bindings", methods=["GET"])
@require_auth
async def assurance_bindings(current_user):
    """The whole binding table, plus everything needed to render and explain it."""
    try:
        from trusted_data_agent.agent import assurance as _A
        from trusted_data_agent.agent.assurance import (
            registry as _reg, conformance as _conf, store as _store,
            properties as _props)
        from trusted_data_agent.agent.assurance import controls as _ctl_mod
        _A.bootstrap()

        rows = _reg.bindings()
        # Which guarantee each property belongs to — DERIVED from the one declaration of
        # mechanism ownership, never a second list. It is what lets the studio be the ring
        # rather than a flat table: a segment shows the properties its own mechanisms
        # assess. A pack property inherits the station of the gate its control attaches to,
        # and falls back to the residue rather than vanishing from every segment.
        try:
            from trusted_data_agent.agent.assurance_points import POINT_PROPERTIES, points
            _byk = {x.key: x for x in points()}
            _p2s = {pr: _byk[m].station for m, props in POINT_PROPERTIES.items()
                    if m in _byk for pr in props}
        except Exception:  # noqa: BLE001
            _p2s = {}
        _ctl_station = {c.fires_on: c.station for c in _ctl_mod.controls()}
        for r in rows:
            r["station"] = (_p2s.get(r.get("property"))
                            or _ctl_station.get(r.get("property")) or "scored")
        # `audit()` is the drift check: a bound module that is no longer valid — renamed,
        # uninstalled, or (for third-party) no longer signed. Served rather than acted on,
        # because auto-unbinding would remove a running protection without a decision.
        try:
            drift = _conf.audit()
        except Exception:  # noqa: BLE001
            drift = []
        return jsonify({
            "rows": rows,
            "symmetry": {k: _reg.symmetry(k) for k in _props.keys()},
            "inflight_consumers": _A.INFLIGHT_CONSUMERS,
            # Which of those the gate consults through the SEAM (it has its own assessment
            # and a plugin adds to it) rather than resolving as its own. Two different
            # readings, and the cell says the right one.
            "seam_consulted": sorted(getattr(_A, "SEAM_CONSULTED", ()) or ()),
            # Pack properties routed to a gate by their manifest — the in-flight half of
            # the plane, and the reason a cell can now say a plugin affects an answer.
            "routed": _assurance_routes(),
            "overrides": _store.load_overrides(),
            "modules": _assurance_module_rows(),
            "drift": drift,
            # The machinery that ACTS. Served beside the bindings because the two answer
            # halves of one question — what a guarantee SEES, and whether it acts on it —
            # and an operator reading only the first would take a dormant control for a
            # working one.
            "controls": _assurance_control_rows(),
            # The PLATFORM's own machinery, served in the same shape. Without this the
            # "what acts on it" reading was the third-party registry alone, so with no pack
            # installed every guarantee read "nothing acts here" — including GUARDED, which
            # two gates uphold. Same dogfooding gap the modules had: one concept, two
            # registries, and only one of them reaching the surface.
            "mechanisms": _assurance_mechanism_rows(),
            "control_acts": list(_ctl_mod.ACTS),
            "control_postures": ["off", "observe", "annotate", "enforce", "review"],
        }), 200
    except Exception as e:  # noqa: BLE001 — a display read never 500s the panel
        app_logger.warning(f"[assurance] bindings unavailable: {e}")
        return jsonify({"rows": [], "symmetry": {}, "inflight_consumers": {},
                        "overrides": [], "modules": [], "drift": [],
                        "error": str(e)}), 200


@rest_api_bp.route("/v1/assurance/bindings/candidates", methods=["GET"])
@require_auth
async def assurance_binding_candidates(current_user):
    """Which modules COULD serve this property in this lane — and why the others cannot.

    The rejected candidates carry `blocked_by` verbatim from `conformance`. A picker that
    lists only valid options teaches nothing; one that names the reason is how an operator
    learns the model.
    """
    prop = (request.args.get("property") or "").strip()
    lane_name = (request.args.get("lane") or "").strip().upper()
    try:
        from trusted_data_agent.agent import assurance as _A
        from trusted_data_agent.agent.assurance import conformance as _conf
        from trusted_data_agent.agent.assurance import properties as _props
        from trusted_data_agent.agent.assurance.capabilities import Lane
        _A.bootstrap()

        if not _props.get(prop):
            return jsonify({"error": f"unknown property {prop!r}"}), 400
        try:
            lane = Lane[lane_name]
        except KeyError:
            return jsonify({"error": f"unknown lane {lane_name!r}"}), 400

        out = []
        for c in _conf.candidates(prop, lane):
            key = str(c.get("key") or "")
            out.append({**c, "builtin": "." not in key,
                        "trust": _assurance_module_trust(key)})
        return jsonify({"candidates": out, "property": prop, "lane": lane.name}), 200
    except Exception as e:  # noqa: BLE001
        app_logger.warning(f"[assurance] candidates unavailable: {e}")
        return jsonify({"candidates": [], "error": str(e)}), 200


def _record_binding_change(user, prop: str, lane: str, before, after, note: str = "") -> None:
    """Audit + live notice for a binding change (PROP-003 §8 R9).

    Keys and labels only — never module source. A binding change is a RECEIPT: it records
    a decision that has already been taken, so it is severity `warning` (worth a look),
    never `danger` (needs you now).
    """
    try:
        from trusted_data_agent.core import trust_events as _te
        payload = {"property": prop, "lane": lane, "from": before, "to": after,
                   "by": getattr(user, "id", None), "note": note or ""}
        summary = (f"Assessment of {prop} in {lane} changed: "
                   f"{before or 'nothing'} → {after or 'nothing (not assessed)'}")
        _te.record_event(
            user_uuid=getattr(user, "id", None),
            event_type="assurance_binding_changed",
            summary=summary,
            severity="warning",
            payload=payload,
        )
        _te.broadcast_notice(
            user_uuid=getattr(user, "id", None),
            event_type="assurance_binding_changed",
            summary=summary,
            severity="warning",
        )
    except Exception as e:  # noqa: BLE001 — an audit failure must not undo a valid write
        app_logger.warning(f"[assurance] binding audit could not be recorded: {e}")


@rest_api_bp.route("/v1/assurance/bindings", methods=["POST"])
@require_admin
async def assurance_bind():
    """Bind a module to a property in a lane. FAILS CLOSED.

    Order matters: conformance decides (via `registry.bind`, which re-runs every rule
    including the third-party trust gate) BEFORE anything is persisted, so a refused
    binding never leaves a row behind that a later `reload_overrides` would apply.
    """
    # `@require_admin` gates but does not inject — the house pattern for an admin route is
    # to read the user itself (mirrors `admin_routes._get_user_uuid_from_request`).
    from trusted_data_agent.auth.admin import get_current_user_from_request
    current_user = get_current_user_from_request()

    try:
        data = await request.get_json() or {}
    except Exception:  # noqa: BLE001
        data = {}
    prop = str(data.get("property") or "").strip()
    lane_name = str(data.get("lane") or "").strip().upper()
    assessor = str(data.get("assessor") or "").strip()
    note = str(data.get("note") or "")

    from trusted_data_agent.agent import assurance as _A
    from trusted_data_agent.agent.assurance import registry as _reg, store as _store
    from trusted_data_agent.agent.assurance.capabilities import Lane
    _A.bootstrap()

    try:
        lane = Lane[lane_name]
    except KeyError:
        return jsonify({"bound": False, "reasons": [f"unknown lane {lane_name!r}"]}), 400
    if not assessor:
        return jsonify({"bound": False, "reasons": ["no module named"]}), 400

    before = None
    for row in _reg.bindings():
        if row.get("property") == prop and row.get("lane") == lane.name:
            before = row.get("assessor")
            break

    problems = _reg.bind(prop, assessor, (lane,))
    if problems:
        return jsonify({"bound": False, "reasons": problems}), 409

    try:
        _store.save_override(prop, lane.name, assessor,
                             bound_by=getattr(current_user, "id", None), note=note)
    except Exception as e:  # noqa: BLE001 — write failed: revert the live table
        app_logger.error(f"[assurance] binding persist failed: {e}")
        _A.reload_overrides()
        return jsonify({"bound": False,
                        "reasons": [f"the binding could not be saved: {e}"]}), 500

    _A.reload_overrides()
    _sync_plugin_scorers_quietly()
    _record_binding_change(current_user, prop, lane.name, before, assessor, note)
    row = next((r for r in _reg.bindings()
                if r.get("property") == prop and r.get("lane") == lane.name), None)
    return jsonify({"bound": True, "row": row,
                    "symmetry": _reg.symmetry(prop)}), 200


def _sync_plugin_scorers_quietly() -> None:
    """Give a newly-bound third-party property its scorer, without a restart.

    Best-effort by design: the binding is already persisted and valid at this point, and
    failing the request because the Scorecard will lag by one restart would undo a change
    the operator correctly made.
    """
    try:
        from trusted_data_agent.assurance_modules import get_assurance_module_manager
        from trusted_data_agent.eval.scorers.plugin_properties import sync_plugin_scorers
        sync_plugin_scorers(get_assurance_module_manager().tunables())
    except Exception as e:  # noqa: BLE001
        app_logger.warning(f"[assurance] plugin scorers not refreshed: {e}")


@rest_api_bp.route("/v1/assurance/bindings/<path:prop>/<lane_name>", methods=["DELETE"])
@require_admin
async def assurance_unbind(prop, lane_name):
    """Two DISTINCT acts, chosen by `restore_default`:

      restore_default=true   drop the override → the SHIPPED default applies again
      restore_default=false  persist an explicit unbind → this lane reads NOT ASSESSED

    Collapsing them would make "I want the platform's choice back" and "I want silence
    here" the same button, and one of those two intentions would become unreachable.
    """
    from trusted_data_agent.auth.admin import get_current_user_from_request
    current_user = get_current_user_from_request()

    restore = (request.args.get("restore_default") or "false").lower() == "true"
    lane_name = str(lane_name or "").strip().upper()

    from trusted_data_agent.agent import assurance as _A
    from trusted_data_agent.agent.assurance import registry as _reg, store as _store
    from trusted_data_agent.agent.assurance.capabilities import Lane
    _A.bootstrap()

    try:
        lane = Lane[lane_name]
    except KeyError:
        return jsonify({"ok": False, "reasons": [f"unknown lane {lane_name!r}"]}), 400

    before = next((r.get("assessor") for r in _reg.bindings()
                   if r.get("property") == prop and r.get("lane") == lane.name), None)
    try:
        if restore:
            _store.delete_override(prop, lane.name)
        else:
            _store.save_override(prop, lane.name, None,
                                 bound_by=getattr(current_user, "id", None),
                                 note="explicit unbind")
    except Exception as e:  # noqa: BLE001
        return jsonify({"ok": False, "reasons": [f"could not be saved: {e}"]}), 500

    _A.reload_overrides()
    after = next((r.get("assessor") for r in _reg.bindings()
                  if r.get("property") == prop and r.get("lane") == lane.name), None)
    _record_binding_change(current_user, prop, lane.name, before, after,
                           "restored the shipped default" if restore else "explicit unbind")
    row = next((r for r in _reg.bindings()
                if r.get("property") == prop and r.get("lane") == lane.name), None)
    return jsonify({"ok": True, "restored_default": restore, "row": row,
                    "symmetry": _reg.symmetry(prop)}), 200


@rest_api_bp.route("/v1/assurance/modules", methods=["GET"])
@require_auth
async def assurance_modules_list(current_user):
    """Installed assurance-module packs, their contributions, and their trust state.

    Reads never fail hard: an unreadable plane must not take the Trust panel down with it.
    """
    try:
        from trusted_data_agent.assurance_modules import (
            get_assurance_module_manager, settings as _ms)
        mgr = get_assurance_module_manager()
        if not mgr.packs:
            mgr.discover()
        packs = [{**p, "trust": _assurance_pack_trust(p["pack_id"])}
                 for p in mgr.list_packs()]
        return jsonify({
            "packs": packs,
            "skipped": mgr.skipped,
            "settings": _ms.get_settings(),
        }), 200
    except Exception as e:  # noqa: BLE001
        app_logger.warning(f"[assurance] modules unavailable: {e}")
        return jsonify({"packs": [], "skipped": [], "settings": {}, "error": str(e)}), 200


@rest_api_bp.route("/v1/assurance/modules/settings", methods=["POST"])
@require_admin
async def assurance_modules_settings():
    """The plane's governance switches. Admin only; the master ships OFF."""
    from trusted_data_agent.auth.admin import get_current_user_from_request
    user = get_current_user_from_request()
    try:
        data = await request.get_json() or {}
    except Exception:  # noqa: BLE001
        data = {}
    try:
        from trusted_data_agent.assurance_modules import (
            settings as _ms, get_assurance_module_manager)
        _ms.save_settings(data, getattr(user, "id", None))
        # Re-discover so turning the master on or disabling a pack takes effect without a
        # restart — a governance switch that needs a restart is one an operator distrusts.
        mgr = get_assurance_module_manager()
        mgr.unload_all()
        mgr.discover()
        return jsonify({"saved": True, "settings": _ms.get_settings(),
                        "packs": mgr.list_packs()}), 200
    except Exception as e:  # noqa: BLE001
        app_logger.error(f"[assurance] module settings save failed: {e}")
        return jsonify({"saved": False, "error": str(e)}), 500


@rest_api_bp.route("/v1/evals/turn-score", methods=["GET"])
@operation("evals.turn_score", effect="read", scope="own",
           summary="The quality verdicts recorded for one turn of one of the caller's conversations — read, nothing is scored again",
           query={"session_id": Arg("string", "the conversation", required=True), "turn": Arg("integer", "the turn number (default: the last)")})
@require_auth
async def evals_turn_score(current_user):
    """Latest **persisted** quality verdicts for a session turn — read-only, no
    re-score, no tokens. Powers the trajectory overlay's auto-display so a turn
    that was already scored (automatically by online eval, or manually) shows its
    scores on open instead of an empty 'Score this turn' button.
    """
    sid = request.args.get("session_id")
    turn = request.args.get("turn")
    if not sid:
        return jsonify({"error": "session_id required"}), 400
    user_uuid = _get_user_uuid_from_request()
    spans = _read_online_spans(2000, user_uuid=user_uuid)
    match = None
    for sp in spans:  # chronological — last match wins (latest score)
        a = sp.get("attributes") or {}
        if a.get("agent.kind") == "flow":
            continue
        if a.get("session.id") == sid and (turn is None or str(a.get("turn.id")) == str(turn)):
            match = sp
    if not match:
        return jsonify({"scored": False}), 200
    a = match.get("attributes") or {}
    verdicts = [e.get("attributes") for e in (match.get("events") or [])
                if isinstance(e, dict) and e.get("name") == "verdict" and e.get("attributes")]
    # Spans persisted before `Verdict.gating` was serialized carry no flag, and a
    # consumer with no flag has to guess whether a failure convicts the turn or merely
    # flags it — which is how the scorecard came to call an advisory `numeric_fidelity`
    # a "gating failure". The fact is resolvable from the dimension name alone, and the
    # registry is right here, so it is filled in on replay: one source, every payload.
    try:
        from trusted_data_agent.eval.scorer import is_gating_dimension
        import trusted_data_agent.eval.scorers  # noqa: F401 — populate the registry
        for v in verdicts:
            if isinstance(v, dict) and "gating" not in v:
                v["gating"] = is_gating_dimension(v.get("dimension"))
    except Exception:  # noqa: BLE001 — a missing flag degrades, never breaks the read
        pass
    return jsonify({
        "scored": True,
        "verdicts": verdicts,
        "source": a.get("eval.source", "online"),
        "profile_tag": a.get("agent.profile_tag"),
        "has_judges": any(v.get("kind") == "judge" for v in verdicts),
        "judged": bool(a.get("eval.judged")),
        "input_tokens": a.get("eval.input_tokens", 0),
        "output_tokens": a.get("eval.output_tokens", 0),
        "cost_usd": a.get("eval.cost_usd", 0.0),
    }), 200


@rest_api_bp.route("/v1/evals/online", methods=["GET"])
@operation("evals.online", effect="read", scope="own",
           summary="The latest quality readings of the caller's turns as they were scored live, newest first",
           query={"limit": Arg("integer", "at most this many")})
@require_auth
async def evals_online_spans(current_user):
    """Tail the online-eval quality span sink (most recent first).

    Drives the regression dashboard: each span is an OTLP-shaped record with
    per-dimension verdict attributes + the signed attestation. Returns [] if the
    sink doesn't exist yet (online eval disabled or no sampled turns).

    TC-7: spans carry ``user.uuid``, ``session.id``, ``turn.id`` and judge evidence strings
    (which can quote answer fragments), so this is scoped to the caller by default — only
    ``scope=system`` (behind VIEW_ALL_SESSIONS) reads across users, mirroring every sibling
    evals endpoint. Previously this one read the shared sink raw with no filter at all.
    """
    from trusted_data_agent.core.config import APP_CONFIG
    from trusted_data_agent.auth.features import user_has_feature, Feature
    scope = (request.args.get("scope") or "my").lower()
    if scope == "system" and not user_has_feature(current_user, Feature.VIEW_ALL_SESSIONS):
        return jsonify({"error": "system scope requires VIEW_ALL_SESSIONS"}), 403
    limit = max(1, min(int(request.args.get("limit", 100)), 1000))
    read_uuid = None if scope == "system" else current_user.id
    try:
        spans = list(reversed(_read_online_spans(limit, user_uuid=read_uuid)))
    except Exception as e:
        app_logger.warning(f"online-eval span read failed: {e}")
        spans = []
    return jsonify({"spans": spans, "scope": scope,
                    "enabled": bool(getattr(APP_CONFIG, "ONLINE_EVAL_ENABLED", False))}), 200


def _caller_votes(scope: str = "my") -> dict:
    """The CALLER's own per-turn votes, for the roster/ledger preference reading.

    Scoped to the caller by construction (R8) — a vote is that user's preference,
    never readable as another user's. Deliberately returns ``{}`` in system scope:
    an admin reading someone else's agent must see NO vote reading rather than a
    zero that would read as "nobody rated this". Never raises; a failure degrades
    to no votes, and every consumer then omits the reading entirely.
    """
    if (scope or "my").lower() == "system":
        return {}
    try:
        from trusted_data_agent.agent.feedback.consumers.annotation import latest_votes
        return latest_votes(_get_user_uuid_from_request())
    except Exception as e:  # noqa: BLE001
        app_logger.debug(f"vote map unavailable: {e}")
        return {}


def _read_online_spans(limit: int = 500, user_uuid: str = None) -> list:
    """Read recent online-eval spans, newest last. When ``user_uuid`` is given,
    keep only that user's spans (the My-Performance scope).

    Delegates to ``eval.sink.read_spans`` — the ONE reader, so the scoping and
    tail semantics this endpoint family relies on cannot drift from the ones the
    vote-annotation consumer uses to find the same span.
    """
    from trusted_data_agent.eval.sink import read_spans
    return read_spans(limit, user_uuid=user_uuid)


