def _usernames_for(uuids):
    """uuid → display-name map for admin-scoped (VIEW_ALL_SESSIONS) surfaces.
    Best-effort: an unresolvable uuid simply stays absent (the UI shows the
    short uuid instead) — never fails the calling endpoint."""
    out = {}
    try:
        from trusted_data_agent.auth.database import get_db_session
        from trusted_data_agent.auth.models import User
        ids = [u for u in set(uuids) if u]
        if not ids:
            return out
        with get_db_session() as s:
            for u in s.query(User).filter(User.id.in_(ids)).all():
                out[u.id] = getattr(u, "display_name", None) or u.username
    except Exception:
        pass
    return out


def _eval_scope_user_filter(scope):
    """System-scope evals views accept ``user=<uuid>`` to focus on ONE user's
    agents. Only meaningful after the VIEW_ALL_SESSIONS gate has passed (the
    caller enforces it); my-scope always resolves to the requester."""
    if scope == "system":
        return (request.args.get("user") or "").strip() or None
    return _get_user_uuid_from_request()


def _quality_bands() -> dict:
    """Where green ends and amber begins, for every surface that colours a rate.

    ONE source. These floors were hardcoded in THREE frontend places (the roster's
    HEALTHY/REVIEW, the ring's `_execBand`, the KPI charts' `healthColor`) while an
    admin-editable copy already existed in `TRUST_BEHAVIOR` — four definitions of the
    same two numbers, which is how a "72% is amber" reading drifts from a "72% is green"
    one on the panel beside it. Reuses the existing setting rather than adding a fourth.

    Semantics deliberately stay OUT: the mode ladder (enforce acts, observe does not) and
    the worst-of aggregation are claims about what the system does, not judgements about
    where a bar sits. Exposing those would let a settings page declare an observe-only
    gate "green", or turn worst-of into best-of — the false-green this grammar exists to
    prevent.
    """
    tb = getattr(APP_CONFIG, "TRUST_BEHAVIOR", None) or {}
    def _f(key, dflt):
        try:
            v = float(tb.get(key, dflt))
            return v if 0.0 < v <= 1.0 else dflt
        except (TypeError, ValueError):
            return dflt
    healthy = _f("healthy_floor", 0.80)
    warn = _f("at_risk_floor", 0.50)
    # A warn floor at or above the healthy floor would collapse the amber band to nothing
    # and make every sub-green rate read red. Fall back rather than render that.
    if warn >= healthy:
        healthy, warn = 0.80, 0.50
    return {"healthy": healthy, "warn": warn}


def _deployment_masters() -> dict:
    """The global switches that decide whether a protection RUNS at all.

    ONE source for every surface that reports them (the evals dashboard and the
    audit pack). A per-profile mode is only a protection while its master is on —
    with a master off both runtimes short-circuit at their first line
    (`grounding/runtime.py`, `guardrails/runtime.py`) — so any reading that
    describes a mode without these facts describes a machine that is not running
    (Trust Circle finding #24)."""
    from trusted_data_agent.core.config import APP_CONFIG as _cfg
    from trusted_data_agent.core import obda_planes as _planes
    return {
        "grounding_gate_enabled": bool(getattr(_cfg, "GROUNDING_GATE_ENABLED", False)),
        "guardrails_enabled": bool(getattr(_cfg, "GUARDRAILS_ENABLED", False)),
        "online_eval_enabled": bool(getattr(_cfg, "ONLINE_EVAL_ENABLED", False)),
        # the OBDA planes are COMPONENTS: a plane's availability for this caller is its
        # component's (global gate + per-user override); the editor marks the plane's
        # cards deactivated from these keys
        "obda_enabled": bool(_planes.plane_available("read", _get_user_uuid_from_request())),
        "obda_model_enabled": bool(_planes.plane_available("model", _get_user_uuid_from_request())),
        "obda_act_enabled": bool(_planes.plane_available("act", _get_user_uuid_from_request())),
        # the OBDA policy ("contracts only", per plane) — the BOUNDED station reads it
        "obda_policy": _planes.policy_map(),
        "recommender_enabled": bool(getattr(_cfg, "RECOMMENDER_ENABLED", True)),
        "preflight_sql_mode": getattr(_cfg, "PREFLIGHT_SQL_MODE", "observe"),
    }


@rest_api_bp.route("/v1/evals/online/dashboard", methods=["GET"])
@operation("evals.online_dashboard", effect="read", scope="own",
           summary="The caller's live quality in one view: pass rate per measure, per agent and per class, and the recurring failure clusters",
           query={"limit": Arg("integer", "how many recent readings to aggregate")})
@require_auth
async def evals_online_dashboard(current_user):
    """Aggregated regression view over the online quality spans.

    ``scope=my`` (default) filters to the requesting user's own agents;
    ``scope=system`` aggregates all users' agents and requires the
    VIEW_ALL_SESSIONS feature (admin/developer tier). ``user=<uuid>`` (system
    scope only) focuses the view on one user; ``users`` in the response always
    maps every user seen in the (unfocused) span window so the picker can
    offer the full population."""
    from trusted_data_agent.eval.analysis import (
        online_pass_rate_by_dimension, cluster_online_failures,
        online_quality_by_agent, online_quality_by_flow, dedupe_spans, turn_failed)
    from trusted_data_agent.core.config import APP_CONFIG
    from trusted_data_agent.auth.features import user_has_feature, Feature

    scope = (request.args.get("scope") or "my").lower()
    is_admin = user_has_feature(current_user, Feature.VIEW_ALL_SESSIONS)
    if scope == "system" and not is_admin:
        return jsonify({"error": "system scope requires VIEW_ALL_SESSIONS"}), 403
    user_filter = _eval_scope_user_filter(scope)

    # Dedup so manual re-scores of a turn (the "Score this turn" button) don't
    # inflate an agent's turn count / pass rate (latest span per unit wins).
    # System scope reads UNfiltered first: the user picker must list the whole
    # population even while the view is focused on one user.
    read_uuid = None if scope == "system" else user_filter
    limit = int(request.args.get("limit", 500))
    spans = await asyncio.to_thread(
        lambda: dedupe_spans(_read_online_spans(limit, user_uuid=read_uuid)))
    users = set()
    if scope == "system":
        for s in spans:
            u = (s.get("attributes") or {}).get("user.uuid")
            if u:
                users.add(u)
        if user_filter:
            spans = [s for s in spans if (s.get("attributes") or {}).get("user.uuid") == user_filter]
    # `turn_failed` is THE failure predicate (resolved against the current registry); the
    # `eval.gating_failures` scalar frozen onto the span at write time kept convicting
    # under retired rules and judge-cleared checks, so the KPI disagreed with every
    # pass rate drawn from the same spans (80 "failures" beside 286 failed turns).
    failures = sum(1 for s in spans if turn_failed(s.get("attributes") or {}))
    by_class: dict = {}
    for s in spans:
        attrs = s.get("attributes") or {}
        cls = attrs.get("eval.profile_class", "unknown")
        by_class[cls] = by_class.get(cls, 0) + 1
        if scope != "system" and attrs.get("user.uuid"):
            users.add(attrs.get("user.uuid"))

    by_agent = online_quality_by_agent(spans, per_user=(scope == "system"),
                                       votes=_caller_votes(scope))
    # ── the trip lens (docs/roadmap/TRUST_TRIP_RESET.md) ──────────────────────
    # A SECOND pass of the SAME aggregator over the marker-filtered span subset —
    # never a second implementation (W4): the trip cell's shape is identical to
    # the total cell's by construction, so every consumer of the total cell works
    # on the trip cell unchanged, and the two lenses cannot drift in how they
    # compute a rate. Markers are the CALLER's own (owner-scoped): in system
    # scope the subset is pre-filtered to the caller's spans, so another user's
    # same-tag agent can never leak into a trip cell. Fail-open: a lens that
    # cannot resolve degrades to the whole record, never breaks the dashboard.
    try:
        from trusted_data_agent.core import trust_trip
        _marker_uuid = _get_user_uuid_from_request()
        _markers = trust_trip.latest_markers(_marker_uuid) if _marker_uuid else {}
        if _markers:
            _self = str(getattr(current_user, "id", None) or _marker_uuid or "")
            _own = spans if scope != "system" else [
                s for s in spans
                if str((s.get("attributes") or {}).get("user.uuid") or "") == _self]
            _trip_cells = online_quality_by_agent(
                trust_trip.spans_since(_own, _markers), per_user=(scope == "system"))
            # The leg logbook, per tag (newest first) — the PREVIOUS leg (W7) is
            # the interval between the two latest markers, or window-start → marker
            # for a first reset, so the panel can answer "did the fix work?".
            _logbook: dict = {}
            for _mk in trust_trip.list_markers(_marker_uuid, limit=200):
                _logbook.setdefault(_mk["profile_tag"], []).append(_mk)
            for _tag, _m in _markers.items():
                _key = f"{_tag}::{_self}" if scope == "system" else _tag
                _cell = by_agent.get(_key)
                if _cell is None:
                    continue
                # No spans since the reset ⇒ an honestly EMPTY leg (turns 0), never
                # a missing lens: the ring must say "the leg is empty", not fall
                # back to the whole record as if no reset had happened.
                _trip = dict(_trip_cells.get(_key) or {"turns": 0, "failures": 0})
                _trip.update({"since": _m.get("created_at"),
                              "note": _m.get("note"),
                              "leg_n": _m.get("leg_n") or 1,
                              "integrity_state": _m.get("integrity_state")})
                _prevs = _logbook.get(_tag) or []
                _prev_start = _prevs[1]["created_at_ns"] if len(_prevs) > 1 else None
                _prev_spans = trust_trip.spans_between(
                    _own, _tag, _prev_start, _m["created_at_ns"])
                if _prev_spans:
                    _pcell = online_quality_by_agent(
                        _prev_spans, per_user=(scope == "system")).get(_key)
                    if _pcell:
                        _trip["prev"] = _pcell
                        _trip["prev_since"] = (_prevs[1]["created_at"]
                                               if len(_prevs) > 1 else None)
                _cell["trip"] = _trip
    except Exception as _te:  # noqa: BLE001 — lens is additive, never load-bearing
        app_logger.debug(f"trust-trip: dashboard lens skipped: {_te}")

    return jsonify({
        "enabled": bool(getattr(APP_CONFIG, "ONLINE_EVAL_ENABLED", False)),
        # #24 — the ring reads THIS payload, and JUDGED has always read its own
        # master from it (`enabled` above). GROUNDED/GUARDED need theirs the same
        # way, or they render a per-profile mode as running when the runtime is off.
        "deployment_masters": _deployment_masters(),
        # The band floors the roster, the ring and the KPI charts all colour by.
        "quality_bands": _quality_bands(),
        # Rule 8.2's practice signal for BOUNDED: does anything here run unattended?
        "scope": scope,
        "is_admin": is_admin,
        "user_count": len(users),
        "user_filter": user_filter if scope == "system" else None,
        "users": _usernames_for(users) if scope == "system" else {},
        "self_uuid": getattr(current_user, "id", None),
        "total_spans": len(spans),
        "spans_with_failure": failures,
        "pass_rate_by_dimension": online_pass_rate_by_dimension(spans),
        "failure_clusters": cluster_online_failures(spans),
        "by_profile_class": by_class,
        "by_agent": by_agent,
        "by_flow": online_quality_by_flow(spans),
    }), 200


