def _integrity_states_by_tag(user_uuid):
    """Synchronous: the caller's profiles -> {tag: trust state}. Runs in a worker thread.

    Fully absence-tolerant — the Ontology Suite is a removable unit, so any
    import/resolution failure degrades to unknown (an empty map / a missing tag).
    """
    integrity_by_tag = {}
    try:
        from trusted_data_agent.core.config_manager import get_config_manager
        from trusted_data_agent.api.trust_routes import resolve_profiles_shared
        # The SAME resolution /v1/trust/agents runs — joined when both are in flight (the
        # Trust page asks for both at once). A failed agent is left out: unknown here.
        for prof, at in resolve_profiles_shared(get_config_manager().get_profiles(user_uuid) or [],
                                                user_uuid):
            tag = prof.get("tag")
            if not tag or isinstance(at, Exception):
                continue
            try:
                state = getattr(getattr(at, "state", None), "value", None) or \
                    (at.to_dict().get("state") if hasattr(at, "to_dict") else None)
                if state:
                    integrity_by_tag[tag] = state
            except Exception:
                continue
    except Exception:
        integrity_by_tag = {}
    return integrity_by_tag


@rest_api_bp.route("/v1/evals/agents/trust-behavior", methods=["GET"])
@operation("evals.trust_behavior", effect="read", scope="own",
           summary="Each agent's behavioural trust score: how its signature, its gates and its quality readings combine, and what pulls it down",
           query={"limit": Arg("integer", "how many recent readings to aggregate")})
@require_auth
async def evals_agents_trust_behavior(current_user):
    """Behavioral Trust Score — per-agent fusion of Trust-Membrane integrity
    (signed/changed/unsigned) with the live eval track record (recency-weighted
    pass rate, trust-critical dimensions, volume gates, staleness decay).

    Pure read-side observability: computing this never gates or alters anything.
    ``enabled`` in the response reflects the admin `trust_behavior` block and
    governs only whether UI surfaces render the ring/states. Integrity states
    are resolved defensively for the requesting user's own profiles — if the
    Trust Membrane (Ontology Suite) is absent, integrity reads unknown and the
    composite is honestly behavior-only. Scope-gated like the other agent views.
    """
    from trusted_data_agent.eval.analysis import dedupe_spans
    from trusted_data_agent.eval.trust_behavior import assess_agents, resolve_config
    from trusted_data_agent.core.config import APP_CONFIG
    from trusted_data_agent.auth.features import user_has_feature, Feature

    scope = (request.args.get("scope") or "my").lower()
    is_admin = user_has_feature(current_user, Feature.VIEW_ALL_SESSIONS)
    if scope == "system" and not is_admin:
        return jsonify({"error": "system scope requires VIEW_ALL_SESSIONS"}), 403
    user_uuid = _get_user_uuid_from_request()
    user_filter = _eval_scope_user_filter(scope) if scope == "system" else user_uuid

    cfg = resolve_config(getattr(APP_CONFIG, "TRUST_BEHAVIOR", None) or {})
    limit = int(request.args.get("limit", 2000))
    spans = await asyncio.to_thread(
        lambda: dedupe_spans(_read_online_spans(limit, user_uuid=user_filter)))

    # Integrity join: resolve the Trust-Membrane state for the requesting user's
    # profiles (tag → state). Fully absence-tolerant — the Ontology Suite is a
    # removable unit, so any import/resolution failure degrades to unknown.
    # Resolved OFF the event loop (the same reason /v1/trust/agents does it): the body
    # is synchronous SQLite + hashing over every profile, and run inline it froze the
    # single asyncio loop — every other request of every user — for its whole duration.
    integrity_by_tag = await asyncio.to_thread(_integrity_states_by_tag, user_uuid)

    # TC-35: system scope keys cells `tag::uuid` (two users' same-tag agents never merge)
    # and integrity caps only the requester's own cells; my scope keeps plain-tag keys.
    agents = assess_agents(spans, integrity_by_tag=integrity_by_tag, config=cfg,
                           per_user=(scope == "system"), self_uuid=user_uuid)
    return jsonify({
        "enabled": bool(cfg.get("enabled", False)),
        "scope": scope,
        "self_uuid": user_uuid if scope == "system" else None,
        # TC-32: `breaker_mode` MUST travel — the TRUSTED station narrates whether a falling
        # badge freezes autonomy from it. Omitting it made the frontend read `undefined → 'off'`,
        # so an admin's `freeze_autonomy` rendered as "the breaker is off, a falling badge
        # changes nothing" — a live safety control displayed as disabled.
        # `trust_dims` travels so the Trust Circle's derivation explainer can NAME the
        # dimensions that actually weight the composite — without it the frontend would
        # hardcode a second copy of the list and drift from the scorer (the defect class
        # the one-source rule exists to prevent).
        "config": {k: cfg[k] for k in ("window_turns", "min_turns_proven", "min_turns_trusted",
                                       "healthy_floor", "trusted_floor", "at_risk_floor",
                                       "half_life_days", "stale_days", "trust_dims",
                                       "trust_dim_weight") if k in cfg},
        "breaker_mode": cfg.get("breaker_mode", "off"),
        "agents": agents,
    }), 200


@rest_api_bp.route("/v1/evals/backtest", methods=["POST"])
@operation("evals.backtest", effect="read", scope="own",
           summary="What a proposed trust policy would have done to the caller's past turns — answers withheld, flagged, sent to a judge — at no token cost",
           body={"policy": Arg("object", "the gates and modes to try, e.g. {\"grounding\": \"enforce\"}", required=True),
                 "profile_tag": "only one agent's turns (its @TAG)",
                 "max_sessions": Arg("integer", "how many recent conversations (default 20, max 100)"),
                 "max_turns": Arg("integer", "how many turns at most (default 300)"),
                 "sessions": Arg("array", "only these conversations")},
           notes="Read-only: it replays what was recorded; nothing is changed. A judge is not simulated — a flagged turn reads 'would go to the judge'.")
@require_auth
async def evals_policy_backtest(current_user):
    """Policy backtesting — replay a PROPOSED trust policy over the user's own
    already-persisted turns and report what it WOULD have done, deterministically
    and at zero token cost. De-risks the observe → enforce climb: "enforce on
    these profiles would have redacted 3 answers, escalated 2 to the judge, and
    blocked 1 injected request — here they are."

    Body: {policy: {grounding_mode?, outbound?: {mode, pii, toxicity},
                    inbound?: {mode}},
           sessions?: [session_id, ...],   # default: the user's recent sessions
           profile_tag?: "TAG",            # optional filter
           max_sessions?: 20, max_turns?: 300}

    Guardrail projections are exact (same policy engine, stored text). Grounding
    projections are trigger-level from the recorded gate stamp — the judge (an
    LLM) is honestly NOT simulated, so a flagged turn reads "would escalate to
    the judge", never a certain block. Read-only: nothing is altered.
    """
    from trusted_data_agent.eval.backtest import backtest_turns
    from trusted_data_agent.core import session_manager

    data = await request.get_json() or {}
    policy = data.get("policy") or {}
    if not any(policy.get(k) for k in ("grounding_mode", "outbound", "inbound")):
        return jsonify({"error": "policy must include at least one of "
                                 "grounding_mode / outbound / inbound"}), 400
    user_uuid = _get_user_uuid_from_request()
    max_sessions = max(1, min(int(data.get("max_sessions", 20)), 100))
    max_turns = max(1, min(int(data.get("max_turns", 300)), 2000))
    profile_tag = (data.get("profile_tag") or "").strip() or None

    session_ids = data.get("sessions")
    if not session_ids:
        listing = await session_manager.get_all_sessions(user_uuid, limit=max_sessions)
        session_ids = [s.get("id") for s in (listing or {}).get("sessions", []) if s.get("id")]
    session_ids = list(session_ids)[:max_sessions]

    turns = []
    for sid in session_ids:
        if len(turns) >= max_turns:
            break
        try:
            wh = await session_manager.get_workflow_history(user_uuid, sid)
        except Exception:
            continue
        for t in wh or []:
            if not isinstance(t, dict):
                continue
            if profile_tag and (t.get("profile_tag") or "").lstrip("@") != profile_tag.lstrip("@"):
                continue
            if "session_id" not in t:
                t = {**t, "session_id": sid}
            turns.append(t)
            if len(turns) >= max_turns:
                break

    summary = backtest_turns(turns, policy)
    return jsonify({"policy": policy, "sessions_examined": len(session_ids),
                    "summary": summary}), 200


@rest_api_bp.route("/v1/assurance/inbox", methods=["GET"])
@operation("assurance.inbox", effect="read", scope="own",
           summary="The caller's Assurance Inbox: trust incidents to look at — answers withheld or flagged, gates that fired, agents whose trust changed",
           query={"include_acked": Arg("boolean", "also the incidents already acknowledged"),
                  "sessions": Arg("integer", "how many recent conversations to scan for live findings (default 10, max 50)")},
           summary_fields=("event_type", "severity", "profile_tag", "summary", "session_id"))
@require_auth
async def assurance_inbox(current_user):
    """The Assurance Inbox — trust incidents as a triageable queue, not
    dashboard archaeology. Merges two honest sources:

    - **stored** events (breaker trips, memory quarantines — out-of-band
      incidents recorded by their emit sites; ack-able), and
    - **derived** events read live from the turn stamps the platform already
      persists (grounding blocks/annotations, guardrail redactions/refusals,
      honesty rewrites, and the multi-turn **session sentinel**) — these can
      never disagree with the trace and need no ack (they ARE the record).

    ``?include_acked=true`` shows acknowledged stored items too;
    ``?sessions=N`` bounds the derived scan (default 10 recent sessions).
    """
    from trusted_data_agent.core import trust_events, session_manager

    user_uuid = _get_user_uuid_from_request()
    include_acked = (request.args.get("include_acked") or "").lower() == "true"
    try:
        max_sessions = _coerce_int(request.args.get("sessions"), "sessions", 10, lo=1, hi=50)
    except _BadParam as e:
        return jsonify({"error": str(e)}), 400

    stored = trust_events.list_events(user_uuid, include_acked=include_acked, limit=100)
    # I2/#57 — mark receipts (records of acts the OWNER performed) so the UI can show
    # them as history without presenting them as work awaiting a decision.
    for _e in stored:
        _e["is_receipt"] = trust_events.is_receipt(_e.get("event_type"))

    # I2/#48 — join every derived observation to its recorded human decision. Derived
    # items are recomputed from the immutable trace, so without this a decided incident
    # reads "unresolved" forever and REVIEWED accuses the owner of inaction they took.
    dispositions = {}
    try:
        from trusted_data_agent.core import review_queue
        dispositions = trust_events.disposition_index(
            review_queue.list_items(user_uuid, status=None, limit=500))
    except Exception as e:
        app_logger.warning(f"assurance-inbox: disposition join unavailable: {e}")

    derived = []
    try:
        listing = await session_manager.get_all_sessions(user_uuid, limit=max_sessions)
        for s in (listing or {}).get("sessions", []):
            sid = s.get("id")
            if not sid:
                continue
            try:
                wh = await session_manager.get_workflow_history(user_uuid, sid)
            except Exception:
                continue
            derived.extend(trust_events.derive_turn_events(
                wh, session_id=sid, dispositions=dispositions))
            sentinel = trust_events.derive_session_sentinel(wh, session_id=sid)
            if sentinel:
                derived.append(sentinel)
        # PROP-002b — the red⇒item direction of the completeness invariant: a
        # station reading danger from a failing RATE files one ack-able
        # observation per (agent, station), so a red segment always resolves to
        # a worked item, not just a colour.
        try:
            from trusted_data_agent.eval import analysis as _analysis
            from trusted_data_agent.agent.assurance_points import station_dimensions
            _spans = _read_online_spans(500, user_uuid=user_uuid)
            if _spans:
                _cells = _analysis.online_quality_by_agent(_spans)
                derived.extend(_analysis.station_shortfalls(
                    _cells, review_floor=_quality_bands().get("review", 0.5),
                    station_dims=station_dimensions()))
        except Exception as e:
            app_logger.warning(f"assurance-inbox: shortfall derivation skipped: {e}")
        # PROP-002 (completeness invariant): join each derived observation to its
        # recorded acknowledgment. The trace is never rewritten — the ack is a
        # separate stored disposition ABOUT it.
        derived = trust_events.apply_derived_acks(
            derived, trust_events.derived_ack_index(user_uuid))
    except Exception as e:
        app_logger.warning(f"assurance-inbox: derived scan failed: {e}")

    # PROP-002b — the per-station reporting levels (operator-assigned from the ONE
    # severity construct; danger always surfaces). Served so every consumer — badge,
    # colour fold, default view — applies the same assignment.
    from trusted_data_agent.agent.assurance_points import normalize_station_reporting
    reporting = normalize_station_reporting(
        getattr(APP_CONFIG, "ASSURANCE_STATION_REPORTING", None))

    return jsonify({
        "stored": stored,
        "derived": derived,
        "unacked": trust_events.unacked_count(user_uuid, reporting=reporting),
        "station_reporting": reporting,
        "sessions_scanned": max_sessions,
    }), 200


