@operation("assurance.inbox_ack", effect="human_only", scope="own",
           summary="Acknowledge an incident in the Assurance Inbox — the person who looked at it says so; an agent never does",
           path={"event_id": "the incident's id"})
@require_auth
async def assurance_inbox_ack(current_user, event_id):
    """Acknowledge a STORED inbox event."""
    from trusted_data_agent.core import trust_events
    user_uuid = _get_user_uuid_from_request()
    ok = trust_events.ack_event(user_uuid, event_id)
    return jsonify({"acknowledged": ok}), (200 if ok else 404)


@rest_api_bp.route("/v1/assurance/inbox/derived/ack", methods=["POST"])
@operation("assurance.inbox_ack_derived", effect="human_only", scope="own",
           summary="Acknowledge a live finding in the Assurance Inbox — the person who looked at it says so; an agent never does")
@require_auth
async def assurance_inbox_ack_derived(current_user):
    """Acknowledge a DERIVED observation or the session sentinel (PROP-002 —
    the completeness invariant: a danger reading nobody can ever disposition is
    permanently unresolvable residue). The sealed trace itself is never
    rewritten; the acknowledgment is a stored disposition ABOUT it, keyed
    ``(session_id, turn_id, event_type)`` (turn_id null = session-level).

    Body: ``{"session_id": "...", "turn_id": 3 | null, "event_type": "..."}``.
    """
    from trusted_data_agent.core import trust_events
    user_uuid = _get_user_uuid_from_request()
    body = await request.get_json(silent=True) or {}
    event_type = (body.get("event_type") or "").strip()
    if not event_type:
        return jsonify({"error": "event_type is required"}), 400
    ok = trust_events.ack_derived(
        user_uuid, body.get("session_id"), body.get("turn_id"), event_type)
    return jsonify({"acknowledged": ok}), (200 if ok else 500)


