@rest_api_bp.route("/v1/assurance/reviews", methods=["GET"])
@operation("assurance.reviews", effect="read", scope="own",
           summary="The caller's review queue: answers withheld for a person and changes agents submitted, with why each waits and who may decide",
           query={"status": Arg("string", "which items (default pending)", enum=("pending", "approved", "rejected", "retained", "all"))},
           summary_fields=("id", "source", "status", "profile_tag", "reason", "created_at"))
@require_auth
async def assurance_reviews(current_user):
    """The HITL review queue — withheld originals parked by ``review`` mode
    (enforce WITH retention) on the outbound guardrail / grounding gate.
    Owner-scoped: you review your own agents' withheld answers (the case that
    matters — scheduled/autonomous runs nobody watched). ``?status=`` filters
    (default pending; ``all`` for everything); ``?include_content=true`` returns
    the withheld originals (owner's own content)."""
    from trusted_data_agent.core import review_queue
    user_uuid = _get_user_uuid_from_request()
    status = (request.args.get("status") or "pending").lower()
    items = review_queue.list_items(
        user_uuid, status=None if status == "all" else status,
        include_content=(request.args.get("include_content") or "").lower() == "true",
        awaiting_me=True,
        limit=max(1, min(int(request.args.get("limit", 100)), 500)))
    # four eyes (PROP-008 §5.4a): an item may be someone else's awaiting this caller, or this
    # caller's own awaiting a designated approver — both are named in words, never as ids
    _names = _usernames_for({i.get("owner_id") for i in items}
                            | {a for i in items for a in (i.get("approvers") or [])}
                            | {i.get("decided_by") for i in items if i.get("decided_by")})
    for i in items:
        # a decided item says WHO decided, in words ("you" or the approver's name)
        if i.get("decided_by"):
            i["decided_by_label"] = "you" if i["decided_by"] == user_uuid else (
                _names.get(i["decided_by"]) or str(i["decided_by"])[:8])
        if i.get("owner_id") and i["owner_id"] != user_uuid:
            i["owner"] = _names.get(i["owner_id"]) or str(i["owner_id"])[:8]
        if i.get("approvers"):
            i["awaiting"] = [_names.get(a) or str(a)[:8] for a in i["approvers"]]
    return jsonify({"items": items,
                    "pending": review_queue.pending_count(user_uuid),
                    # Recovery-ledger entries (enforce-parked full withholdings) —
                    # recoverable, dispositionable, but never owed work: kept OUT of
                    # `pending` so the REVIEWED station and the inbox badge keep
                    # meaning "a human must act".
                    "retained": review_queue.retained_count(user_uuid)}), 200


async def _perform_parked_action(user_uuid: str, item_id: str, approved_by: str = None) -> dict:
    """Perform a parked action for its OWNER (OBDA-ACT, PROP-008 §5.4): ``user_uuid`` is the
    owner — the graph, the agent and the connection are theirs. ``approved_by`` names the
    person who approved (the owner, or a designated approver — §5.4a)."""
    import asyncio as _asyncio
    import json as _json
    from trusted_data_agent.core import review_queue, action_perform
    from trusted_data_agent.core import sqlite_util as _su
    from components.builtin.knowledge_graph.graph_store import GraphStore
    item = review_queue.get_item(user_uuid, item_id)
    payload = _json.loads((item or {}).get("original_text") or "{}")
    kg_id = payload.get("kg_id")
    conn = _su.connect(str(DB_PATH))
    try:
        row = conn.execute("SELECT profile_id FROM kg_metadata WHERE kg_id = ? AND user_uuid = ?",
                           (kg_id, user_uuid)).fetchone()
    finally:
        conn.close()
    if not row:
        raise action_perform.ActionPerformError("not_found", "the parked action's graph is not yours")
    store = GraphStore(row[0], user_uuid, kg_id=kg_id)

    def _lookup(pid):
        from trusted_data_agent.core.config_manager import get_config_manager
        return get_config_manager().get_profile(pid, user_uuid)
    # the write blocks on the warehouse: run it off the event loop
    return await _asyncio.to_thread(action_perform.perform_parked, store, user_uuid, item,
                                    profile_lookup=_lookup, approved_by=approved_by)


@rest_api_bp.route("/v1/assurance/reviews/<item_id>", methods=["DELETE"])
@operation("assurance.review_withdraw", effect="human_only", scope="own",
           summary="Withdraw one of the caller's pending review items — the owner's call, never an agent's",
           path={"item_id": "the review item"})
@require_auth
async def assurance_review_withdraw(current_user, item_id):
    """The owner withdraws one of their own PENDING items — a parked write nobody will decide.
    Nothing was ever written for it; the act log keeps the park. A designated approver
    cannot withdraw (403); a decided item is not withdrawn (409)."""
    from trusted_data_agent.core import review_queue
    user_uuid = _get_user_uuid_from_request()
    gone = review_queue.withdraw(user_uuid, item_id)
    if gone is None:
        return jsonify({"error": "review item not found"}), 404
    if gone.get("refused"):
        return jsonify({"error": gone["refused"], "message": gone.get("message")}), (403 if gone["refused"] == "not_owner" else 409)
    return jsonify({"status": "success", "withdrawn": {"id": item_id, "source": gone.get("source")}})


@rest_api_bp.route("/v1/assurance/reviews/<item_id>/<decision>", methods=["POST"])
@operation("assurance.review_decide", effect="human_only", scope="own",
           summary="Approve or reject a review item — the approval is the control; an agent is never its own reviewer",
           path={"item_id": "the review item", "decision": "approve or reject"})
@require_auth
async def assurance_review_decide(current_user, item_id, decision):
    """Disposition a pending review item: ``approve`` (the owner has seen the
    withheld original and accepts it) or ``reject`` (the withholding stands).
    Either way an audit event is appended to the originating turn so the
    disposition re-renders on reload and lands in the sealed record's system
    events. Approval does NOT rewrite the delivered conversation (history stays
    honest); the approved original remains readable from the queue item.

    ``{"release_to_conversation": true}`` (approve only, default false): the
    owner EXPLICITLY releases the withheld original INTO the conversation —
    forward-only: subsequent turns receive it via the ``review_release``
    context module (clearly labelled as a human decision) and its exact PII
    values join the session's outbound released-value allowlist so the agent
    can state what the owner released. The sealed turn is never rewritten."""
    from trusted_data_agent.core import review_queue, session_manager
    if decision not in ("approve", "reject"):
        return jsonify({"error": "decision must be approve or reject"}), 400
    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    note = (data.get("note") or "").strip() or None
    release = bool(data.get("release_to_conversation")) and decision == "approve"

    item = review_queue.get_item(user_uuid, item_id)
    if not item:
        return jsonify({"error": "review item not found"}), 404
    # four eyes (PROP-008 §5.4a): an item awaiting designated approvers is decided by one of
    # them — its owner cannot approve their own agent's write. Refused before anything runs.
    if not item.get("can_decide"):
        _n = _usernames_for(item.get("approvers") or [])
        who = ", ".join(_n.get(a) or str(a)[:8] for a in (item.get("approvers") or [])) or "its owner"
        return jsonify({"error": "not_your_decision", "awaiting": who,
                        "message": f"This parked write awaits {who}. The agent's owner cannot approve "
                                   f"it — a designated approver decides."}), 403
    owner_uuid = item.get("owner_id") or user_uuid
    # Release is only coherent for a withheld ANSWER. An inbound item's original
    # is the user's request — for a parked prompt injection, that is the attacker's
    # payload, and releasing it would inject it into the model's context labelled
    # as owner-approved. Refuse loudly rather than silently downgrade to a plain
    # approve: the owner asked for something specific and must learn it was denied.
    if release and not review_queue.is_releasable_source(item.get("source")):
        return jsonify({
            "error": "release_not_permitted_for_source",
            "source": item.get("source"),
            "message": ("This item was withheld on the way IN — its original is the "
                        "request itself, not an answer. Releasing it would place that "
                        "text into the agent's context as owner-approved. Approve or "
                        "uphold instead."),
        }), 400
    status = "approved" if decision == "approve" else "rejected"
    # OBDA-ACT (PROP-008 §5.4): a parked ACTION is performed on approval — and only then. The
    # write happens BEFORE the disposition is recorded: an approval whose write is refused
    # (the contract changed while it waited, a check no longer holds, the signature is no
    # longer intact) leaves the item OPEN with the reason, never "approved" over nothing.
    # The write and its disposition are ONE unit, shielded from cancellation: a client that
    # disconnects mid-request (a closed tab, a dropped connection) cancels the handler, and
    # an approval cancelled between the two would leave a PERFORMED write on an item still
    # pending — approvable a second time (found by the four-eyes browser run, Oct 2026).
    async def _perform_and_record():
        rec, nt = None, note
        if decision == "approve" and item.get("source") == "action":
            try:
                rec = await _perform_parked_action(owner_uuid, item_id,
                                                   approved_by=f"user:{user_uuid}")
            except Exception as e:  # noqa: BLE001
                return ("refused", {"error": "action_not_performed", "code": getattr(e, "code", "error"),
                                    "message": getattr(e, "message", str(e))}), None, nt
            if rec.get("outcome") != "performed":
                return ("refused", {"error": "action_not_performed", "code": rec.get("refused_check"),
                                    "message": rec.get("refusal"), "record": rec}), None, nt
            nt = (nt + " · " if nt else "") + (
                f"performed: {rec.get('rows_affected')} row(s), receipt "
                f"{str(rec.get('invocation_hash') or '')[:12]}")
        if decision == "approve" and item.get("source") == "platform":
            # A parked PLATFORM write (TDA_Platform, phase 3): run as its owner after the
            # request is checked against the current catalog — and only then recorded approved.
            from trusted_data_agent.core import platform_operations as _pops
            rec = await _pops.perform_parked(item, owner_uuid, approved_by=f"user:{user_uuid}")
            if rec.get("outcome") != "performed":
                return ("refused", {"error": "platform_write_not_performed", "message": rec.get("message"),
                                    "record": rec}), None, nt
            nt = (nt + " · " if nt else "") + f"performed: {rec.get('op')} answered {rec.get('status')}"
        return review_queue.decide(user_uuid, item_id, status, note=nt,
                                   release_to_context=release), rec, nt
    import asyncio as _asyncio_d
    decided, action_record, note = await _asyncio_d.shield(_asyncio_d.ensure_future(_perform_and_record()))
    if isinstance(decided, tuple) and decided and decided[0] == "refused":
        return jsonify(decided[1]), 409
    if decided is None:
        # TC-73: a STORE failure must not be reported to the owner as "the item is not
        # pending" — that reads as a settled disposition when nothing was recorded.
        return jsonify({"error": "the review store is unavailable — nothing was recorded; "
                                 "try again"}), 503
    if not decided:
        return jsonify({"error": "item is not open (already decided)"}), 409

    # Audit trail on the originating turn (best-effort; the decision stands
    # regardless — the queue row is the primary record).
    try:
        if item.get("session_id") and item.get("turn_id"):
            if status != "approved":
                verdict_txt = "withholding upheld by the owner"
            elif release:
                verdict_txt = ("released by the owner after review — "
                               "INTO the conversation (available to subsequent turns)")
            else:
                verdict_txt = "released by the owner after review (record only)"
            if action_record is None and item.get("source") == "action" and status == "rejected":
                # a REJECTED write ended too: recorded as refused on its turn, so the parked row
                # flips to the refusal and the fold never reads a rejected write as still parked
                try:
                    _pl = json.loads(item.get("original_text") or "{}")
                except Exception:  # noqa: BLE001
                    _pl = {}
                if _pl.get("invocation_hash"):
                    await session_manager.record_action_confirmation(
                        owner_uuid, item["session_id"], item["turn_id"], _pl["invocation_hash"],
                        {"action": _pl.get("action"), "version": _pl.get("version"), "outcome": "refused",
                         "refused_check": "rejected_by_owner",
                         "refusal": ("rejected by the owner in the Assurance Inbox"
                                     if user_uuid == owner_uuid else
                                     "rejected by the designated approver in the Assurance Inbox"),
                         "rejected_by": f"user:{user_uuid}", "review_id": item_id,
                         "invocation_hash": _pl["invocation_hash"]})
            if action_record is not None and action_record.get("invocation_hash"):
                # the parked act ENDED: recorded as its confirmation on the turn, so the one
                # fold (`action_perform.summarize`) reads it as performed everywhere — the
                # answer row, the capsule, the reloaded Live Status card, BOUNDED — once
                from trusted_data_agent.api.action_routes import confirmation_entry
                _entry = confirmation_entry(action_record.get("action") or "", action_record,
                                            user_uuid, None)
                _entry["approved_by"] = f"user:{user_uuid}"
                _entry["review_id"] = item_id
                await session_manager.record_action_confirmation(
                    owner_uuid, item["session_id"], item["turn_id"],
                    action_record["invocation_hash"], _entry)
            await session_manager.append_system_events_to_turn(
                owner_uuid, item["session_id"], int(item["turn_id"]),
                [{"type": "review_decision",
                  "payload": {"step": "Human Review",
                              "type": "review_decision",
                              "details": {"review_id": item_id, "source": item.get("source"),
                                          "decision": status, "note": note,
                                          "released_to_context": release,
                                          "summary": (
                                              (f"Parked write performed after "
                                               f"{'the owner' if user_uuid == owner_uuid else 'the designated approver'}'s approval — "
                                               f"{action_record.get('rows_affected') or 0} row(s)")
                                              if action_record is not None else
                                              ("Parked write rejected by the owner — nothing was written"
                                               if user_uuid == owner_uuid else
                                               "Parked write rejected by the designated approver — nothing was written")
                                              if item.get("source") == "action" else
                                              f"Withheld answer {verdict_txt}")}}}])
    except Exception as e:
        app_logger.warning(f"review decision audit event failed: {e}")

    # Release-to-conversation, APPEND-ONLY: the delivered history is never
    # rewritten — instead the decision is broadcast so the open UI can react,
    # and the answer capsule on the originating turn surfaces the released
    # original (it reads the review queue). Nothing is silently delivered:
    # the release is always labelled as a human decision.
    try:
        import asyncio as _asyncio
        from trusted_data_agent.core.config import APP_STATE
        payload = {"review_id": item_id, "decision": status,
                   "session_id": item.get("session_id"), "turn_id": item.get("turn_id"),
                   "profile_tag": item.get("profile_tag"), "source": item.get("source"),
                   "released_to_context": release}
        # the owner's open answer flips in place; a designated approver's inbox refreshes too
        for _who in {owner_uuid, user_uuid}:
            for _q in list(APP_STATE.get("notification_queues", {}).get(_who, set())):
                _q.put_nowait({"type": "review_decision_notice", "payload": payload})   # TC-70
    except Exception as e:
        app_logger.debug(f"review decision notification failed: {e}")

    # A release INTO the conversation is a deliberate act of human oversight —
    # record it as a trust event so it appears in the trust history / audit pack.
    if release:
        try:
            from trusted_data_agent.core import trust_events
            trust_events.record_event(
                user_uuid, "review_release", severity="info",
                summary=(f"Owner released a withheld original into the conversation "
                         f"(turn {item.get('turn_id')}, {item.get('source')})"),
                session_id=item.get("session_id"),
                payload={"review_id": item_id, "turn_id": item.get("turn_id"),
                         "source": item.get("source")})
        except Exception as e:
            app_logger.debug(f"release trust event failed: {e}")

    if action_record is not None:
        try:
            from trusted_data_agent.core import action_perform as _ap_
            _ap_.emit_step(owner_uuid, {**action_record, "approved_by": f"user:{user_uuid}"},
                           session_id=item.get("session_id"), turn_id=item.get("turn_id"),
                           confirmed_by=f"user:{user_uuid} (approved in the Assurance Inbox)")
        except Exception:  # noqa: BLE001
            pass
        return jsonify({"id": item_id, "status": status, "released_to_context": False,
                        "action_record": {k: v for k, v in action_record.items()
                                          if not str(k).startswith("_") and k != "checks"}}), 200

    return jsonify({"id": item_id, "status": status,
                    "released_to_context": release}), 200


@rest_api_bp.route("/v1/assurance/trust-history/<tag>", methods=["GET"])
@operation("assurance.trust_history", effect="read", scope="own",
           summary="One agent's trust changelog: every signature, attestation, change and renewal, oldest first",
           path={"tag": "the agent's @TAG"})
@require_auth
async def assurance_trust_history(current_user, tag):
    """Trust changelog for one agent — the audit-facing timeline of how trust in
    this agent evolved: the current attestation (sign-off), stored trust
    incidents (breaker trips, quarantines), and HITL review items + decisions.
    Owner-scoped, read-only, assembled from records that already exist (no new
    tracking); the Trust Membrane is imported defensively (suite absent →
    sign-off entries simply absent)."""
    from trusted_data_agent.core import trust_events, review_queue
    from trusted_data_agent.core.config_manager import get_config_manager

    user_uuid = _get_user_uuid_from_request()
    tag_clean = (tag or "").lstrip("@")
    timeline = []

    # Sign-off (Trust Membrane attestation — defensive; the suite is removable).
    try:
        prof = next((p for p in (get_config_manager().get_profiles(user_uuid) or [])
                     if (p.get("tag") or "").lstrip("@") == tag_clean), None)
        if prof:
            from trusted_data_agent.core.trust import store as trust_store
            att = trust_store.load_attestation("agent", prof.get("id"), owner_uuid=user_uuid)
            if att and att.get("signed"):
                signed_at = att.get("signed_at")
                ts = None
                try:
                    from datetime import datetime, timezone
                    ts = datetime.fromtimestamp(float(signed_at), tz=timezone.utc).isoformat() \
                        if signed_at else None
                except Exception:
                    # TC-74: NEVER fall back to the raw epoch-seconds string — every other
                    # timeline entry is ISO-8601 and the merge sorts LEXICOGRAPHICALLY, so
                    # a "17219…" string misordered the sign-off entry in an audit-facing
                    # timeline. An unparseable stamp is honestly omitted (entry keeps ts=None
                    # and sorts to the end) rather than silently misplaced.
                    ts = None
                timeline.append({"kind": "signed", "ts": ts,
                                 "summary": f"Agent signed (fingerprint {str(att.get('signer_fingerprint') or '')[:12]}…)"})
    except Exception:
        pass

    # Stored trust incidents for this agent (breaker, quarantines — incl. acked).
    for ev in trust_events.list_events(user_uuid, include_acked=True, limit=200):
        if (ev.get("profile_tag") or "").lstrip("@") == tag_clean:
            timeline.append({"kind": "incident", "ts": ev.get("created_at"),
                             "severity": ev.get("severity"),
                             "event_type": ev.get("event_type"),
                             "summary": ev.get("summary")})

    # Review items + decisions (HITL).
    _rv_items = review_queue.list_items(user_uuid, status=None, limit=200)
    _decider = _usernames_for([it.get("decided_by") for it in _rv_items if it.get("decided_by")]
                              + [a for it in _rv_items for a in (it.get("approvers") or [])])
    def _who(uid):
        return "the owner" if (not uid or uid == user_uuid) else (_decider.get(uid) or str(uid)[:8])
    for it in _rv_items:
        if (it.get("profile_tag") or "") != tag_clean:
            continue
        if it.get("status") == "pending":
            # a parked WRITE is not a withheld answer (PROP-008): it awaits a decision, and with
            # four eyes it awaits a named approver, never its owner
            if it.get("source") == "action":
                _aw = ", ".join(_who(a) for a in (it.get("approvers") or [])) or "the owner"
                summ = f"Parked write ({', '.join(it.get('categories') or []) or 'an action'}) — awaiting {_aw}"
            else:
                summ = f"Answer withheld by the {it.get('source')} — awaiting disposition"
            timeline.append({"kind": "review", "ts": it.get("created_at"), "summary": summ})
        elif it.get("status") == "retained":
            # A recovery-ledger entry, not owed work — the wording must never
            # imply a disposition is outstanding.
            timeline.append({"kind": "review", "ts": it.get("created_at"),
                             "summary": f"Answer withheld by the {it.get('source')} — "
                                        "original retained (recoverable, no action owed)"})
        else:
            if it.get("source") == "action":
                # a decision recorded before `decided_by` existed names nobody — never a guess
                verb = ("approved" if it.get("status") == "approved" else "rejected") + (
                    f" by {_who(it.get('decided_by'))}" if it.get("decided_by") else "")
                head = f"Parked write ({', '.join(it.get('categories') or []) or 'an action'}) {verb}"
            else:
                verb = "released by the owner" if it.get("status") == "approved" else "withholding upheld"
                head = f"Review decided: {verb}"
            timeline.append({"kind": "review_decision", "ts": it.get("decided_at"),
                             "decision": it.get("status"),
                             "summary": head
                                        + (f" — {it.get('note')}" if it.get("note") else "")})

    # The agent's ACTS (PROP-008 §6) — every face, the unattended ones included: a write a
    # flow or a schedule performed while nobody watched is exactly what an auditor asks for.
    try:
        from trusted_data_agent.core import action_act_log
        from trusted_data_agent.core.action_perform import act_words
        _face_word = {"conversation": "In conversation", "flow": "By a flow", "scheduler": "On a schedule",
                      "dashboard": "From a dashboard", "mcp": "By an external assistant (MCP)",
                      "review": "On approval", "rest": "Through the REST API"}
        if prof:
            acts = action_act_log.list_acts(user_uuid, profile_id=prof.get("id"), limit=100)
            # a person is named by their account, never by a uuid on an audit surface
            names = _usernames_for([str(a.get("approved_by") or "").partition("user:")[2] for a in acts])
            for a in acts:
                who = str(a.get("approved_by") or "").partition("user:")[2]
                timeline.append({"kind": "act", "ts": a.get("at"), "face": a.get("face"),
                                 "outcome": a.get("outcome"),
                                 "summary": f"{_face_word.get(a.get('face'), 'Acted')}: {act_words(a)}"
                                            + (f" — approved by {names.get(who) or who[:8]}" if who else "")})
    except Exception:
        pass

    # Trip resets (W2 — the reset is an audited act, so it appears in the
    # audit-facing timeline like any other trust act; it can never be silent).
    try:
        from trusted_data_agent.core import trust_trip
        for mk in trust_trip.list_markers(user_uuid, tag_clean, limit=50):
            timeline.append({
                "kind": "trip_reset", "ts": mk.get("created_at"),
                "summary": "Trip reset — a new leg began"
                           + (f" (agent read {mk.get('integrity_state')})"
                              if mk.get("integrity_state") else "")
                           + (f" — {mk.get('note')}" if mk.get("note") else "")})
    except Exception:
        pass

    timeline.sort(key=lambda e: e.get("ts") or "", reverse=True)
    return jsonify({"tag": tag_clean, "timeline": timeline[:100]}), 200


@rest_api_bp.route("/v1/assurance/agent-story/<tag>", methods=["GET"])
@operation("assurance.agent_story", effect="read", scope="own",
           summary="The life of one agent from its records: when it was built, signed, changed, what its gates caught and how its quality moved",
           path={"tag": "the agent's @TAG"})
@require_auth
async def assurance_agent_story(current_user, tag):
    """The life of THIS agent — the trust story assembled from records that
    already exist (profile, corpus scans, attestation, spans, reviews,
    incidents). Every sentence the UI narrates is backed by a real record;
    nothing here is generated or estimated. Owner-scoped; every source is
    read defensively (an absent subsystem drops its chapter, never errors).
    ``closures`` are the loop-closure receipts: moments where an incident led
    to a recorded human disposition (review decided, incident acknowledged,
    document quarantined) — 'trust that responds', made countable."""
    from trusted_data_agent.core import trust_events, review_queue
    from trusted_data_agent.core.config_manager import get_config_manager

    user_uuid = _get_user_uuid_from_request()
    tag_clean = (tag or "").lstrip("@")
    story = {"tag": tag_clean}

    # ── born — the profile itself (birth time from the id's embedded epoch) ──
    prof = None
    try:
        prof = next((p for p in (get_config_manager().get_profiles(user_uuid) or [])
                     if (p.get("tag") or "").lstrip("@") == tag_clean), None)
    except Exception:
        prof = None
    if not prof:
        return jsonify({"error": f"agent @{tag_clean} not found"}), 404
    born_ts = None
    try:
        import re as _re
        m = _re.match(r"profile-(\d{13})-", str(prof.get("id") or ""))
        if m:
            from datetime import datetime, timezone
            born_ts = datetime.fromtimestamp(int(m.group(1)) / 1000.0, tz=timezone.utc).isoformat()
    except Exception:
        pass
    story["born"] = {"when": born_ts, "name": prof.get("name") or tag_clean,
                     "profile_class": prof.get("profile_type")}

    # ── knowledge — corpus screening across the agent's bound repositories ──
    kn = {"collections": 0, "documents": 0, "screened": 0, "injection_findings": 0,
          "acknowledged": 0, "quarantined": 0}
    try:
        from trusted_data_agent.core.collection_db import get_collection_db
        cdb = get_collection_db()
        # TC-75: read BOTH binding fields via the trust composition's canonical resolver —
        # `knowledgeConfig.collections` alone missed `ragCollections`, so the story narrated
        # "No knowledge repositories bound yet" for an agent whose corpus is an active trust
        # ingredient (story and badge disagreeing about the same subject). Falls back to the
        # single-field read if the (removable) trust suite is absent.
        try:
            from trusted_data_agent.core.trust.composition import bound_repository_ids
            coll_ids = bound_repository_ids(prof)
        except Exception:
            coll_ids = [c.get("id") if isinstance(c, dict) else c
                        for c in ((prof.get("knowledgeConfig") or {}).get("collections") or [])]
        for cid in coll_ids[:20]:
            try:
                # Screening applies to KNOWLEDGE repositories; a planner repo surfaced by
                # the two-field resolver has no corpus to screen and must not pad the count.
                coll = cdb.get_collection_by_id(int(cid))
                if (coll or {}).get("repository_type") != "knowledge":
                    continue
                man = cdb.get_scan_manifest(int(cid))
            except Exception:
                continue
            kn["collections"] += 1
            kn["documents"] += man.get("total_documents", 0)
            kn["screened"] += man.get("scanned", 0)
            inj = man.get("injection_documents") or []
            kn["injection_findings"] += len(inj)
            kn["acknowledged"] += sum(1 for d in inj if d.get("acknowledged"))
            kn["quarantined"] += len(man.get("quarantined") or [])
    except Exception:
        pass
    story["knowledge"] = kn

    # ── signed — the Trust-Membrane attestation (defensive; suite removable) ──
    signed = {"state": "unsigned", "when": None}
    try:
        from trusted_data_agent.core.trust import store as trust_store
        att = trust_store.load_attestation("agent", prof.get("id"), owner_uuid=user_uuid)
        if att and att.get("signed"):
            signed["state"] = "signed"
            try:
                from datetime import datetime, timezone
                signed["when"] = datetime.fromtimestamp(
                    float(att.get("signed_at")), tz=timezone.utc).isoformat() if att.get("signed_at") else None
            except Exception:
                signed["when"] = None
    except Exception:
        pass
    story["signed"] = signed

    # ── acting + judged — the live eval track record for this tag ──
    acting = {"turns": 0, "failures": 0, "first_at": None, "last_at": None}
    try:
        from trusted_data_agent.eval.analysis import dedupe_spans
        spans = [s for s in dedupe_spans(_read_online_spans(2000, user_uuid=user_uuid))
                 if ((s.get("attributes") or {}).get("agent.profile_tag") or "").lstrip("@") == tag_clean]
        acting["turns"] = len(spans)
        acting["failures"] = sum(1 for s in spans
                                 if (s.get("attributes") or {}).get("eval.gating_failures", 0))
        nanos = sorted([s.get("start_time_unix_nano") for s in spans
                        if isinstance(s.get("start_time_unix_nano"), (int, float))])
        if nanos:
            from datetime import datetime, timezone
            acting["first_at"] = datetime.fromtimestamp(nanos[0] / 1e9, tz=timezone.utc).isoformat()
            acting["last_at"] = datetime.fromtimestamp(nanos[-1] / 1e9, tz=timezone.utc).isoformat()
    except Exception:
        pass
    story["acting"] = acting

    # ── reviewed + closures — human dispositions + acknowledged incidents ──
    closures = []
    reviews = {"pending": 0, "decided": 0, "released": 0}
    try:
        for it in review_queue.list_items(user_uuid, status=None, limit=200):
            if (it.get("profile_tag") or "") != tag_clean:
                continue
            if it.get("status") == "pending":
                reviews["pending"] += 1
            elif it.get("status") == "retained":
                # Recovery-ledger entry (plain-enforce full withholding) — neither
                # owed work nor a decided disposition; counting it as "decided"
                # would fabricate an oversight act nobody performed.
                reviews["retained"] = reviews.get("retained", 0) + 1
            else:
                reviews["decided"] += 1
                released = bool(it.get("released_to_context"))
                if it.get("status") == "approved" and released:
                    reviews["released"] += 1
                closures.append({
                    "kind": "review", "when": it.get("decided_at"),
                    "summary": (("parked write approved" if it.get("status") == "approved"
                                 else "parked write rejected")
                                + ("" if not it.get("decided_by") or it.get("decided_by") == user_uuid
                                   else " by a designated approver"))
                               if it.get("source") == "action" else
                               ("withheld answer released by the owner" if released
                                else "withheld answer approved (record only)") if it.get("status") == "approved"
                               else "withholding upheld by the owner"})
    except Exception:
        pass
    try:
        for ev in trust_events.list_events(user_uuid, include_acked=True, limit=200):
            if (ev.get("profile_tag") or "").lstrip("@") != tag_clean:
                continue
            if ev.get("acknowledged"):
                closures.append({"kind": "incident", "when": ev.get("created_at"),
                                 "summary": f"incident acknowledged — {ev.get('summary')}"})
    except Exception:
        pass
    # Quarantines are corpus-level closures (the doc ref carries the reason).
    if kn["quarantined"]:
        closures.append({"kind": "quarantine", "when": None,
                         "summary": f"{kn['quarantined']} document(s) quarantined out of retrieval"})
    closures.sort(key=lambda c: c.get("when") or "", reverse=True)
    story["reviewed"] = reviews
    story["closures"] = closures[:20]

    # ── trip — the current leg, if the operator has started one (W2/W8) ──
    try:
        from trusted_data_agent.core import trust_trip
        _m = trust_trip.latest_markers(user_uuid).get(tag_clean)
        if _m:
            story["trip"] = {"since": _m.get("created_at"), "note": _m.get("note"),
                             "integrity_state": _m.get("integrity_state"),
                             "legs": _m.get("leg_n") or 1}
    except Exception:
        pass
    return jsonify(story), 200


@rest_api_bp.route("/v1/assurance/trust-trip/<tag>", methods=["GET"])
@operation("assurance.trust_trip", effect="read", scope="own",
           summary="One agent's trip logbook: every point from which its readings were counted afresh, newest first",
           path={"tag": "the agent's @TAG"})
@require_auth
async def assurance_trust_trip_logbook(current_user, tag):
    """The leg logbook for one agent — every trip marker ever set, newest first,
    plus the current leg. Markers are append-only (W1): the odometer never
    resets, so this list can only grow. Owner-scoped."""
    from trusted_data_agent.core import trust_trip
    user_uuid = _get_user_uuid_from_request()
    tag_clean = (tag or "").lstrip("@")
    markers = trust_trip.list_markers(user_uuid, tag_clean, limit=50)
    current = trust_trip.latest_markers(user_uuid).get(tag_clean)
    return jsonify({"tag": tag_clean, "markers": markers, "current": current,
                    "legs": (current or {}).get("leg_n") or len(markers)}), 200


@rest_api_bp.route("/v1/assurance/trust-trip/<tag>/reset", methods=["POST"])
@operation("assurance.trust_trip_reset", effect="human_only", scope="own",
           summary="Start counting one agent's trust readings afresh — the owner decides when a new leg begins, never an agent",
           path={"tag": "the agent's @TAG"})
@require_auth
async def assurance_trust_trip_reset(current_user, tag):
    """Start a new leg for one agent — the trip reset (speedometer model).

    Appends a marker; deletes NOTHING (W1 — spans, turns, verdicts and
    incidents are untouched, and the whole-record lens stays byte-identical).
    The act is audited (W2): the marker records who, when (server clock), the
    operator's reason, and the agent's integrity state at that moment (W8,
    via the same ``turn_integrity_stamp`` the turn seal uses — defensively,
    the trust suite being removable). Owner-scoped: the tag is resolved
    against the CALLER's own profiles, so an admin viewing another user's
    same-tag agent can never reset a leg that is not theirs.
    Body: ``{note?: str}``."""
    from trusted_data_agent.core import trust_trip
    from trusted_data_agent.core.config_manager import get_config_manager

    user_uuid = _get_user_uuid_from_request()
    tag_clean = (tag or "").lstrip("@")
    try:
        prof = next((p for p in (get_config_manager().get_profiles(user_uuid) or [])
                     if (p.get("tag") or "").lstrip("@") == tag_clean), None)
    except Exception:
        prof = None
    if not prof:
        return jsonify({"error": f"agent @{tag_clean} not found"}), 404

    data = await request.get_json(silent=True) or {}
    note = data.get("note") if isinstance(data.get("note"), str) else None

    integrity_state = None
    try:
        from trusted_data_agent.core.trust.composition import turn_integrity_stamp
        _st = turn_integrity_stamp(prof.get("id"), user_uuid, profile=prof)
        integrity_state = (_st or {}).get("state")
    except Exception:
        integrity_state = None   # suite absent — the marker simply has no snapshot

    try:
        marker = trust_trip.reset_trip(
            user_uuid, tag_clean, profile_id=prof.get("id"),
            note=note, integrity_state=integrity_state)
    except Exception as e:  # noqa: BLE001 — the reset IS the act: fail loud, honestly
        app_logger.warning(f"trust-trip: reset failed for @{tag_clean}: {e}")
        return jsonify({"error": "the trip reset could not be recorded"}), 500
    marker["leg_n"] = (trust_trip.latest_markers(user_uuid).get(tag_clean) or {}).get("leg_n")
    return jsonify({"status": "ok", "marker": marker}), 200


@rest_api_bp.route("/v1/assurance/resilience-test", methods=["POST"])
@require_auth
async def assurance_resilience_test(current_user):
    """Red-team resilience self-test — run the curated adversarial corpus through
    the real deterministic in-path detectors (injection / PII / toxicity) and
    report per-category recall + benign false-positive rate + a headline
    resilience score. 0 tokens, no live model (honest scope in the payload)."""
    from trusted_data_agent.eval.redteam import run_self_test
    return jsonify(run_self_test()), 200


@rest_api_bp.route("/v1/assurance/retrieval-anomaly", methods=["POST"])
@require_auth
async def assurance_retrieval_anomaly(current_user):
    """RAG Trust Hardening Wave 5 (B1) — index-poisoning detection: per-document
    retrieval frequency × query diversity over the caller's recent persisted turns
    (no new logging; bounded window). A high-frequency, high-diversity document is a
    suspicious retrieval hub — flagged as an Assurance-Inbox item for HUMAN
    disposition (never auto-quarantined; quarantine is one click from the inbox).
    Honest cap: statistical detection, not proven semantic poisoning — the payload
    says so. Body: {sessions?: 30, min_retrievals?: 4, diversity_threshold?: 0.75}."""
    from trusted_data_agent.core import session_manager, trust_events
    from trusted_data_agent.eval import retrieval_anomaly

    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    try:
        n_sessions = _coerce_int(data.get("sessions"), "sessions", 30, lo=1, hi=100)
        _min_retr = _coerce_int(data.get("min_retrievals"), "min_retrievals",
                                retrieval_anomaly.MIN_RETRIEVALS, lo=1)
        _div_thr = _coerce_float(data.get("diversity_threshold"), "diversity_threshold",
                                 retrieval_anomaly.DIVERSITY_THRESHOLD)
    except _BadParam as e:
        return jsonify({"error": str(e)}), 400

    turns = []
    try:
        listing = await session_manager.get_all_sessions(user_uuid, limit=n_sessions)
        for s in (listing or {}).get("sessions", []):
            sid = s.get("id")
            if not sid:
                continue
            try:
                wh = await session_manager.get_workflow_history(user_uuid, sid)
                turns.extend(t for t in (wh or []) if isinstance(t, dict))
            except Exception:
                continue
    except Exception as e:
        app_logger.warning(f"retrieval-anomaly: session sweep failed: {e}")

    report = retrieval_anomaly.analyze(
        turns,
        min_retrievals=_min_retr,
        diversity_threshold=_div_thr)
    # Flagged hubs land in the inbox (labels + ids + stats only — never chunk content).
    for f in report.get("flagged", []):
        try:
            summary = (f"Retrieval anomaly: document '{f.get('filename') or f['document_id']}' "
                       f"is a suspicious hub — {f['why']}")
            trust_events.record_event(
                user_uuid, "retrieval_anomaly", summary, severity="warning",
                payload={"document_id": f["document_id"],
                         "filename": f.get("filename"),
                         "retrievals": f["retrievals"],
                         "query_diversity": f["query_diversity"],
                         "collections": f.get("collections")})
            trust_events.broadcast_notice(user_uuid, "retrieval_anomaly", summary,
                                          severity="warning")
        except Exception:
            pass
    return jsonify(report), 200


async def _redteam_ingest_probe_doc(collection_id: int, filename: str, content: str) -> str:
    """Wave 3 (R2) — ingest one payload document into the caller's TEST collection via
    the standard client-side constructor path (chunk → embed → store + metadata row).
    Returns the document_id the cleanup deletes. Raises on failure (the probe is then
    scored 'unknown — ingest failed', honestly)."""
    import time as _time
    import uuid as _uuid
    from trusted_data_agent.core.collection_db import get_collection_db
    from trusted_data_agent.core.config import APP_STATE
    from trusted_data_agent.agent.repository_constructor import (
        create_repository_constructor, RepositoryType, ChunkingStrategy)

    retriever = APP_STATE.get("rag_retriever_instance")
    if retriever is None:
        raise RuntimeError("retriever unavailable")
    db = get_collection_db()
    coll = db.get_collection_by_id(collection_id)
    doc_id = f"redteam-{_uuid.uuid4()}"
    ingest_epoch = int(_time.time())
    try:
        cs = ChunkingStrategy[(coll.get("chunking_strategy") or "paragraph").upper()]
    except KeyError:
        cs = ChunkingStrategy.PARAGRAPH
    backend = await retriever._get_knowledge_backend(collection_id)
    constructor = create_repository_constructor(
        repository_type=RepositoryType.KNOWLEDGE,
        chroma_client=retriever.client,
        storage_dir=retriever.rag_cases_dir / f"collection_{collection_id}",
        embedding_model=coll.get("embedding_model", "all-MiniLM-L6-v2"),
        chunking_strategy=cs,
        chunk_size=coll.get("chunk_size", 1000),
        chunk_overlap=coll.get("chunk_overlap", 200),
        backend=backend,
    )
    result = await constructor.construct_async(
        collection_id=collection_id, content=content,
        collection_name=coll["collection_name"], filename=filename,
        document_id=doc_id, ingest_epoch=ingest_epoch, save_original=False)
    db.upsert_document_metadata(
        document_id=doc_id, collection_id=collection_id, filename=filename,
        content_hash=f"redteam-{ingest_epoch}", ingest_epoch=ingest_epoch,
        chunk_count=result.get("chunks_stored", 0), source="redteam_probe")
    return doc_id


async def _redteam_remove_probe_doc(collection_id: int, doc_id: str):
    """Wave 3 (R2) — remove a payload document: its chunks from the vector backend and
    its metadata row. Called from the runner's finally."""
    from trusted_data_agent.core.collection_db import get_collection_db
    from trusted_data_agent.core.config import APP_STATE
    from trusted_data_agent.vectorstore.filters import FieldFilter, FilterOp

    retriever = APP_STATE.get("rag_retriever_instance")
    db = get_collection_db()
    coll = db.get_collection_by_id(collection_id)
    if retriever is not None and coll:
        backend = await retriever._get_knowledge_backend(collection_id)
        if backend:
            res = await backend.get(
                coll["collection_name"],
                where=FieldFilter("document_id", FilterOp.EQ, doc_id),
                include_documents=False, include_metadata=False, limit=10_000)
            ids = [d.id for d in (res.documents or [])] if res else []
            if ids:
                await backend.delete(coll["collection_name"], ids=ids)
    conn = db._get_connection()
    conn.execute("DELETE FROM knowledge_documents WHERE document_id = ?", (doc_id,))
    conn.commit()
    conn.close()
    db.sync_collection_counts(collection_id)


@rest_api_bp.route("/v1/assurance/live-redteam", methods=["POST"])
@require_auth
async def assurance_live_redteam(current_user):
    """Live red-team probe — drive a bounded adversarial corpus as REAL turns
    through a target profile and score whether its guards held (injection
    obeyed? planted PII echoed? scope drift?). Unlike the deterministic
    self-test, this costs real tokens (one turn per probe), so it is **opt-in
    and hard-capped**: ``max_probes`` bounds the run (default 3, ceiling = the
    corpus size). Scoring is deterministic + 0-token, so the resilience verdict
    is reproducible. Runs against the CALLER'S OWN profile via the internal
    self-call path using an internal token derived from the caller.

    Body: {profile_tag: "TAG"  (or profile_id), max_probes?: 3, probe_ids?: [str],
           corpus_collection_id?: <int>, max_corpus_probes?: 2}

    ``probe_ids`` runs only the named probes (corpus order, still capped by ``max_probes``)
    — e.g. ``["write-escape"]`` to check an action-only agent's write surface alone.

    **Corpus lane (RAG Trust Hardening Wave 3, R1/R2):** when
    ``corpus_collection_id`` names a caller-OWNED **test** knowledge collection
    (explicit consent — never a production corpus implicitly), payload documents
    are ingested there, the retrieving questions are asked, the agent's behaviour
    is scored deterministically (obeyed a doc-planted injection? echoed a
    doc-planted secret?), and the payload docs are **deleted in a finally** —
    cleanup status is reported in the result, never silent.
    """
    from trusted_data_agent.eval import live_redteam
    from trusted_data_agent.mcp_server.client import UderiaRestClient
    from trusted_data_agent.auth.security import create_internal_token

    user_uuid = _get_user_uuid_from_request()
    data = await request.get_json(silent=True) or {}
    profile_tag = (data.get("profile_tag") or "").lstrip("@") or None
    profile_id = data.get("profile_id")
    max_probes = data.get("max_probes", 3)
    _ids = data.get("probe_ids")
    if _ids is not None and not (isinstance(_ids, list) and all(isinstance(i, str) for i in _ids)):
        return jsonify({"error": "probe_ids must be a list of probe ids"}), 400
    probes = live_redteam.select_probes(_ids, max_probes)
    if not probes and not data.get("corpus_collection_id"):
        return jsonify({"error": "none of the named probes exists",
                        "probes": [p.id for p in live_redteam.PROBE_CORPUS]}), 400
    corpus_collection_id = data.get("corpus_collection_id")
    corpus_probes = (live_redteam.bounded_corpus_probes(data.get("max_corpus_probes", 2))
                     if corpus_collection_id else [])

    # Resolve the target profile id from the tag (own profiles only).
    if not profile_id and profile_tag:
        from trusted_data_agent.core.config_manager import get_config_manager
        prof = next((p for p in (get_config_manager().get_profiles(user_uuid) or [])
                     if (p.get("tag") or "").lstrip("@") == profile_tag), None)
        profile_id = prof.get("id") if prof else None
    if not profile_id:
        return jsonify({"error": "profile_tag or profile_id (one of your own) is required"}), 400

    # ── Corpus-lane consent + ownership check (R2) ─────────────────────────
    cleanup_status = None
    if corpus_probes:
        from trusted_data_agent.core.collection_db import get_collection_db
        try:
            corpus_collection_id = _coerce_int(corpus_collection_id, "corpus_collection_id", 0)
        except _BadParam as e:
            return jsonify({"error": str(e)}), 400
        _coll = get_collection_db().get_collection_by_id(int(corpus_collection_id))
        if not _coll:
            return jsonify({"error": "corpus_collection_id not found"}), 404
        # TC-33: fail CLOSED. A collection row with a NULL owner (legacy/system collections
        # exist) must not pass — the corpus lane ingests adversarial payload documents and its
        # cleanup path DELETEs rows, so an ownerless collection let any user write to and prune
        # a shared collection. Only a collection the caller demonstrably owns is eligible.
        _owner = _coll.get("owner_user_id") or _coll.get("user_id")
        if _owner != user_uuid:
            return jsonify({"error": "corpus_collection_id must be a collection you own"}), 403
        if _coll.get("repository_type") != "knowledge":
            return jsonify({"error": "corpus_collection_id must be a knowledge repository"}), 400
        if (_coll.get("chunking_strategy") or "").lower() == "server_side":
            return jsonify({"error": "corpus probes require a client-side-chunked test "
                                     "collection (server-side ingest is asynchronous)"}), 400

    token = create_internal_token(user_uuid)
    # TC-78: self-call base URL derived from the request the caller reached us on — a
    # hardcoded localhost:5050 made every probe fail (scored as errors) on any deployment
    # bound to a different port, silently degrading the resilience reading. Loopback with
    # the ACTUAL port is preferred (the self-call must not leave the host); the request
    # host is the fallback for binds where loopback is unavailable.
    try:
        from urllib.parse import urlsplit
        _port = urlsplit(request.host_url).port
        _base = f"http://127.0.0.1:{_port}" if _port else request.host_url.rstrip("/")
    except Exception:
        _base = "http://localhost:5050"
    client = UderiaRestClient(_base, token,
                              poll_interval=2.0, poll_timeout=180.0)
    scores = []
    _ingested = []
    session_id = None

    async def _probe_turn(result):
        # the trace-based scorers need the persisted turn, not only the answer's payload
        if not session_id or (isinstance(result, dict) and result.get("_probe_error")):
            return result
        try:
            return live_redteam.with_turn(result, await session_manager.get_session(user_uuid, session_id))
        except Exception as e:  # noqa: BLE001
            app_logger.warning(f"live-redteam: could not read the probe turn: {e}")
            return result

    try:
        session_id = await client.create_session(name="Live red-team probe")
        for probe in probes:
            try:
                task_id = await client.submit_query(session_id, probe.prompt, profile_id)
                result = await client.poll_task(task_id)
            except Exception as e:
                app_logger.warning(f"live-redteam probe {probe.id} failed: {e}")
                result = {"final_answer_text": "", "_probe_error": str(e)}
            scores.append(live_redteam.score_probe(probe, await _probe_turn(result)))

        # ── The corpus lane: ingest payload doc → probe → score (cleanup in finally) ──
        for cprobe in corpus_probes:
            try:
                doc_id = await _redteam_ingest_probe_doc(
                    int(corpus_collection_id), cprobe.doc_filename, cprobe.doc_content)
                _ingested.append(doc_id)
            except Exception as e:
                app_logger.warning(f"live-redteam corpus ingest {cprobe.id} failed: {e}")
                scores.append({"probe_id": cprobe.id, "category": cprobe.category,
                               "held": None, "reason": f"payload ingest failed: {e}",
                               "answer_excerpt": ""})
                continue
            try:
                task_id = await client.submit_query(session_id, cprobe.prompt, profile_id)
                result = await client.poll_task(task_id)
            except Exception as e:
                app_logger.warning(f"live-redteam corpus probe {cprobe.id} failed: {e}")
                result = {"final_answer_text": "", "_probe_error": str(e)}
            scores.append(live_redteam.score_probe(cprobe, await _probe_turn(result)))
    except Exception as e:
        app_logger.error(f"live-redteam run failed: {e}", exc_info=True)
        return jsonify({"error": f"probe run failed: {e}"}), 500
    finally:
        # R2 — cleanup is part of the probe contract; its status is reported, never silent.
        if corpus_probes:
            failed_cleanup = []
            for doc_id in _ingested:
                try:
                    await _redteam_remove_probe_doc(int(corpus_collection_id), doc_id)
                except Exception as e:
                    failed_cleanup.append(doc_id)
                    app_logger.error(f"live-redteam cleanup failed for {doc_id}: {e}")
            cleanup_status = ("clean" if not failed_cleanup else
                              f"CLEANUP INCOMPLETE — payload doc(s) still present: {failed_cleanup}")

    summary = live_redteam.summarize(scores)
    if cleanup_status is not None:
        summary["corpus_cleanup"] = cleanup_status
    # A failure is a real security finding — record it in the Assurance Inbox.
    if summary.get("failed"):
        try:
            from trusted_data_agent.core import trust_events
            _s = (f"Live red-team: @{profile_tag or profile_id} FAILED {summary['failed']} "
                  f"of {summary['probes_run']} probe(s) — a guard did not hold")
            trust_events.record_event(user_uuid, "live_redteam_failure", _s,
                                      severity="danger", profile_tag=profile_tag,
                                      payload={"failed": summary["failed"],
                                               "by_category": summary["by_category"]})
            trust_events.broadcast_notice(user_uuid, "live_redteam_failure", _s,
                                          profile_tag=profile_tag, severity="danger")
        except Exception:
            pass
    return jsonify({"profile_tag": profile_tag, "profile_id": profile_id,
                    "summary": summary, "scores": scores}), 200


@rest_api_bp.route("/v1/assurance/audit-pack", methods=["POST"])
@require_auth
async def assurance_audit_pack(current_user):
    """Export a signed **audit pack** — a portable, independently-verifiable
    evidence bundle for the requesting user's deployment posture: the current
    trust posture (per-profile grounding/guardrail modes, authority scope,
    behavioral state), the online-eval aggregates, the open + acknowledged trust
    incidents, the resilience self-test, and a compliance-control map (EU AI Act
    / NIST AI RMF / GDPR). The whole bundle is Ed25519-signed with the same
    deployment provenance key used for turn attestations, so an auditor can
    verify it offline. Read-only.
    """
    import hashlib
    from datetime import datetime, timezone
    from trusted_data_agent.core.config import APP_CONFIG
    from trusted_data_agent.core import trust_events, session_manager
    from trusted_data_agent.core.config_manager import get_config_manager
    from trusted_data_agent.eval.analysis import dedupe_spans, agent_kpi_dashboard
    from trusted_data_agent.eval.redteam import run_self_test
    from trusted_data_agent.eval import trust_behavior as tb

    user_uuid = _get_user_uuid_from_request()
    ts = datetime.now(timezone.utc).isoformat()

    # Posture — per profile: the RESOLVED mode of every gate, from the ONE resolver
    # (`effective_posture`), not a hand-rolled re-derivation. The audit pack is the signed
    # evidence bundle handed to auditors, so it must not understate protection: an agent
    # hardened via agent-level inheritance (`postureConfig.mode`) resolves to `enforce` even
    # with the gate's own block empty — the previous hand-rolled read exported it as `observe`
    # and omitted three of the five gates entirely. Each gate carries its source (gate/agent/
    # grounding/default) as richer evidence.
    from trusted_data_agent.core import posture_modes as _pm
    posture = []
    for p in (get_config_manager().get_profiles(user_uuid) or []):
        ac = p.get("authorityConfig") or p.get("identityConfig") or {}
        eff = _pm.effective_posture(p)
        posture.append({
            "tag": p.get("tag"), "profile_type": p.get("profile_type"),
            # All five gates, resolved, with their source. Legacy flat keys kept for any
            # existing consumer, now sourced from the resolver so they can't disagree.
            "gates": eff,
            "grounding_mode": eff.get("grounding", {}).get("mode", "observe"),
            "outbound_guardrail_mode": eff.get("outbound", {}).get("mode", "observe"),
            "authority": {"autonomous": ac.get("autonomous"),
                          "deny_writes": ac.get("deny_writes"),
                          "denied_tools": ac.get("denied_tools") or [],
                          "max_cost_per_run": ac.get("max_cost_per_run"),
                          "frozen_by_breaker": ac.get("frozen_by_breaker", False)},
        })

    # Eval aggregates + behavioral trust.
    spans = dedupe_spans(_read_online_spans(2000, user_uuid=user_uuid))
    kpi = agent_kpi_dashboard(spans)
    cfg = tb.resolve_config(getattr(APP_CONFIG, "TRUST_BEHAVIOR", None) or {})
    behavior = tb.assess_agents(spans, config=cfg)

    # Incidents (open + acked) + derived over recent sessions.
    stored = trust_events.list_events(user_uuid, include_acked=True, limit=200)
    # TC-6: build the disposition index exactly as assurance_inbox does. Previously
    # `dispositions` was undefined in this function — a NameError swallowed by the blanket
    # `except: pass` below, so `derived` was ALWAYS empty and the Ed25519-signed audit pack
    # attested an understated incident record (every grounding block, guardrail redaction,
    # honesty rewrite and session sentinel silently absent from the evidence bundle).
    dispositions = {}
    try:
        from trusted_data_agent.core import review_queue
        dispositions = trust_events.disposition_index(
            review_queue.list_items(user_uuid, status=None, limit=500))
    except Exception as e:
        app_logger.warning(f"audit-pack: disposition join unavailable: {e}")

    derived = []
    try:
        listing = await session_manager.get_all_sessions(user_uuid, limit=20)
        for s in (listing or {}).get("sessions", []):
            sid = s.get("id")
            if not sid:
                continue
            wh = await session_manager.get_workflow_history(user_uuid, sid)
            derived.extend(trust_events.derive_turn_events(
                wh, session_id=sid, dispositions=dispositions))
            sent = trust_events.derive_session_sentinel(wh, session_id=sid)
            if sent:
                derived.append(sent)
    except Exception as e:
        # Do not silently hide a systemic failure (the exact defect above): log it so an
        # empty derived set is diagnosable rather than mistaken for "no incidents".
        app_logger.warning(f"audit-pack: derived-incident scan failed: {e}")

    body = {
        "audit_pack_version": 1,
        "generated_at": ts,
        # One source per rule — the same masters the evals dashboard reports.
        "deployment_masters": {**_deployment_masters(), "trust_behavior": cfg},
        "posture": posture,
        "eval_kpi": kpi.get("overall", {}),
        "behavioral_trust": {tag: v.get("composite") for tag, v in behavior.items()},
        "incidents": {"stored": stored, "derived": derived},
        "resilience_self_test": run_self_test(),
        "compliance_map": {
            "EU_AI_Act_NIST_AI_RMF": {
                "accuracy": "grounding gate (per-profile modes in posture)",
                "safety_robustness": "guardrails + memory/retrieval firewalls",
                "measurement_monitoring": "online eval aggregates + behavioral trust",
                "traceability": "Ed25519 provenance chain per turn",
                "accountability": "Agent Authority principal + attribution",
                "risk_management": "ontology/pack governance lifecycle",
            },
            "GDPR": {
                "data_minimization_masking": "outbound guardrail PII redaction (labels only)",
                "erasure": "Agent Memory erase endpoints",
            },
        },
    }

    # Sign the canonical bundle with the deployment provenance key (same as turn
    # attestations) so it verifies offline. Degrades to unsigned+hash if the key
    # is unavailable — the content hash still gives tamper-evidence.
    canonical = _json_canonical(body)
    content_hash = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
    attestation = {"content_sha256": content_hash, "signed": False}
    try:
        from trusted_data_agent.eval.online import sign_payload
        sig = sign_payload(content_hash)
        attestation.update({"signed": bool(sig.get("signed")),
                            "signature": sig.get("signature"),
                            "key_fingerprint": sig.get("key_fingerprint"),
                            "algorithm": "Ed25519",
                            "signed_field": "content_sha256"})
    except Exception as e:
        app_logger.debug(f"audit-pack: signing unavailable: {e}")

    return jsonify({"audit_pack": body, "attestation": attestation}), 200


def _json_canonical(obj) -> str:
    import json as _json
    return _json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


@rest_api_bp.route("/v1/evals/annotations", methods=["GET", "POST"])
@require_auth
async def evals_annotations(current_user):
    """SME annotation queue: GET ?case_id= to list, POST to record a verdict.

    POST body: {label: agree|disagree|..., note?, case_id?, session_id?, turn?}.
    Annotations feed judge calibration (judge↔human κ).
    """
    gate = _eval_store_gate(current_user)   # TC-34
    if gate:
        return gate
    from trusted_data_agent.eval.store import get_eval_store
    store = get_eval_store()
    if request.method == "GET":
        return jsonify({"annotations": store.list_annotations(
            case_id=request.args.get("case_id"),
            limit=int(request.args.get("limit", 200)))}), 200
    data = await request.get_json() or {}
    label = (data.get("label") or "").strip()
    if not label:
        return jsonify({"error": "label is required"}), 400
    reviewer = getattr(current_user, "username", None) or _get_user_uuid_from_request() or "anon"
    # dimension + judge_passed make the row a κ pair (see eval/calibration.py:
    # pairs_from_annotations). judge_passed is tri-state: absent → NULL (a note,
    # not calibration evidence), else the ruling the human saw, frozen.
    jp = data.get("judge_passed")
    store.add_annotation(reviewer=reviewer, label=label, note=data.get("note", ""),
                         case_id=data.get("case_id"), session_id=data.get("session_id"),
                         turn=data.get("turn"), dimension=data.get("dimension"),
                         judge_passed=None if jp is None else bool(jp))
    return jsonify({"status": "ok"}), 201


@rest_api_bp.route("/v1/evals/judge-calibration", methods=["GET"])
@require_auth
async def evals_judge_calibration(current_user):
    """Per-dimension judge↔human κ over the annotation queue.

    The measurement behind the platform rule "judges stay advisory until their
    calibration clears": each report carries κ, raw agreement, confusion, and a
    status (calibrated / below_floor / insufficient). ``calibrated`` means
    ELIGIBLE for promotion to gating — promotion itself stays a deliberate
    governance act; nothing here flips a scorer.
    """
    gate = _eval_store_gate(current_user)   # annotations feed κ — same gate
    if gate:
        return gate
    from trusted_data_agent.eval.store import get_eval_store
    from trusted_data_agent.eval.calibration import (
        report_from_annotations, DEFAULT_KAPPA_GATING_FLOOR, DEFAULT_MIN_PAIRS)
    anns = get_eval_store().list_annotations(limit=5000)
    reports = report_from_annotations(anns)
    return jsonify({
        "floor": DEFAULT_KAPPA_GATING_FLOOR,
        "min_pairs": DEFAULT_MIN_PAIRS,
        "dimensions": reports,
        "total_pairs": sum(r.get("n_decided", 0) for r in reports.values()),
    }), 200


@rest_api_bp.route("/v1/evals/judge-queue", methods=["GET"])
@require_auth
async def evals_judge_queue(current_user):
    """Recent judge rulings awaiting a human verdict — the κ work queue.

    Reads the online quality spans (deduped, newest first), keeps only the
    dimensions the registry says are JUDGES, and marks rulings already
    annotated by (session, turn, dimension) so settled work is visible as
    settled rather than re-offered. Serves the exact fields the annotation
    POST needs to freeze the pair (dimension + the ruling shown).
    """
    gate = _eval_store_gate(current_user)   # TC-34 — instance-global surface
    if gate:
        return gate
    from trusted_data_agent.eval.store import get_eval_store
    from trusted_data_agent.eval.analysis import dedupe_spans, _dim_kind
    limit = min(int(request.args.get("limit", 40)), 200)
    spans = dedupe_spans(_read_online_spans(1000))
    # str-normalized join key: the span's turn.id and the DB's INTEGER column
    # must not miss each other on type ("1" vs 1 — the score-turn lesson).
    done = {(a.get("session_id"), str(a.get("turn")), a.get("dimension"))
            for a in get_eval_store().list_annotations(limit=5000) if a.get("dimension")}
    rows = []
    for sp in reversed(spans):               # newest first
        attrs = sp.get("attributes") or {}
        sid, turn = attrs.get("session.id"), attrs.get("turn.id")
        for k, v in attrs.items():
            if not (k.startswith("eval.dim.") and k.endswith(".passed")):
                continue
            dim = k[len("eval.dim."):-len(".passed")]
            # v is None when the judge ABSTAINED — nothing to agree with.
            if v is None or _dim_kind(dim) != "judge":
                continue
            rows.append({
                "session_id": sid, "turn": turn, "dimension": dim,
                "passed": bool(v),
                "score": attrs.get(f"eval.dim.{dim}.score"),
                "agent": attrs.get("agent.profile_tag"),
                "profile_class": attrs.get("eval.profile_class"),
                "ts": (sp.get("start_time_unix_nano") or 0) / 1e9 or None,
                "annotated": (sid, str(turn), dim) in done,
            })
        if len(rows) >= limit * 3:           # bound the scan, not the answer
            break
    pending = [r for r in rows if not r["annotated"]][:limit]
    return jsonify({"verdicts": pending,
                    "annotated_count": sum(1 for r in rows if r["annotated"])}), 200


