@rest_api_bp.route("/v1/scheduled-tasks", methods=["GET"])
@operation("scheduled_tasks.list", effect="read", scope="own",
           summary="The caller's scheduled tasks — questions an agent answers on a timer — with each one's schedule in words and its next runs",
           query={"profile_id": "only one agent's tasks"},
           summary_fields=("id", "name", "schedule", "enabled", "profile_id"))
@require_auth
async def list_scheduled_tasks(current_user):
    """List scheduled tasks for the current user. Optional ?profile_id= filter."""
    try:
        from trusted_data_agent.core.task_scheduler import list_tasks
        try:
            from components.builtin.scheduler.handler import _next_runs, _human_schedule
        except ImportError:  # the Scheduler component is enterprise; the engine's tasks still list
            def _human_schedule(schedule):
                return schedule

            def _next_runs(schedule, n=5, task_id=None):
                return []
        user_uuid = current_user.id
        profile_id = request.args.get("profile_id")
        tasks = list_tasks(user_uuid, profile_id=profile_id)
        for t in tasks:
            t["_human_schedule"] = _human_schedule(t.get("schedule", ""))
            t["_next_runs"] = _next_runs(t.get("schedule", ""), n=5, task_id=t.get("id")) if t.get("schedule") else []
            t["_session_context"] = "current" if t.get("session_id") else "new"
        return jsonify({"tasks": tasks}), 200
    except Exception as e:
        app_logger.error(f"Failed to list scheduled tasks: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@rest_api_bp.route("/v1/scheduled-tasks", methods=["POST"])
@operation("scheduled_tasks.create", effect="write", scope="own", governs=True,
           summary="Schedule a question for one of the caller's agents to answer on a timer, on its own",
           body={"name": Arg("string", "its name", required=True),
                 "profile_id": Arg("string", "the agent that answers it", required=True),
                 "prompt": Arg("string", "the question, as the agent will receive it each time", required=True),
                 "schedule": Arg("string", "a 5-field cron ('0 9 * * 1-5' = weekdays at 09:00) or an interval ('interval:30m', 'interval:2h', 'interval:1d')", required=True),
                 "max_tokens_per_run": Arg("integer", "a run past this many tokens is recorded as an error"),
                 "overlap_policy": Arg("string", "when the previous run is still going: skip it, queue it, or allow both",
                                       enum=("skip", "queue", "allow"))},
           notes="Standing authority to act and spend without being asked, so a person always approves it. Results "
                 "stay in the user's sessions; sending them by email or webhook is the owner's to set.")
@require_auth
async def create_scheduled_task(current_user):
    """Create a new scheduled task."""
    try:
        from trusted_data_agent.core.task_scheduler import create_task
        # Was `is_scheduler_globally_enabled()` — a hand-rolled copy of the global half
        # that missed the per-user admin override. One predicate now, same as every other
        # component surface.
        from trusted_data_agent.components.settings import is_component_available
        if not is_component_available("scheduler", current_user.id):
            return jsonify({"error": "Task Scheduler component is disabled for your account",
                            "code": "component_not_available"}), 403

        data = await request.get_json() or {}
        # a scheduled ACTION (PROP-008 §6) carries action_spec and needs no prompt
        required = (["name", "schedule", "profile_id"] if data.get("action_spec")
                    else ["name", "prompt", "schedule", "profile_id"])
        missing = [f for f in required if not data.get(f)]
        if missing:
            return jsonify({"error": f"Missing required fields: {', '.join(missing)}"}), 400

        task = create_task(
            user_uuid=current_user.id,
            profile_id=data["profile_id"],
            name=data["name"],
            prompt=data.get("prompt") or "",
            schedule=data["schedule"],
            output_channel=data.get("output_channel"),
            output_config=data.get("output_config"),
            max_tokens_per_run=data.get("max_tokens_per_run"),
            overlap_policy=data.get("overlap_policy", "skip"),
            action_spec=data.get("action_spec") or None,
        )
        return jsonify({"task": task}), 201
    except ValueError as e:
        # PROP-008 §6 — a scheduled action its agent may not perform (ActionTaskError)
        from trusted_data_agent.core.task_scheduler import ActionTaskError
        if isinstance(e, ActionTaskError):
            return jsonify({"error": e.code, "message": str(e)}), 400
        app_logger.error(f"Failed to create scheduled task: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500
    except Exception as e:
        app_logger.error(f"Failed to create scheduled task: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


